const SUPA = Deno.env.get("SUPABASE_URL")!;
const SERVICE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
// KC-CLUB-DB-ZEITGRENZE (2.23.11, Ausfall 04.10. 3:55–5:40 Uhr: Anfragen hingen bis 150 s): jede Datenbank-Abfrage (REST/RPC)
// bricht nach DB_ZEIT_MS ab. Ist während einer Anfrage eine Abfrage hängen geblieben, antwortet der Server mit 503 – nie mit einem
// halben Ergebnis (UNKNOWN ≠ OK) – und die App schaltet schneller auf Notbetrieb/gespeicherten Stand. Speicher (Dateien) unverändert.
const DB_ZEIT_MS = 15000;
const DB_AUS = { n: 0 }; // zählt abgebrochene Abfragen (je Anfrage vorher/nachher verglichen)
// KC-CLUB-NOTPAKET-PUFFER (2.453.0, Prüfbericht 18.10.2026): Ein Bau des Notfall-Pakets las ~5.000× aus der Datenbank, 54 % davon exakt
// doppelt (dieselben Mitglieder-, Rechte- und Chat-Abfragen für jedes Mitglied). Innerhalb eines Notpaket-Teils (nur lesend) wird jede
// gleiche Leseabfrage nur einmal gestellt und die Antwort wiederverwendet. Der Puffer gilt NUR innerhalb dieses Aufrufs (AsyncLocalStorage:
// gleichzeitige andere Anfragen sehen ihn nie), lebt nur so lange wie der Aufruf und wird bei jedem Schreiben geleert. Fehler werden nie gepuffert.
type DbAntwort = { status: number; statusText: string; headers: [string, string][]; body: ArrayBuffer | null };
// KC-CLUB-DB-SPARSAM (2.464.0): haltbarMs > 0 → eine gepufferte Antwort gilt nur so lange (normale App-Aufrufe); 0 → den ganzen Aufruf (Notpaket-Teil, nur lesend).
type DbPuffer = { antworten: Map<string, Promise<DbAntwort>>; zeit: Map<string, number>; netz: number; puffer: number; haltbarMs: number; aktion?: string; treffer?: Map<string, number> };
const dbPufferNeu = (haltbarMs: number): DbPuffer => ({ antworten: new Map(), zeit: new Map(), netz: 0, puffer: 0, haltbarMs });
// Schreibt etwas außerhalb der Schnittstelle (andere Server-Funktion, direkter Datenbank-Weg), muss der Puffer des Aufrufs weg – nie veraltet lesen.
const dbPufferLeeren = () => { const pf = DB_PUFFER.getStore() as DbPuffer | undefined; if (pf) { pf.antworten.clear(); pf.zeit.clear(); } };
// Nur lesende Datenbank-Funktionen (STABLE bzw. reines SELECT, geprüft 18.10.2026): gehen ungepuffert durch, leeren den Puffer aber nicht.
// Jede andere Funktion gilt vorsichtshalber als Schreiben. (Messung 2.453.0: diese drei leerten den Puffer mehrmals je Mitglied → nur 2 % gespart.)
const DB_RPC_NUR_LESEN = new Set(["kc_club_rt_kanal", "kc_club_ungelesen_je_chat", "kc_communication_get_server_secret", "kc_club_kachel_zahlen", "kc_club_chat_stand",
  // 2.602.0 KC-CLUB-START-KERN: auch die Pakete sind STABLE (Postgres verbietet darin jedes Schreiben) – sie leerten bisher bei jedem Start den Puffer
  "kc_club_start_kern", "kc_club_start_paket", "kc_club_unterhaltung_paket", "kc_club_comm_paket", "kc_club_buero_paket", "kc_club_online_jetzt", "kc_club_nachricht_mahnung", "kc_club_unterhaltungen_paket"]); // 2.496.0: Kachel-Zahlen · 2.510.0: Chat-Fingerabdruck (beide STABLE, nur lesend)
const dbFetch: typeof fetch = (input, init) => {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  const pf = url.includes("/rest/v1/") ? DB_PUFFER.getStore() as DbPuffer | undefined : undefined;
  if (!pf) return dbFetchNetz(input, init);
  const ri = init as RequestInit | undefined;
  const methode = String(ri?.method || (input instanceof Request ? input.method : "GET")).toUpperCase();
  if (methode !== "GET" && methode !== "HEAD") {
    const rpc = /\/rest\/v1\/rpc\/([a-z0-9_]+)/.exec(url)?.[1];
    if (!(methode === "POST" && rpc && DB_RPC_NUR_LESEN.has(rpc))) { pf.antworten.clear(); pf.zeit.clear(); }
    pf.netz++; return dbFetchNetz(input, init);
  }
  const h = new Headers(ri?.headers ?? (input instanceof Request ? input.headers : undefined));
  const schluessel = [methode, url, h.get("accept"), h.get("prefer"), h.get("range"), h.get("accept-profile")].join("|");
  let a = pf.antworten.get(schluessel);
  if (a && pf.haltbarMs && Date.now() - (pf.zeit.get(schluessel) ?? 0) > pf.haltbarMs) a = undefined;
  if (a) { pf.puffer++; if (pf.treffer) pf.treffer.set(schluessel, (pf.treffer.get(schluessel) || 0) + 1); }
  else {
    pf.netz++;
    a = dbFetchNetz(input, init).then(async (r) => {
      const body = methode === "HEAD" ? null : await r.arrayBuffer();
      if (!r.ok) pf.antworten.delete(schluessel);
      return { status: r.status, statusText: r.statusText, headers: [...r.headers], body };
    });
    pf.antworten.set(schluessel, a); pf.zeit.set(schluessel, Date.now());
    a.catch(() => pf.antworten.delete(schluessel));
  }
  return a.then((x) => new Response(x.body && x.body.byteLength ? x.body.slice(0) : null, { status: x.status, statusText: x.statusText, headers: x.headers }));
};
const dbFetchNetz: typeof fetch = (input, init) => {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  if (!url.includes("/rest/v1/")) return fetch(input, init);
  const zeit = AbortSignal.timeout(DB_ZEIT_MS), ri = init as RequestInit | undefined;
  // KC-CLUB-START-SPARSAM-2: Schreiben in eine gemerkte Tabelle → Merker dieser Instanz vorher UND nachher leeren (nie veraltet nach eigenem Speichern)
  const schreibt = !["GET", "HEAD"].includes(String(ri?.method || (input instanceof Request ? input.method : "GET")).toUpperCase());
  if (schreibt) merkerVergessen(url);
  const r = fetch(input, { ...ri, signal: ri?.signal ? AbortSignal.any([ri.signal, zeit]) : zeit }).catch((e) => {
    if (zeit.aborted) { DB_AUS.n++; console.error("DB-Zeitgrenze", DB_ZEIT_MS, "ms"); }
    throw e;
  });
  return schreibt ? r.finally(() => merkerVergessen(url)) : r;
};
// KC-CLUB-START-SPARSAM-2 (Server 2.494.0, Stufe 2 „App-Start sparsamer“, Freigabe Hansi): Club-Einstellungen, Wartung, Freigaben,
// Zustand KC Communicator und Namen ändern sich selten, wurden aber bei JEDEM App-Start neu gefragt. Jetzt je Server-Instanz MERK_MS lang gemerkt.
// Speichert diese Instanz selbst etwas in einer dieser Tabellen, ist der Merker sofort weg; andere Instanzen sehen es spätestens nach MERK_MS.
const MERK_MS = 60_000;
function merkerVergessen(url: string) {
  const t = /\/rest\/v1\/([a-z0-9_]+)/.exec(url)?.[1];
  if (t === "kc_club_konfig") { KONFIG_MERK.clear(); KONFIG_STAND++; }
  else if (t === "kc_core_app_registry") WARTUNG_MERK = null;
  else if (t === "kc_club_funktion_freigabe") FREIGABE.bis = 0;
  else if (t === "kc_club_terminumfragen") LIVE_KURZ = null;
  else if (t === "kc_club_treffen") TREFFEN_MERK.clear();
}
// KC-CLUB-START-SPARSAM-2 (Server 2.495.0, Stufe 2 Punkt 3): Clubtermine (nur die Termin-Zeilen, nie Zu-/Absagen) für den App-Start MERK_MS lang
// gemerkt – das nächste Treffen und die kommenden Treffen für die Kachel-Zahl. Zu-/Absagen bleiben frisch. Speichern eines Termins leert den Merker.
const TREFFEN_MERK = new Map<string, { t: number; v: Promise<{ data: any; error: any }> }>();
function treffenGemerkt(k: string, lesen: () => PromiseLike<{ data: any; error: any }>): Promise<{ data: any; error: any }> {
  const m0 = TREFFEN_MERK.get(k);
  if (!m0 || Date.now() - m0.t > MERK_MS) {
    const m = { t: Date.now(), v: Promise.resolve(lesen()).then((r) => { if (r.error && TREFFEN_MERK.get(k) === m) TREFFEN_MERK.delete(k); return r; },
      (e) => { if (TREFFEN_MERK.get(k) === m) TREFFEN_MERK.delete(k); throw e; }) };
    TREFFEN_MERK.set(k, m);
  }
  return TREFFEN_MERK.get(k)!.v.then((r) => ({ data: r.data == null ? r.data : structuredClone(r.data), error: r.error }));
}
const dbWeg = () => json({ error: "Die Datenbank antwortet gerade nicht – bitte gleich noch einmal versuchen.", db: "weg" }, 503);
const db = createClient(SUPA, SERVICE, { auth: { persistSession: false, autoRefreshToken: false }, global: { fetch: dbFetch } });

const SERVER_VERSION = "2.614.0";
const TEMPO_LOG_MS = 1500; // KC-CLUB-TEMPO: ab hier landet ein Vorgang im Server-Log
const SS_FRIST_MS = 3 * 60000, SS_MAX_ZEICHEN = 2_000_000, SS_LIVE_MS = 30 * 60000; // 2.103.0: Live-Mitschauen; 2.136.0 KC-CLUB-STUDIO (Wunsch Hansi): 30 statt 10 Min.
// KC-CLUB-STUDIO (2.136.0, Wunsch Hansi): 🎬 Studio – Foto, Mitschauen, Live zeigen an einem Platz.
// Rechte (kc_club_person_einstellung „studio_recht“, setzt nur der Admin): zeigen = dauerhaft „📺 Live zeigen“; alles_bis = für kurze Zeit
// auch Foto + Mitschauen. Der Admin hat immer alles. Das andere Mitglied wird IMMER gefragt und kann jederzeit beenden.
const STUDIO_MS = 30 * 60000, STUDIO_ALLES_MIN = [30, 60, 120, 480];
// KC-CLUB-FERNHILFE F1: Live-Bild und Zeiger gehen über einen geheimen Broadcast-Kanal je Sitzung, jede Nachricht mit AES-GCM verschlüsselt –
// nicht mehr über die Datenbank. Kanal + Schlüssel bekommen nur die beiden Beteiligten (mit der Zusage bzw. beim Abholen). Der Server bleibt für
// Zustimmung, Dauer und Ende zuständig. Rückweg: FH_BROADCAST = false → alter Weg (Bild über kc_club_person_einstellung).
const FH_BROADCAST = true;
const fhNeu = () => { const b = crypto.getRandomValues(new Uint8Array(48)); let s = ""; for (const x of b.subarray(16)) s += String.fromCharCode(x);
  return { kanal: "kc-fh-" + [...b.subarray(0, 16)].map((x) => x.toString(16).padStart(2, "0")).join(""), schluessel: btoa(s) }; };
// Messwerte einer Sitzung (nur Zahlen) fürs Protokoll – Grundlage für die Grenzen der Fernhilfe
const fhMess = (m: any) => { const z = (v: any) => Math.max(0, Math.min(1e9, Math.round(Number(v) || 0))); return m && typeof m === "object" ? { n: z(m.n), kb: z(m.kb), max_kb: z(m.max_kb), befehle: z(m.befehle), voll: z(m.voll), aend: z(m.aend), weg: m.weg === "broadcast" ? "broadcast" : "server" } : null; };
type StudioStufe = "zeigen" | "alles" | null;
function studioAusWert(w: any): { stufe: StudioStufe; zeigen: boolean; allesBis: string | null } {
  const zeigen = w?.zeigen === true, allesBis = w?.alles_bis && Date.now() < new Date(w.alles_bis).getTime() ? String(w.alles_bis) : null;
  return { stufe: allesBis ? "alles" : zeigen ? "zeigen" : null, zeigen, allesBis };
}
async function studioStufe(ich: { person_id: string; admin: boolean }): Promise<StudioStufe> {
  if (ich.admin) return "alles";
  const { data } = await db.from("kc_club_person_einstellung").select("wert").eq("person_id", ich.person_id).eq("schluessel", "studio_recht").maybeSingle();
  return studioAusWert(data?.wert).stufe;
}
async function studioDarf(ich: { person_id: string; admin: boolean }, was: "zeigen" | "alles") {
  const st = await studioStufe(ich);
  if (!st || (was === "alles" && st !== "alles")) throw new Fehler(was === "alles" ? "Foto und Mitschauen sind für dich gerade nicht freigeschaltet." : "Das Studio ist für dich nicht freigeschaltet.", 403);
}
// Ein Live-Bild = der sichtbare Inhalt der Club-App (gepackt), kein Foto – geprüft wird nur Form und Größe; angezeigt wird es beim Empfänger
// in einem abgeschotteten Rahmen ohne Skripte.
function studioFrame(f: any) {
  if (!f || typeof f !== "object") return null;
  const zahl = (v: any, min: number, max: number) => Number.isFinite(Number(v)) ? Math.max(min, Math.min(max, Math.round(Number(v)))) : min;
  if (f.vorhang === true) return { vorhang: true, am: jetzt() };
  const d = String(f.d || "");
  if (!d || d.length > SS_MAX_ZEICHEN || !/^[A-Za-z0-9+/=]+$/.test(d)) throw new Fehler("Das Live-Bild ist zu groß oder ungültig.", 400);
  const t = f.tipp && Number.isFinite(Number(f.tipp.x)) && Number.isFinite(Number(f.tipp.y)) ? { x: Math.max(0, Math.min(1, Number(f.tipp.x))), y: Math.max(0, Math.min(1, Number(f.tipp.y))), n: zahl(f.tipp.n, 0, 1e9) } : null;
  return { d, z: f.z === "gzip" ? "gzip" : "roh", w: zahl(f.w, 200, 4000), h: zahl(f.h, 200, 4000), tipp: t, am: jetzt() };
}
// Beenden = Bild sofort vom Server löschen (KC-CLUB-MITSCHAUEN)
async function ssBeenden(pid: string, w: any) {
  await db.from("kc_club_person_einstellung").update({ wert: { id: w.id, von: w.von, status: "beendet", seit: w.seit, am: jetzt() }, geaendert_am: jetzt() }).eq("person_id", pid).eq("schluessel", "schnappschuss");
} // KC-CLUB-SCHNAPPSCHUSS: 3 Min. zum Antworten, Bild höchstens ~1,5 MB
