const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json", "Cache-Control": "no-store" } });
class Fehler extends Error { constructor(msg: string, public status = 400) { super(msg); } }
// KC-CLUB-RC-PRUEFUNG (20.10.2026): Schreiben mit Rückmeldung – schlägt es fehl, meldet die App das ehrlich statt „gespeichert“ (Freigaben, Notfall, Zusagen, Links)
function schreibOk<R extends { error: unknown }>(r: R, was = "Speichern"): R { if (r?.error) throw new Fehler(`${was} hat nicht geklappt – bitte gleich noch einmal versuchen.`, 500); return r; }
// KC-CLUB-RC-PRUEFUNG (20.10.2026): Arbeit nebenbei (ohne zu warten) – EdgeRuntime.waitUntil hält die Funktion wach, bis sie fertig ist
function nebenbei(p: Promise<unknown>) { try { (globalThis as any).EdgeRuntime?.waitUntil?.(p); } catch {} return p; }

// ---------- Hilfen ----------
async function sha256(s: string) {
  const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(b)].map((x) => x.toString(16).padStart(2, "0")).join("");
}
// 2.430.0 KC-CLUB-KALENDER-EINFACH: Kalender-Link aus dem Server-Geheimnis abgeleitet (nicht gespeichert, nur sein Hash)
async function kalenderToken(pid: string, erstellt: string) {
  const k = await crypto.subtle.importKey("raw", new TextEncoder().encode("kc-kalender|" + SERVICE), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const b = new Uint8Array(await crypto.subtle.sign("HMAC", k, new TextEncoder().encode(`${pid}|${new Date(erstellt).toISOString()}`)));
  return [...b.slice(0, 24)].map((x) => x.toString(16).padStart(2, "0")).join("");
}
// ---------- KC-CLUB-KURZCODE (1.87.0, Wunsch Hansi: Installation ohne langen Link) ----------
// 6-stelliger Code (15 Min., einmal). Der Schlüssel des Mitglieds liegt bis zum Einlösen AES-GCM-verschlüsselt in
// kc_club_kurzcodes (Schlüssel abgeleitet aus dem Server-Geheimnis, nie im Klartext). Fehlversuche: je Netz 8, insgesamt 60 je 15 Min.
const KURZCODE_MIN = 15, KURZCODE_FEHL_NETZ = 8, KURZCODE_FEHL_GESAMT = 60;
const ZUGANG_VORMERK_MS = 24 * 3600000; // KC-CLUB-ZUGANG-VORMERKEN (1.96.0)
let KURZCODE_AES: CryptoKey | null = null;
async function kurzcodeAes() {
  if (!KURZCODE_AES) KURZCODE_AES = await crypto.subtle.importKey("raw", await crypto.subtle.digest("SHA-256", new TextEncoder().encode("kc-kurzcode:" + SERVICE)), "AES-GCM", false, ["encrypt", "decrypt"]);
  return KURZCODE_AES;
}
const kcB64 = (u: Uint8Array) => btoa(String.fromCharCode(...u)), kcUnb64 = (t: string) => Uint8Array.from(atob(t), (c) => c.charCodeAt(0));
async function kurzcodeVerschluesseln(klartext: string) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const enc = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, await kurzcodeAes(), new TextEncoder().encode(klartext)));
  return kcB64(iv) + "." + kcB64(enc);
}
async function kurzcodeEntschluesseln(t: string) {
  const [iv, enc] = t.split(".");
  return new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: kcUnb64(iv) }, await kurzcodeAes(), kcUnb64(enc)));
}
const kurzcodeHash = (code: string) => sha256("kc-kurzcode:" + code);
function zufall(bytes = 24) { const a = new Uint8Array(bytes); crypto.getRandomValues(a); return [...a].map((x) => x.toString(16).padStart(2, "0")).join(""); }
const jetzt = () => new Date().toISOString();
const fTag = new Intl.DateTimeFormat("de-DE", { timeZone: TZ, weekday: "short", day: "2-digit", month: "2-digit" });
const fTagLang = new Intl.DateTimeFormat("de-DE", { timeZone: TZ, weekday: "long", day: "2-digit", month: "2-digit", year: "numeric" });
const fZeit = new Intl.DateTimeFormat("de-DE", { timeZone: TZ, hour: "2-digit", minute: "2-digit" });
const berlinTag = (d: Date) => new Intl.DateTimeFormat("sv-SE", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit" }).format(d);
const berlinStunde = (d: Date) => Number(new Intl.DateTimeFormat("en-US", { timeZone: TZ, hourCycle: "h23", hour: "2-digit" }).format(d));
const wann = (iso: string, lang = false) => `${(lang ? fTagLang : fTag).format(new Date(iso))}, ${fZeit.format(new Date(iso))} Uhr`;
const txt = (v: unknown, max: number) => String(v ?? "").replace(/\r\n?/g, "\n").replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, " ").trim().slice(0, max);

type Person = { person_id: string; display_name: string; given_name?: string; preferred_name?: string; email?: string };
const vorname = (p?: Person | null) => (p ? p.preferred_name || p.given_name || p.display_name : "");
// KC-CLUB-GEDENKEN (2.204.0, Wunsch Hansi „wenn jemand aus unserer Gruppe verstorben ist, eine brennende Kerze anzeigen“):
// nur Trauerfälle aus Freud & Leid („tod_mitglied“), über die die Mitglieder schon informiert wurden (= Familie einverstanden),
// GEDENKEN_TAGE lang ab dieser Nachricht. Nur Name und Sterbedatum.
const GEDENKEN_TAGE = 30;
async function gedenkenListe() {
  const { data } = await db.from("kc_club_fl_faelle").select("person_id,datum,informiert_am").eq("art", "tod_mitglied").not("informiert_am", "is", null)
    .gte("informiert_am", new Date(Date.now() - GEDENKEN_TAGE * 86400000).toISOString()).order("informiert_am", { ascending: false }).limit(5);
  const leute = await personen((data ?? []).map((x: any) => x.person_id));
  return (data ?? []).filter((x: any) => leute.has(x.person_id)).map((x: any) => ({ person_id: x.person_id, name: leute.get(x.person_id)!.display_name, datum: x.datum ?? null }));
}
// 2.209.0 (Gesamtprüfung 5): Geheimnisse in gleichbleibender Zeit vergleichen (kein Erraten Zeichen für Zeichen über die Antwortzeit)
function gleichZeit(a: unknown, b: string) {
  const x = new TextEncoder().encode(String(a ?? "")), y = new TextEncoder().encode(b);
  let d = x.length ^ y.length;
  for (let i = 0; i < y.length; i++) d |= (x[i] ?? 0) ^ y[i];
  return d === 0;
}
// KC-CLUB-START-SPARSAM-2: Namen aktiver Mitglieder kommen aus der gemerkten Mitgliederliste (MERK_MS); nur wer dort fehlt
// (ausgeschieden, Gast, Test) wird wie bisher einzeln gefragt. Gleiche Felder wie vorher, jeder Aufruf bekommt eigene Kopien.
const PERSON_FELDER = ["person_id", "display_name", "given_name", "preferred_name", "email"] as const;
const personKopie = (p: any): Person => Object.fromEntries(PERSON_FELDER.map((k) => [k, p[k] ?? null])) as Person;
let MG_NAMEN: { t: number; v: Promise<Map<string, Person>> } | null = null;
function mgNamenMerken(liste: any[]) { MG_NAMEN = { t: Date.now(), v: Promise.resolve(new Map(liste.map((p) => [p.person_id, personKopie(p)]))) }; }
function mgNamen(): Promise<Map<string, Person>> {
  if (!MG_NAMEN || Date.now() - MG_NAMEN.t > MERK_MS) { const m: { t: number; v: Promise<Map<string, Person>> } = { t: Date.now(), v: aktiveMitglieder().then(() => { if (MG_NAMEN && MG_NAMEN !== m) return MG_NAMEN.v; if (MG_NAMEN === m) MG_NAMEN = null; return new Map<string, Person>(); }) }; MG_NAMEN = m; }
  return MG_NAMEN.v;
}
async function personen(ids: string[]): Promise<Map<string, Person>> {
  const u = [...new Set(ids.filter(Boolean))];
  if (!u.length) return new Map();
  const mg = await mgNamen().catch(() => new Map<string, Person>()), aus = new Map<string, Person>(), rest: string[] = [];
  for (const id of u) { const p = mg.get(id); if (p) aus.set(id, personKopie(p)); else rest.push(id); }
  if (!rest.length) return aus;
  const { data } = await db.from("kc_core_people").select("person_id,display_name,given_name,preferred_name,email").in("person_id", rest);
  for (const p of (data ?? []) as Person[]) aus.set(p.person_id, p);
  return aus;
}
// KC-CLUB-START-PARALLEL-3 (2.162.0): laufen mehrere Aufrufe gleichzeitig (z. B. beim Start), teilen sie sich EINE Abfrage –
// nichts wird zwischengespeichert, jeder bekommt eine eigene Kopie (spart Datenbank-Verbindungen, Inhalt bleibt gleich)
let MG_LAUF: Promise<(Person & { birth_date?: string })[]> | null = null;
async function aktiveMitglieder() {
  if (!MG_LAUF) MG_LAUF = (async () => {
    // birth_date nur für „Geburtstag heute“ – wird nie ungefiltert an die App gegeben
    const { data, error } = await db.from("kc_core_people").select("person_id,display_name,given_name,family_name,preferred_name,email,birth_date")
      .eq("active", true).eq("org_id", ORG).not("person_id", "like", "KC-P-TEST%").order("display_name");
    if (!error && data) mgNamenMerken(data); // KC-CLUB-START-SPARSAM-2: frische Liste auch für die Namen (personen)
    return (data ?? []) as (Person & { birth_date?: string })[];
  })().finally(() => { MG_LAUF = null; });
  return (await MG_LAUF).map((x) => ({ ...x }));
}
// 2.614.0 KC-CLUB-SAMMELVERSAND-OHNE-AUSHILFEN (Wunsch Hansi „Leon und Ruth sollen keine E-Mails usw. bekommen, wenn jemand
// Nachricht an alle anklickt“): Alles, was „an alle“ geht (Schnellnachricht/Neue Nachricht mit „Alle“, Termine, Terminumfragen,
// Abstimmungen, Hilfe-Aufrufe und -Angebote, Pinnwand „für alle“, Geburtstage, Clubjahr, Sitzungseinladung, Mitfragen an alle,
// Adressänderung an alle) erreicht nur Personen mit Zugang „mitglied“. Aushilfen und Gäste bekommen weiter, was sie GEZIELT erreicht
// (einzeln gewählt, Gruppe, Dienstplan/Dienst-Tausch, Dienstwunsch-Erinnerung) und den SOS-Notfall. Sichtbar bleibt alles wie bisher.
// Rollen 60 s im Speicher. Lädt die Liste nicht, gilt der letzte bekannte Stand; gab es noch keinen, geht der Sammelversand an
// niemanden (Regel 11: unbekannt ≠ leer – lieber keine Rundmail als eine an die Aushilfen).
let NG_STAND: { t: number; ids: Set<string> } | null = null;
async function nurGezielt(): Promise<Set<string>> {
  if (NG_STAND && Date.now() - NG_STAND.t < 60000) return NG_STAND.ids;
  const { data, error } = await db.from("kc_club_rollen").select("person_id,zugang,ist_admin").in("zugang", ["aushilfe", "gast"]);
  if (error) { if (NG_STAND) return NG_STAND.ids; throw new Error("Zugangsliste nicht lesbar – kein Sammelversand"); }
  NG_STAND = { t: Date.now(), ids: new Set((data ?? []).filter((r: any) => zugangAus(r) !== "mitglied").map((r: any) => String(r.person_id))) };
  return NG_STAND.ids;
}
async function sammelEmpfaenger(): Promise<(Person & { birth_date?: string })[]> {
  const [leute, aus] = await Promise.all([aktiveMitglieder(), nurGezielt().catch((e) => { console.error("sammelEmpfaenger", String(e)); return null; })]);
  return aus ? leute.filter((m) => !aus.has(m.person_id)) : [];
}
async function ohneNurGezielt(ids: string[]): Promise<string[]> {
  const aus = await nurGezielt().catch((e) => { console.error("ohneNurGezielt", String(e)); return null; });
  return aus ? ids.filter((id) => !aus.has(id)) : [];
}
async function protokoll(person: string | null, aktion: string, details: Record<string, unknown> = {}) {
  await db.from("kc_club_protokoll").insert({ person_id: person, aktion, details });
}
// KC-CLUB-PROTOKOLL-BREMSE (2.122.0, Gesamtprüfung 4): Meldungen ohne Inhalt (Spur, Start, Diagnose, Sprache) höchstens n je Person und Stunde –
// sonst könnte jemand das Protokoll fluten, und der Protokoll-Wächter würde dafür die normalen Einträge der anderen wegräumen. Muster mit % = Anfang.
async function protokollPlatz(person: string, aktion: string, proStunde: number) {
  let q = db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("person_id", person).gte("zeit", new Date(Date.now() - 3600000).toISOString());
  q = aktion.endsWith("%") ? q.like("aktion", aktion) : q.eq("aktion", aktion);
  const { count, error } = await q;
  return !!error || (count ?? 0) < proStunde; // Zählfehler → nicht blockieren (Meldungen sind nur Hilfsdaten)
}
// 2.425.0 KC-CLUB-MASSEN-GRENZE (Generalcheck Sicherheit): Aktionen, die Push + Mail an alle auslösen, je Person und Tag begrenzen –
// sonst könnte ein Skript das Mail-Kontingent leeren und echte Notfall-Mails kämen nicht mehr an. Admin ohne Grenze; Zählfehler blockieren nie.
async function massenGrenze(ich: Ich, aktionen: string[], maxTag: number, was: string) {
  if (ich.admin) return;
  const { count, error } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("person_id", ich.person_id).in("aktion", aktionen)
    .gte("zeit", new Date(Date.now() - 86400000).toISOString());
  if (!error && (count ?? 0) >= maxTag) throw new Fehler(`Heute gingen schon ${maxTag} ${was} raus – mehr geht ab morgen wieder. Ist es dringend, sag ${await adminVorname()} Bescheid.`, 429);
}
// Bescheid an viele je Eintrag nur einmal (aus und wieder „wichtig“ löste sonst jedes Mal neue Pushes aus)
async function schonBescheid(aktion: string, feld: string, id: string) {
  const { count, error } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", aktion).eq(`details->>${feld}`, id);
  return !error && (count ?? 0) > 0;
}
// 2.425.0 KC-CLUB-GENERALCHECK (Sicherheit): im Notfall-Chat aller Mitglieder ändern Selbstlöschen und Anheften nur der Admin
async function notfallChatNurAdmin(ich: Ich, threadId: string) {
  if (ich.admin) return;
  const { data } = await db.from("kc_communication_threads").select("subject").eq("id", threadId).maybeSingle();
  if (data?.subject === NOTFALL_BETREFF) throw new Fehler("Im Notfall-Chat kann das nur der Admin ändern.", 403);
}
// 2.426.0 KC-CLUB-RT-KANAL-WECHSEL: neuer Name der direkten Leitung bei jeder Zugangsänderung – alte Geräte/entfernte Personen hören
// nichts mehr mit. Vor dem Datenbank-Update fehlt die Funktion: dann still nichts (die Leitung läuft wie bisher weiter).
const rtNeu = (pid: string) => Promise.resolve(db.rpc("kc_club_rt_neu", { p_person: pid })).catch(() => null);
// 2.431.0 KC-CLUB-ELTERN (Wunsch Hansi „so sachte wie möglich, Kinder brauchen auch Privatsphäre“): Eltern-Handy bekommt NUR
// Termine (Treffen neu/geändert/abgesagt, Erinnerung; Schulungen über kc-termine) und Nachrichten der Clubleitung/des Admins (nur Hinweis,
// ohne Text). Versand über die eigene Edge Function kc-eltern (Dienstschlüssel); „{kind}“ ersetzt sie durch den Vornamen des Kindes.
// Läuft im Hintergrund – das Speichern wartet nie darauf und scheitert nie daran.
const ELTERN_SEITE = APP_URL + "eltern/"; const ELTERN_MAX = 3;
function elternHinweis(kinder: string[], art: "termin" | "erinnerung" | "absage" | "nachricht" | "notfall", titel: string, text: string) {
  const ids = [...new Set(kinder)].filter(Boolean); if (!ids.length) return;
  const p = fetch(`${SUPA}/functions/v1/kc-eltern`, { method: "POST", signal: AbortSignal.timeout(15000),
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${SERVICE}`, apikey: SERVICE },
    body: JSON.stringify({ action: "senden", kinder: ids, art, titel: txt(titel, 120), text: txt(text, 300), url: ELTERN_SEITE }) })
    .then((r) => { dbPufferLeeren(); return r.body?.cancel(); }).catch((e) => console.error("elternHinweis", String(e)));
  try { (globalThis as any).EdgeRuntime?.waitUntil?.(p); } catch {}
}
// 2.447.0 KC-CLUB-GRUPPEN-QUITTUNG (Wunschliste #8): „angekommen“ (App hat neue Nachrichten geladen) bzw. „gelesen“ (Chat geöffnet)
// je Chat festhalten – nur wenn wirklich Neues da ist (die Datenbank prüft das). Läuft nebenher; Fehler stören nie.
function quittungMerken(ich: { person_id: string; nurLesen?: boolean }, threads: string[], art: "angekommen" | "gelesen") {
  if (!threads.length || ich.nurLesen) return Promise.resolve();
  const p = Promise.resolve(db.rpc("kc_club_chat_quittung_merken", { p_person: ich.person_id, p_threads: threads.slice(0, 50), p_art: art }))
    .then((r: any) => { if (r?.error) console.error("quittung", r.error.message); }, (e) => console.error("quittung", String(e)));
  try { (globalThis as any).EdgeRuntime?.waitUntil?.(p); } catch {}
  return p;
}
// 2.448.0 KC-CLUB-OBJEKT-ANLAGEN (Wunschliste #10, Wunsch Hansi „bei allen Möglichkeiten eine Anlage mit hochladen – Foto, PDF oder
// Dateimanager“): Anlagen (gleiche Ablage wie im Chat, vorher per anlage_hochladen geladen) an Vorschlag/Spende, Terminfindung, Terminanfrage.
const OBJ_ANLAGEN_MAX = 5;
// 2.461.0 KC-CLUB-TERMIN-LINK-PROSPEKT: Link zur Seite des Veranstalters – nur https (ohne Schema wird https:// davorgesetzt), sonst klare Meldung
function terminLink(roh: unknown): string | null {
  let l = String(roh ?? "").trim(); if (!l) return null;
  if (!/^[a-z][a-z0-9+.-]*:/i.test(l)) l = "https://" + l.replace(/^\/+/, "");
  l = l.replace(/^http:\/\//i, "https://"); // http → https (sicherer, fast alle Seiten können es)
  if (!/^https:\/\/[^\s<>"]+$/.test(l) || l.length > 500) throw new Fehler("Bitte einen gültigen Link angeben, z. B. https://www.freilichtbuehne-werne.de");
  return l;
}
async function objAnlagenSetzen(ich: { person_id: string }, art: string, objektId: string, roh: unknown) {
  const ids = [...new Set((Array.isArray(roh) ? roh : []).map((x) => String(x)).filter((x) => /^[0-9a-f-]{36}$/i.test(x)))].slice(0, OBJ_ANLAGEN_MAX);
  if (!ids.length) return 0;
  const { data: att } = await db.from("kc_communication_attachments").select("id,object_path").in("id", ids);
  const eigene = ids.filter((id) => (att ?? []).some((a: any) => a.id === id && String(a.object_path).startsWith(`club/${ich.person_id}/`))); // nur selbst hochgeladene
  if (!eigene.length) return 0;
  const { error } = await db.from("kc_club_objekt_anlagen").insert(eigene.map((attachment_id, i) => ({ art, objekt_id: objektId, attachment_id, reihenfolge: i })));
  if (error) throw new Fehler("Gespeichert – aber die Anlage konnte nicht angehängt werden. Bitte noch einmal versuchen.", 500);
  return eigene.length;
}
// KC-CLUB-VORSCHLAG-BEARBEITEN (Wunsch Hansi 19.10.2026 „Vorschläge verändern und dann die Anlagen dazu packen“): Anlagen eines Eintrags
// neu festlegen. Bleiben dürfen die schon angehängten (auch von anderen), neu dazu nur selbst hochgeladene – wie beim Anlegen.
async function objAnlagenErsetzen(ich: { person_id: string }, art: string, objektId: string, roh: unknown) {
  const ids = [...new Set((Array.isArray(roh) ? roh : []).map((x) => String(x)).filter((x) => /^[0-9a-f-]{36}$/i.test(x)))].slice(0, OBJ_ANLAGEN_MAX);
  const { data: alt, error: ae } = await db.from("kc_club_objekt_anlagen").select("attachment_id").eq("art", art).eq("objekt_id", objektId);
  if (ae) throw new Fehler("Anlagen konnten nicht geladen werden – bitte noch einmal versuchen.", 500);
  const bisher = new Set((alt ?? []).map((x: any) => String(x.attachment_id)));
  const kandidaten = ids.filter((id) => !bisher.has(id));
  const { data: att } = kandidaten.length ? await db.from("kc_communication_attachments").select("id,object_path").in("id", kandidaten) : { data: [] as any[] };
  const erlaubt = ids.filter((id) => bisher.has(id) || (att ?? []).some((a: any) => a.id === id && String(a.object_path).startsWith(`club/${ich.person_id}/`)));
  const weg = [...bisher].filter((id) => !erlaubt.includes(id));
  if (erlaubt.length) {
    const { error } = await db.from("kc_club_objekt_anlagen").upsert(erlaubt.map((attachment_id, i) => ({ art, objekt_id: objektId, attachment_id, reihenfolge: i })), { onConflict: "art,objekt_id,attachment_id" });
    if (error) throw new Fehler("Gespeichert – aber die Anlagen konnten nicht angehängt werden. Bitte noch einmal versuchen.", 500);
  }
  if (weg.length) {
    const { error } = await db.from("kc_club_objekt_anlagen").delete().eq("art", art).eq("objekt_id", objektId).in("attachment_id", weg);
    if (error) throw new Fehler("Gespeichert – aber eine Anlage konnte nicht entfernt werden. Bitte noch einmal versuchen.", 500);
  }
  return { anzahl: erlaubt.length, neu: erlaubt.filter((id) => !bisher.has(id)).length, entfernt: weg.length };
}
async function objAnlagenHolen(art: string, objektIds: string[]): Promise<Map<string, any[]>> {
  const m = new Map<string, any[]>(); if (!objektIds.length) return m;
  const { data: v } = await db.from("kc_club_objekt_anlagen").select("objekt_id,attachment_id,reihenfolge").eq("art", art).in("objekt_id", objektIds.slice(0, 300)).order("reihenfolge");
  const { data: att } = (v ?? []).length ? await db.from("kc_communication_attachments").select("id,file_name,mime_type,size_bytes").in("id", (v ?? []).map((x: any) => x.attachment_id)) : { data: [] as any[] };
  for (const x of v ?? []) { const a: any = (att ?? []).find((y: any) => y.id === x.attachment_id); if (!a) continue;
    m.set(x.objekt_id, [...(m.get(x.objekt_id) ?? []), { id: a.id, name: a.file_name, mime: a.mime_type, groesse: a.size_bytes }]); }
  return m;
}
// Darf ich die Anlage sehen? Genau dann, wenn ich den Eintrag sehen darf (gleiche Regeln wie die Listen).
async function objAnlageSichtbar(ich: Ich, art: string, objektId: string) {
  if (art === "vorschlag") {
    if (ich.zugang !== "mitglied") return false;
    const { data: v } = await db.from("kc_club_vorschlaege").select("ziel_ids,erstellt_von").eq("id", objektId).maybeSingle();
    return !!v && (!v.ziel_ids || v.ziel_ids.includes(ich.person_id) || v.erstellt_von === ich.person_id || ich.admin);
  }
  if (art === "treffen") { const { data: t } = await db.from("kc_club_treffen").select("id").eq("id", objektId).maybeSingle(); return !!t; } // 2.461.0: Clubtermine sieht jeder
  if (art === "terminumfrage") { const { data: u } = await db.from("kc_club_terminumfragen").select("id").eq("id", objektId).maybeSingle(); return !!u; }
  if (art === "terminanfrage") {
    if (ich.zugang !== "mitglied") return false;
    const { data: a } = await db.from("kc_club_terminanfragen").select("erstellt_von").eq("id", objektId).maybeSingle(); if (!a) return false;
    if (a.erstellt_von === ich.person_id) return true;
    const { data: e } = await db.from("kc_club_terminanfrage_empfaenger").select("anfrage_id").eq("anfrage_id", objektId).eq("person_id", ich.person_id).maybeSingle(); return !!e;
  }
  return false;
}
// 2.449.0 KC-CLUB-BILD-VERLAUF (Wunschliste #21, Fund Hansi „Avatar-Bild durch ein Selfie ersetzt und wollte es wieder haben – ist weg“;
// Antwort Hansi: „nur automatisch – die letzten 3 benutzten Bilder, für Fotos, Selfies und die gebaute Figur“): vor jedem Wechsel wird das
// bisherige Bild gemerkt (Figur = Code, Foto = Code + kleines JPG wie bisher). Höchstens 3; das aktuelle steht nie im Verlauf.
// Nur für die Person selbst (eigene Aktion „avatar_verlauf“); nicht im Start-Paket, damit der Start klein bleibt.
const AV_VERLAUF_MAX = 3;
async function avJetzt(pid: string): Promise<{ code: string | null; bild: string | null }> {
  const { data } = await db.from("kc_club_person_einstellung").select("schluessel,wert").eq("person_id", pid).in("schluessel", ["avatar", "avatar_foto"]);
  const code = ((data ?? []).find((x: any) => x.schluessel === "avatar")?.wert as any)?.figur ?? null;
  const fo: any = (data ?? []).find((x: any) => x.schluessel === "avatar_foto")?.wert;
  return { code, bild: code && AVF_CODE.test(code) && fo?.code === code ? fo.bild ?? null : null };
}
async function avVerlaufHolen(pid: string): Promise<any[]> {
  const { data } = await db.from("kc_club_person_einstellung").select("wert").eq("person_id", pid).eq("schluessel", "avatar_verlauf").maybeSingle();
  return (Array.isArray((data?.wert as any)?.liste) ? (data!.wert as any).liste : []).filter((x: any) => typeof x?.code === "string" && (!AVF_CODE.test(x.code) || typeof x.bild === "string"));
}
async function avVerlaufMerken(pid: string, alt: { code: string | null; bild: string | null }, neu: string | null) {
  let liste = (await avVerlaufHolen(pid)).filter((x: any) => x.code !== alt.code && x.code !== neu);
  if (alt.code && alt.code !== neu && (!AVF_CODE.test(alt.code) || alt.bild)) liste = [{ code: alt.code, ...(alt.bild ? { bild: alt.bild } : {}), am: jetzt() }, ...liste];
  await db.from("kc_club_person_einstellung").upsert({ person_id: pid, schluessel: "avatar_verlauf", wert: { liste: liste.slice(0, AV_VERLAUF_MAX) }, geaendert_am: jetzt() }, { onConflict: "person_id,schluessel" });
}
// KC-CLUB-LOESCHEN: vor jedem Löschen eine vollständige Sicherung ins Änderungsprotokoll (Wiederherstellungspunkt)
async function geloescht(ich: { person_id: string }, was: string, sicherung: Record<string, unknown>) {
  const { error } = await db.from("kc_club_protokoll").insert({ person_id: ich.person_id, aktion: was + "_geloescht", details: { sicherung } });
  if (error) throw new Fehler("Sicherung fehlgeschlagen – es wurde nichts gelöscht.", 500);
}

// Versand über den KC Communicator (Push, sonst/zusätzlich Mail über web.de).
// 2.0.0 (Gesamtprüfung): Communicator nicht erreichbar → KEIN Absturz (sonst meldet die App einen Fehler, obwohl die Nachricht
// schon gespeichert ist, und das Mitglied schickt sie nochmal) – stattdessen „0 gesendet, n Fehler“ zurückgeben und protokollieren
async function routerSenden(eventKey: string, personIds: string[], vars: Record<string, unknown>, korrelation: string, kopie?: { cc?: string[]; bcc?: string[] }) {
  try { return await routerSendenRoh(eventKey, personIds, vars, korrelation, kopie); }
  catch (e) { console.error("routerSenden", eventKey, String(e)); return { gesendet: 0, fehler: personIds.length }; }
}
// 2.536.0 KC-CLUB-KOMMUNIKATION-AUS (Wunsch Hansi „aus der Kommunikation der Club-App herausnehmen“): Registry kc_club_kommunikation_aus.
// Wer dort steht, bekommt über KEINEN Club-Weg Push oder Mail – auch nicht bei ausdrücklich gewähltem Weg, Express, Notfall oder Kopie.
// Liste 60 s im Speicher. Lädt sie nicht, gilt der letzte bekannte Stand; gab es noch keinen, wird nicht gesendet (Regel 11: unbekannt ≠ leer).
let KA_STAND: { t: number; ids: Set<string> } | null = null;
async function kommunikationAus(): Promise<Set<string>> {
  if (KA_STAND && Date.now() - KA_STAND.t < 60000) return KA_STAND.ids;
  const { data, error } = await db.from("kc_club_kommunikation_aus").select("person_id");
  if (error) { if (KA_STAND) return KA_STAND.ids; throw new Error("Liste „keine Benachrichtigungen“ nicht lesbar – nichts gesendet"); }
  KA_STAND = { t: Date.now(), ids: new Set((data ?? []).map((x: any) => String(x.person_id))) };
  return KA_STAND.ids;
}
async function routerSendenRoh(eventKey: string, personIds: string[], vars: Record<string, unknown>, korrelation: string, kopie?: { cc?: string[]; bcc?: string[] }) {
  // KC-CLUB-PERSON-SPERRE (2.23.77): Gesperrte mit „Benachrichtigungen aus“ bekommen nichts (alle Club-Wege laufen hier durch)
  const stumm = new Set([...(await sperrenAktuell()).stumm, ...await kommunikationAus()]); // 2.536.0 KC-CLUB-KOMMUNIKATION-AUS
  if (stumm.size) {
    personIds = personIds.filter((id) => !stumm.has(id));
    if (kopie) kopie = { cc: kopie.cc?.filter((id) => !stumm.has(id)), bcc: kopie.bcc?.filter((id) => !stumm.has(id)) };
    if (!personIds.length && !kopie?.cc?.length && !kopie?.bcc?.length) return { gesendet: 0, fehler: 0 };
  }
  dbPufferLeeren(); // KC-CLUB-DB-SPARSAM: der Communicator schreibt selbst
  const r = await fetch(`${SUPA}/functions/v1/kc-communication-router`, { signal: AbortSignal.timeout(20000),
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${SERVICE}`, apikey: SERVICE },
    body: JSON.stringify({ sourceProgram: "kc-club", eventKey, recipients: personIds.map((personId) => ({ personId })), variables: vars, correlationId: korrelation,
      // KC-CLUB-WICHTIGKEIT (2.287.0): ❗ hoch / 🚨 Notfall als Priorität an den Communicator (Spalte priority; Notfall = Push mit hoher Dringlichkeit)
      // 2.384.0 KC-CLUB-EXPRESS-SOFORT (Wunsch Hansi „Express heißt so schnell wie möglich“): Express geht wie der Notfall als „critical“ –
      // nur dann setzt der Versand beim Push die Dringlichkeit „high“. Mit „normal“ darf Android den Push im Stromsparmodus zurückhalten.
      ...(vars.wichtigkeit === "notfall" || vars.eilig === true ? { priority: "critical" } : vars.wichtigkeit === "hoch" ? { priority: "high" } : {}),
      // 0.38.0: Kopien (Mitgliedsnummern) – der Communicator löst sie zu Mail-Adressen auf
      ...(kopie?.cc?.length ? { cc: kopie.cc.map((personId) => ({ personId })) } : {}), ...(kopie?.bcc?.length ? { bcc: kopie.bcc.map((personId) => ({ personId })) } : {}) }),
  });
  const out = await r.json().catch(() => ({}));
  dbPufferLeeren();
  const ergebnis: { gesendet: number; fehler: number; wege?: Record<string, { push: string; mail: string }> } = { gesendet: Number(out?.sent || 0), fehler: Number(out?.failed || 0) };
  // 2.403.0 KC-CLUB-EXPRESS-WEGE: je Empfänger, was auf welchem Weg wirklich passiert ist (aus der Antwort des Versanddienstes) –
  // „ja“ = raus, „kein“ = kein Push-Gerät bzw. keine Mail-Adresse, „fehler“ = versucht und gescheitert, „-“ = nicht vorgesehen
  if (Array.isArray(out?.results)) ergebnis.wege = Object.fromEntries(out.results.filter((x: any) => x?.personId).map((x: any) => [x.personId, routerWege(x.attempts)]));
  if (VORGANG_KOPIE.test(korrelation) && !korrelation.endsWith(":kopie")) await vorgangKopie(eventKey, personIds, vars, korrelation, ergebnis).catch((e) => console.error("vorgangKopie", String(e)));
  return ergebnis;
}
function routerWege(attempts: any[]): { push: string; mail: string } {
  const weg = (k: string) => { const a = (Array.isArray(attempts) ? attempts : []).filter((x: any) => x?.channel === k);
    if (!a.length) return "-"; if (a.some((x: any) => x.result === "sent" || x.result === "deduplicated" || x.result === "queued")) return "ja"; // queued: KC-COMM-WARTEN
    return a.some((x: any) => /^(NO_ACTIVE_PUSH_DEVICE|NO_EMAIL|PUSH_NO_ACTIVE_SUBSCRIPTION|PUSH_SUBSCRIPTION_NOT_FOUND|EMAIL_RECIPIENT_MISSING)/.test(String(x.reason || ""))) ? "kein" : "fehler"; };
  return { push: weg("push"), mail: weg("email") };
}
// KC-CLUB-VORGANG-KOPIE (2.221.0, Wunsch Hansi „ich muss über alle Vorgänge Bescheid wissen und immer in BCC gesetzt werden, damit ich weiß,
// dass alles gelaufen ist und geklappt hat“): bei jeder Benachrichtigung zu einem Vorgang (Änderungsmeldung, Erstattung, Dienstwunsch,
// Zugang/Link, Leihen) bekommt der Admin eine eigene Kopie-Mail – mit Empfänger und Versandergebnis. Auch wenn das Mitglied nur Push bekam.
// Private Chats, Spiele, Reaktionen usw. bekommen KEINE Kopie. Je Vorgang höchstens eine Kopie (gleiche Kennung → der Versanddienst entdoppelt).
// 2.255.0 KC-CLUB-TWINKEY-BEANTWORTET (Wunsch Hansi „sende mir eine Kopie, damit ich weiß, wie der Text gelautet hat“): + Twinkey-Antworten
const VORGANG_KOPIE = /^club-(aenderung|erstattung|bestaetigung|dw-|wunschbogen|zugang|leihe|twinkey-antwort)/;
async function vorgangKopie(eventKey: string, personIds: string[], vars: Record<string, unknown>, korrelation: string, erg: { gesendet: number; fehler: number }, nurApp = false) {
  const adm = (await adminIds()).filter((a) => !personIds.includes(a));
  if (!adm.length || !personIds.length) return;
  const leute = await personen(personIds), namen = personIds.map((id) => leute.get(id)?.display_name || id).join(", ");
  const weg = nurApp ? "nur Club-App" : /_push$/.test(eventKey) ? "Push" : /_mail$/.test(eventKey) ? "E-Mail" : "Push + E-Mail";
  const stand = nurApp ? "📱 liegt in der Club-App bereit (Hinweis beim nächsten Öffnen)" : erg.fehler ? `⚠️ ${erg.gesendet} zugestellt, ${erg.fehler} NICHT zugestellt` : erg.gesendet ? `✅ zugestellt (${erg.gesendet})` : "⚠️ nichts zugestellt (kein Empfangsweg)";
  const betreff = String(vars.betreff ?? vars.titel ?? "Benachrichtigung");
  await routerSendenRoh("club_nachricht_mail", adm, { ...vars, titel: `📋 Kopie: ${String(vars.titel ?? betreff)}`, betreff: `📋 Kopie: ${betreff}`, kurz: `Kopie an dich: ${namen}`,
    text: `Kopie für dich als Admin\nAn: ${namen}\nWeg: ${weg}\nErgebnis: ${stand}\n\n────────────────────\n\n${String(vars.text ?? vars.kurz ?? "")}` },
    korrelation.replace(/:(ruhe|push)$/, "") + ":kopie");
}
// KC-CLUB-BENACHRICHTIGUNG: Ereignis → Bereich, den das Mitglied in den Einstellungen steuert
const BEREICH_VON: Record<string, string> = { club_treffen: "termine", club_erinnerung: "termine", club_nachricht: "nachrichten", club_vorschlag: "vorschlaege", club_dienst: "dienste", club_geburtstag: "geburtstage",
  club_protokoll: "termine", club_aufgabe: "termine", club_pinnwand: "pinnwand" };
const BEREICHE = ["termine", "nachrichten", "vorschlaege", "dienste", "geburtstage", "pinnwand"];
// Anzeige-Standard, solange nichts gespeichert ist (Server nutzt dann die bisherige Standardregel)
const STANDARD_WAHL: Record<string, { push: boolean; email: boolean }> = { termine: { push: true, email: true }, nachrichten: { push: true, email: false }, vorschlaege: { push: true, email: false }, dienste: { push: false, email: false }, geburtstage: { push: true, email: false }, pinnwand: { push: true, email: false } };
// ---------- KC-CLUB-RUHEZEIT (0.98.0): „Nicht stören“ ----------
// Wer „Nicht stören“ eingeschaltet hat, bekommt in dieser Zeit keinen Push. Mail geht weiter (stört nachts nicht).
// Was dabei ausfällt, wird gezählt; nach dem Ende der Ruhezeit schickt die Wartung EINE Sammelmeldung.
// Anrufe/Anklopfen laufen nicht über senden() und kommen deshalb immer durch; @Erwähnungen, wenn so eingestellt.
const minutenBerlin = (d = new Date()) => { const [h, m] = new Intl.DateTimeFormat("en-GB", { timeZone: TZ, hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).format(d).split(":").map(Number); return h * 60 + m; };
const hhmm = (x: string) => Number(x.slice(0, 2)) * 60 + Number(x.slice(3, 5));
function inRuhezeit(r: any, jetztMin = minutenBerlin()) {
  if (!r?.an) return false;
  const v = hhmm(r.von), b = hhmm(r.bis);
  return v === b ? false : v < b ? jetztMin >= v && jetztMin < b : jetztMin >= v || jetztMin < b;
}
async function ruhendePersonen(ids: string[], erwaehnung = false): Promise<Set<string>> {
  if (!ids.length) return new Set();
  const { data } = await db.from("kc_club_person_einstellung").select("person_id,wert").eq("schluessel", "ruhezeit").in("person_id", ids);
  return new Set((data ?? []).filter((x: any) => inRuhezeit(x.wert) && !(erwaehnung && x.wert?.erwaehnung)).map((x: any) => x.person_id));
}
async function ruhezeitVerpasst(ids: string[], titel: string) {
  for (const id of ids) {
    const { data } = await db.from("kc_club_person_einstellung").select("wert").eq("person_id", id).eq("schluessel", "ruhezeit_verpasst").maybeSingle();
    const w: any = data?.wert || { anzahl: 0, titel: [] };
    await db.from("kc_club_person_einstellung").upsert({ person_id: id, schluessel: "ruhezeit_verpasst", wert: { anzahl: (w.anzahl || 0) + 1, titel: [txt(titel, 80), ...(w.titel || [])].slice(0, 5) }, geaendert_am: jetzt() }, { onConflict: "person_id,schluessel" });
  }
}

// KC-CLUB-OHNEAPP: Wer die Club-App noch nie geöffnet hat, bekommt nur eine Mail (Regel <eventKey>_mail) –
// ein Push über eine Anmeldung aus einem anderen Programm würde auf die gesperrte App führen.
async function senden(eventKey: string, personIds: string[], vars: Record<string, unknown>, korrelation: string) {
  if (!personIds.length) return { gesendet: 0 };
  const [{ data: zug }, { data: wahl }] = await Promise.all([
    db.from("kc_club_zugang").select("person_id").eq("aktiv", true).not("zuletzt_gesehen", "is", null).in("person_id", personIds),
    db.from("kc_club_benachrichtigung").select("person_id,push,email").eq("bereich", BEREICH_VON[eventKey] ?? "-").in("person_id", personIds),
  ]);
  const mitApp = new Set((zug ?? []).map((z: any) => z.person_id));
  const w = new Map((wahl ?? []).map((x: any) => [x.person_id, x]));
  const hinweis = "\n\n(Die Köcheclub-App hast du noch nicht geöffnet – deinen persönlichen Link bekommst du von Hansi.)";
  const ruhe = await ruhendePersonen(personIds.filter((id) => mitApp.has(id))), verpasst: string[] = []; // KC-CLUB-RUHEZEIT
  const probe = await probeListe(); // KC-CLUB-PROBEPHASE: ohne eigene Wahl nur Termine per Mail (wie bisher ohne App), sonst nichts
  // Gruppen je Regel; Mitglieder ohne App getrennt (sie bekommen den Hinweis auf den Link)
  const gruppen = new Map<string, { key: string; ohne: boolean; ids: string[] }>();
  for (const id of personIds) {
    let ohne = !mitApp.has(id);
    let key: string | null;
    if (probe.has(id) && !w.has(id)) { if (BEREICH_VON[eventKey] !== "termine") continue; ohne = false; key = eventKey + "_mail"; }
    else if (ohne) key = eventKey + "_mail";
    else {
      const x: any = w.get(id);
      key = !x ? eventKey : x.push && x.email ? eventKey + "_beide" : x.push ? eventKey + "_push" : x.email ? eventKey + "_mail" : null;
      // Ruhezeit: Push fällt weg, Mail bleibt; ohne Mail wird die Meldung für die Sammelmeldung gezählt
      if (key && ruhe.has(id) && key !== eventKey + "_mail") { if (key === eventKey + "_beide") key = eventKey + "_mail"; else { verpasst.push(id); key = null; } }
    }
    if (!key) continue; // Mitglied hat für diesen Bereich alles ausgeschaltet
    const g = gruppen.get(`${ohne}|${key}`) ?? { key, ohne, ids: [] };
    g.ids.push(id); gruppen.set(`${ohne}|${key}`, g);
  }
  let gesendet = 0, fehler = 0;
  for (const g of gruppen.values()) {
    const r = await routerSenden(g.key, g.ids, g.ohne ? { ...vars, text: String(vars.text ?? "") + hinweis } : vars, korrelation);
    gesendet += r.gesendet; fehler += r.fehler;
  }
  if (verpasst.length) await ruhezeitVerpasst(verpasst, String(vars.titel ?? vars.kurz ?? "Meldung"));
  return { gesendet, fehler, ruhezeit: verpasst.length };
}

// KC-CLUB-ZUSTELLWAHL: Absender wählt ausdrücklich, wie benachrichtigt wird (🔔 Push und/oder ✉️ E-Mail).
// Leer = wie jedes Mitglied es eingestellt hat (senden). Wer die App noch nie geöffnet hat, bekommt immer eine Mail.
const ZUSTELLWEGE = ["push", "email"];
async function sendenGewaehlt(eventKey: string, personIds: string[], wege: string[], vars: Record<string, unknown>, korrelation: string, opt: { erwaehnung?: boolean; notfall?: boolean } = {}) {
  const w = [...new Set(wege.filter((x) => ZUSTELLWEGE.includes(x)))];
  if (!w.length) return await senden(eventKey, personIds, vars, korrelation);
  if (!personIds.length) return { gesendet: 0 };
  // KC-CLUB-RUHEZEIT: wer gerade „Nicht stören“ hat, bekommt keinen Push – Mail, wenn gewählt; sonst später gesammelt
  if (w.includes("push") && !opt.notfall) { // KC-CLUB-NOTFALL-MELDUNG: Notfall kommt auch in der Ruhezeit
    const ruhe = await ruhendePersonen(personIds, !!opt.erwaehnung);
    if (ruhe.size) {
      const still = personIds.filter((id) => ruhe.has(id)); personIds = personIds.filter((id) => !ruhe.has(id));
      if (w.includes("email")) await routerSenden(eventKey + "_mail", still, vars, korrelation + ":ruhe");
      else await ruhezeitVerpasst(still, String(vars.titel ?? vars.kurz ?? "Meldung"));
      if (!personIds.length) return { gesendet: 0, ruhezeit: still.length };
    }
  }
  const { data: zug } = await db.from("kc_club_zugang").select("person_id").eq("aktiv", true).not("zuletzt_gesehen", "is", null).in("person_id", personIds);
  const mitApp = new Set((zug ?? []).map((z: any) => z.person_id));
  const key = w.length === 2 ? eventKey + "_beide" : w[0] === "push" ? eventKey + "_push" : eventKey + "_mail";
  const hinweis = "\n\n(Die Köcheclub-App hast du noch nicht geöffnet – deinen persönlichen Link bekommst du von Hansi.)";
  const mit = personIds.filter((id) => mitApp.has(id)), ohne = personIds.filter((id) => !mitApp.has(id));
  let gesendet = 0, fehler = 0;
  if (mit.length) { const r = await routerSenden(key, mit, vars, korrelation); gesendet += r.gesendet; fehler += r.fehler; }
  if (ohne.length) { const r = await routerSenden(eventKey + "_mail", ohne, { ...vars, text: String(vars.text ?? "") + hinweis }, korrelation); gesendet += r.gesendet; fehler += r.fehler; }
  // 0.32.1: Push ausdrücklich gewählt → auch Mitglieder ohne geöffnete Club-App, die schon ein aktives Push-Abo haben
  // (z. B. von der früheren Push-Seite), bekommen den Push zusätzlich zur Mail. Der Text weist auf den persönlichen Link hin.
  if (ohne.length && w.includes("push")) {
    const { data: abo } = await db.from("kc_member_push_subscriptions").select("person_id").eq("active", true).in("person_id", ohne);
    const mitAbo = [...new Set((abo ?? []).map((x: any) => x.person_id))] as string[];
    if (mitAbo.length) { const r = await routerSenden(eventKey + "_push", mitAbo, { ...vars, kurz: String(vars.kurz ?? "") + " (Club-App: bitte deinen persönlichen Link öffnen)" }, korrelation + ":push"); gesendet += r.gesendet; fehler += r.fehler; }
  }
  return { gesendet, fehler, wege: w };
}
const zustellwege = (v: unknown) => (Array.isArray(v) ? v : []).map(String).filter((x) => ZUSTELLWEGE.includes(x));
// 2.403.0 KC-CLUB-EXPRESS-PRIO1 (Wunsch Hansi „Express so schnell wie möglich raus, in der Warteschlange bevorzugt – Priorität 1“):
// Express geht nicht als ein Sammelauftrag (der Versanddienst arbeitet die Empfänger darin nacheinander ab), sondern je Empfänger
// ein eigener Auftrag – alle gleichzeitig (höchstens EXPRESS_PARALLEL auf einmal), mit Priorität „critical“ (= Priorität 1: der
// Versanddienst lässt sie an der Minutengrenze vorbei und Push geht mit höchster Dringlichkeit). Push und Mail je Empfänger;
// wer die App noch nie geöffnet hat, bekommt die Mail mit dem Link-Hinweis. Ergebnis je Empfänger und Weg (für die Anzeige beim Absender).
const EXPRESS_PARALLEL = 8;
async function expressSenden(personIds: string[], vars: Record<string, unknown>, korrelation: string) {
  const ids = [...new Set(personIds)]; if (!ids.length) return { gesendet: 0, fehler: 0, wege: [] as any[] };
  const [{ data: zug }, leute] = await Promise.all([
    db.from("kc_club_zugang").select("person_id").eq("aktiv", true).not("zuletzt_gesehen", "is", null).in("person_id", ids), personen(ids)]);
  const mitApp = new Set((zug ?? []).map((z: any) => z.person_id));
  const hinweis = "\n\n(Die Köcheclub-App hast du noch nicht geöffnet – deinen persönlichen Link bekommst du von Hansi.)";
  const v = { ...vars, eilig: true, wichtigkeit: vars.wichtigkeit ?? "hoch" };
  const einzeln = async (id: string) => {
    const r = mitApp.has(id) ? await routerSenden("club_nachricht_beide", [id], v, korrelation)
      : await routerSenden("club_nachricht_mail", [id], { ...v, text: String(v.text ?? "") + hinweis }, korrelation);
    const w = (r as any).wege?.[id] ?? { push: "-", mail: "-" };
    return { person_id: id, name: vorname(leute.get(id)) || leute.get(id)?.display_name || id, push: w.push, mail: w.mail, ok: w.push === "ja" || w.mail === "ja" || (!(r as any).wege && r.gesendet > 0) };
  };
  const wege: any[] = [];
  for (let i = 0; i < ids.length; i += EXPRESS_PARALLEL) wege.push(...await Promise.all(ids.slice(i, i + EXPRESS_PARALLEL).map(einzeln)));
  const gesendet = wege.filter((x) => x.ok).length;
  return { gesendet, fehler: wege.length - gesendet, wege: wege.map(({ ok, ...x }) => x) };
}

// Vorhandenes Zweiergespräch (genau zwei Teilnehmer, ohne Betreff) zwischen a und b – sonst null
async function zweierGespraech(a: string, b: string): Promise<string | null> {
  const { data: a1 } = await db.from("kc_communication_thread_participants").select("thread_id").eq("person_id", a);
  const { data: a2 } = await db.from("kc_communication_thread_participants").select("thread_id").eq("person_id", b);
  const gemeinsam = (a1 ?? []).map((x: any) => x.thread_id).filter((id: string) => (a2 ?? []).some((y: any) => y.thread_id === id));
  for (const id of gemeinsam) {
    const { count } = await db.from("kc_communication_thread_participants").select("person_id", { count: "exact", head: true }).eq("thread_id", id);
    const { data: th } = await db.from("kc_communication_threads").select("subject").eq("id", id).single();
    if (count === 2 && !th?.subject) return id;
  }
  return null;
}

