// KC-CLUB-NUTZUNG-PERSONEN (2.6.1, Prüfung): höchstens NZ_GERAETE_JE_TAG verschiedene Kennungen je Tag annehmen (flüchtig im
// Speicher dieser Server-Instanz, ohne Personenbezug) – sonst könnte ein Skript die Zahl beliebig aufblähen
const NZ_GERAETE_JE_TAG = 120;
let nzGeraeteMerk = { tag: "", g: new Set<string>() };
function nzGeraetErlaubt(geraet: string) {
  const tag = berlinTag(new Date()); if (nzGeraeteMerk.tag !== tag) nzGeraeteMerk = { tag, g: new Set<string>() };
  if (!nzGeraeteMerk.g.has(geraet) && nzGeraeteMerk.g.size >= NZ_GERAETE_JE_TAG) return false;
  nzGeraeteMerk.g.add(geraet); return true;
}
// KC-CLUB-EINWEISUNG (2.4.0): für die Admin-Zentrale – nur Zahlen, keine Namen (wie die Nutzungsstatistik)
async function einweisungZahlen() {
  const { data } = await db.from("kc_club_person_einstellung").select("person_id,wert").eq("schluessel", "einweisung").not("person_id", "like", "KC-P-TEST%");
  const bereiche: Record<string, number> = {};
  for (const x of data ?? []) for (const id of Object.keys((x as any).wert?.gesehen ?? {})) bereiche[id] = (bereiche[id] ?? 0) + 1;
  return { personen: (data ?? []).filter((x: any) => Object.keys(x.wert?.gesehen ?? {}).length).length, aus: (data ?? []).filter((x: any) => x.wert?.an === false).length, bereiche };
}
async function adminAbwesendPruefen() {
  // 2.6.1 (Prüfung, Regel 11): jede gescheiterte Abfrage = Stand unbekannt → keine Meldung (kein Fehlalarm)
  const { data: ad, error: e1 } = await db.from("kc_club_rollen").select("person_id").eq("ist_admin", true).not("person_id", "like", "KC-P-TEST%");
  if (e1) return;
  const ids = (ad ?? []).map((x: any) => x.person_id); if (!ids.length) return;
  const { data: zg, error: e2 } = await db.from("kc_club_zugang").select("zuletzt_gesehen").in("person_id", ids).not("zuletzt_gesehen", "is", null).order("zuletzt_gesehen", { ascending: false }).limit(1);
  if (e2) return;
  const zuletzt = zg?.[0]?.zuletzt_gesehen ? Date.parse(zg[0].zuletzt_gesehen) : 0;
  if (Date.now() - zuletzt < ADMIN_ABWESEND_TAGE * 86400000) return;
  const { count, error: e3 } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "admin_abwesend_gemeldet").gte("zeit", new Date(Date.now() - 7 * 86400000).toISOString());
  if (e3 || count === null || count > 0) return;
  const [{ data: lt, error: e4 }, aktiv] = await Promise.all([db.from("kc_club_rollen").select("person_id,aemter,ist_vorstand,ist_admin"), aktiveMitglieder()]);
  if (e4) return;
  const aktivIds = new Set(aktiv.map((m) => m.person_id)); // 2.6.1: nur aktive Mitglieder, keine Testpersonen
  const leitung = (lt ?? []).filter((r: any) => !r.ist_admin && aktivIds.has(r.person_id) && !String(r.person_id).startsWith("KC-P-TEST") && (r.ist_vorstand || (r.aemter ?? []).includes("Clubsprecher"))).map((r: any) => r.person_id);
  if (!leitung.length) return;
  const name = await adminVorname();
  await protokoll(null, "admin_abwesend_gemeldet", { tage: ADMIN_ABWESEND_TAGE, leitung: leitung.length });
  await senden("club_nachricht", leitung, {
    titel: "🛡️ Längere Zeit kein Admin in der App", kurz: `Seit über ${ADMIN_ABWESEND_TAGE} Tagen war kein Admin in der Club-App.`,
    betreff: "Köcheclub Werne – längere Zeit kein Admin in der App",
    text: `Hallo,\n\nseit über ${ADMIN_ABWESEND_TAGE} Tagen war kein Admin in der Köcheclub-App. Das ist nur ein Hinweis – vielleicht ist ${name} einfach im Urlaub.\n\nFalls etwas Dringendes ist (z. B. ein Mitglied kommt nicht mehr in die App): Bitte zuerst ${name} direkt ansprechen. Ist ${name} nicht erreichbar, liegt beim Clubsprecher der versiegelte Notfall-Umschlag mit der Betriebsanleitung für die Vertretung.\n\nViele Grüße\nKöcheclub-App`, url: APP_URL,
  }, `club-admin-abwesend:${berlinTag(new Date())}`).catch(() => null);
}
// KC-CLUB-ADMIN-NAME (1.99.0): Vorname des (ersten) Admins für Texte wie „bitte … Bescheid geben“ – 10 Min. gemerkt
let ADMIN_VORNAME: { name: string; bis: number } | null = null;
async function adminVorname(): Promise<string> {
  if (ADMIN_VORNAME && ADMIN_VORNAME.bis > Date.now()) return ADMIN_VORNAME.name;
  let name = "Hansi";
  try { const { data: ad } = await db.from("kc_club_rollen").select("person_id").eq("ist_admin", true).not("person_id", "like", "KC-P-TEST%").order("person_id").limit(1);
    if (ad?.[0]) { const p = (await personen([ad[0].person_id])).get(ad[0].person_id); name = vorname(p ?? null) || name; } } catch { /* Rückfall „Hansi“ */ }
  ADMIN_VORNAME = { name, bis: Date.now() + 600000 }; return name;
}
// 2.0.0: Zeitpunkt prüfen statt abstürzen („Invalid time value“)
const isoZeitOderFehler = (v: unknown, was: string) => { const d = new Date(String(v)); if (isNaN(d.getTime())) throw new Fehler(`${was}: bitte eine gültige Zeit wählen.`); return d.toISOString(); };
// 2.0.0: Text von Nicht-Angemeldeten ohne Links weitergeben (kein Weg für fremde Links in Admin-Push/Mail)
const ohneLinks = (t: string) => t.replace(/(https?:\/\/|www\.)\S+/gi, "[Link entfernt]");
// ---------- Anmeldung ----------
type Ich = { person_id: string; name: string; vorname: string; admin: boolean; vorstand: boolean; aemter: string[]; protokolle: boolean; kontakte: boolean; buero: BueroRecht;
  zugang: "mitglied" | "aushilfe" | "gast"; // 2.422.0 KC-CLUB-ZUGANG
  nurLesen?: boolean }; // KC-CLUB-NOTBETRIEB: true = Antwort nur für das Notfall-Paket berechnen, nichts schreiben
// KC-CLUB-BUERO-RECHTE (1.37.0): Büro je Mitglied vom Admin freigeschaltet – null = kein Büro; Admin immer „schreiben“
type BueroRecht = "lesen" | "schreiben" | null;
const BUERO_RECHTE = ["lesen", "schreiben"] as const;
// KC-CLUB-ANMELDECACHE (0.56.0): geprüfte Anmeldung je Server-Instanz ANMELDUNG_CACHE_MS lang merken (spart je Anfrage
// 2 Datenbank-Runden). Schlüssel = SHA-256 des Tokens (nie das Token selbst). Rollen-/Zugangsänderungen leeren den Speicher
// dieser Instanz sofort; andere Instanzen übernehmen sie spätestens nach ANMELDUNG_CACHE_MS. „zuletzt gesehen“ höchstens
// alle ZULETZT_TAKT_MS schreiben (Online-Anzeige rechnet mit ONLINE_SEK = 150 s).
const ANMELDUNG_CACHE_MS = 60_000, ZULETZT_TAKT_MS = 30_000, ANMELDUNG_CACHE_MAX = 300;
const ANMELDUNGEN = new Map<string, { ich: Ich; bis: number; gesehen: number; version: string | null }>();
const anmeldungenVergessen = () => ANMELDUNGEN.clear();
const INSTANZ = crypto.randomUUID().slice(0, 8); let ANMELDUNG_TREFFER = false; // Messung: welche Instanz, Speicher getroffen?
// KC-CLUB-MINDESTVERSION (RC 20.10.2026): ältere App-Versionen werden beim Start um ein Update gebeten (gleich halten mit "mindest" in version.json)
const MINDEST_APP_VERSION = "2.500.0";
const versionAelter = (a: string, b: string) => { const x = a.split(".").map(Number), y = b.split(".").map(Number); for (let i = 0; i < 3; i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) < (y[i] || 0); return false; };
// ---------- 2.579.0 KC-CLUB-FREMDZUGRIFF (Wunsch Hansi „Fremde Anmeldeversuche: wann, mit welchem Schlüssel, Vermutung wer“) ----------
// Jede abgelehnte Anmeldung wird im Hintergrund vermerkt (kc_club_fremdzugriff): Zeit, Kurzkennung des Schlüssels (nie der Schlüssel),
// Netz-Kennung (Hash der IP), Gerät und eine Vermutung. Gleicher Schlüssel aus gleichem Netz höchstens alle FZ.gleichMin Minuten,
// je Server-Instanz höchstens FZ.proStunde Einträge je Stunde (gegen Fluten). Häufen sich Versuche oder kommt ein Programm/Bot → Push an die Admins.
const FZ_ZULETZT = new Map<string, number>(); let FZ_STUNDE = { ab: 0, n: 0 }, FZ_ALARM_MS = 0;
const NETZ_ANGEMELDET = new Map<string, { person: string; t: number }>(); // gleiche Internetverbindung: wer war hier zuletzt erfolgreich (nur im Speicher)
const netzKennung = async (req: Request) => (await sha256("kc-netz:" + (req.headers.get("x-forwarded-for") || "").split(",")[0].trim())).slice(0, 16);
function fremdMerken(req: Request, grund: string, hash: string | null, person: string | null = null) {
  return nebenbei((async () => {
    const t = Date.now(), netz = await netzKennung(req), ua = txt(req.headers.get("user-agent"), 200), kennung = fzKennung(hash);
    const schl = `${kennung || "-"}|${netz}`;
    if (t - (FZ_ZULETZT.get(schl) || 0) < FZ.gleichMin * 60000) return;
    if (t - FZ_STUNDE.ab > 3600000) FZ_STUNDE = { ab: t, n: 0 };
    if (++FZ_STUNDE.n > FZ.proStunde) return;
    FZ_ZULETZT.set(schl, t); if (FZ_ZULETZT.size > 500) for (const [k, v] of FZ_ZULETZT) if (t - v > FZ.gleichMin * 60000) FZ_ZULETZT.delete(k);
    const h: any = {};
    if (grund === "gesperrt" && person) h.gesperrt = { person };
    if (hash && !h.gesperrt) {
      const { data: alt } = await db.from("kc_club_zugang_alt").select("person_id,ersetzt_am,grund").eq("token_hash", hash).maybeSingle();
      if (alt) { grund = "alt"; h.alt = { person: alt.person_id, grund: alt.grund, am: new Date(alt.ersetzt_am).toLocaleDateString("de-DE", { timeZone: "Europe/Berlin" }) }; }
    }
    const n0 = NETZ_ANGEMELDET.get(netz);
    if (n0 && t - n0.t < FZ.netzMin * 60000) h.netz = { person: n0.person, minVorher: Math.round((t - n0.t) / 60000) };
    if (!h.netz) { // auch aus den „Fenster“-Meldungen der letzten Stunde (alle Server-Instanzen)
      const { data: fe } = await db.from("kc_club_person_einstellung").select("person_id,wert").eq("schluessel", "fenster").contains("wert", { liste: [{ n: netz }] }).limit(5);
      const best = (fe ?? []).map((x: any) => ({ person: x.person_id, t: Math.max(...((x.wert?.liste || []).filter((y: any) => y?.n === netz).map((y: any) => Number(y.t) || 0))) }))
        .filter((x: any) => t - x.t < FZ.netzMin * 60000).sort((a: any, b: any) => b.t - a.t)[0];
      if (best) h.netz = { person: best.person, minVorher: Math.max(0, Math.round((t - best.t) / 60000)) };
    }
    if (!h.gesperrt && !h.alt && !h.netz && ua.length > 30) { // genau dieser Browser schon bei einem Mitglied gesehen (Fehlerprotokoll der App, 30 Tage)
      const { data: pr } = await db.from("kc_club_protokoll").select("person_id").like("aktion", "fehler_%").eq("details->>ua", ua).not("person_id", "is", null)
        .gte("zeit", new Date(t - 30 * 86400000).toISOString()).limit(1);
      if (pr?.[0]) h.geraet = { person: pr[0].person_id };
    }
    const kand = [h.gesperrt?.person, h.alt?.person, h.netz?.person, h.geraet?.person].filter(Boolean) as string[];
    const leute = kand.length ? await personen(kand) : new Map();
    const v = fzVermutung(h, new Map([...leute].map(([id, pe]) => [id, pe?.display_name || id])));
    const geraet = fzGeraet(ua);
    await db.from("kc_club_fremdzugriff").insert({ grund, schluessel: kennung, person_vermutung: v.person, vermutung: v.text.slice(0, 300), netz, geraet, ua,
      version: txt(req.headers.get("x-club-version"), 20) || null, land: txt(req.headers.get("cf-ipcountry") || req.headers.get("x-country"), 8) || null });
    const { count } = await db.from("kc_club_fremdzugriff").select("id", { count: "exact", head: true }).gte("zeit", new Date(t - FZ.alarmFensterMin * 60000).toISOString());
    if (!fzAlarm(count ?? 0, FZ_ALARM_MS, t, /^Programm/.test(geraet))) return;
    const { count: schon } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "fremd_alarm").gte("zeit", new Date(t - FZ.alarmPauseMin * 60000).toISOString());
    FZ_ALARM_MS = t; if (schon) return;
    await protokoll(null, "fremd_alarm", { anzahl: count ?? 0, geraet, vermutung: v.text.slice(0, 120) });
    const ziel = await adminIds();
    if (ziel.length) await routerSenden("club_nachricht_push", ziel, {
      titel: `🕵️ ${count ?? 1} fremde${(count ?? 1) === 1 ? "r" : ""} Anmeldeversuch${(count ?? 1) === 1 ? "" : "e"}`, kurz: `${geraet} · ${v.text.slice(0, 90)}`,
      betreff: "Köcheclub-App: fremde Anmeldeversuche", text: `In den letzten ${FZ.alarmFensterMin} Minuten wurden ${count ?? 1} Anmeldungen abgelehnt.\nLetzter Versuch: ${geraet}\nVermutung: ${v.text}\n\nEinzelheiten: Club-App → Sicherheits-Check.`,
      url: `${APP_URL}#fremdzugriffe`, eilig: true,
    }, `club-fremd:${t}`);
  })().catch((e) => console.error("fremdzugriff", String(e))));
}
async function anmelden(req: Request): Promise<Ich> {
  const token = req.headers.get("x-club-token") ?? "";
  if (!/^[0-9a-f]{32,96}$/.test(token)) { if (token) fremdMerken(req, "kaputt", null); throw new Fehler("Kein Zugang – bitte den persönlichen Link neu öffnen.", 401); }
  const hash = await sha256(token), jetztMs = Date.now(), version = txt(req.headers.get("x-club-version"), 20) || null;
  const c = ANMELDUNGEN.get(hash);
  if (c && c.bis > jetztMs) {
    if (jetztMs - c.gesehen > ZULETZT_TAKT_MS || c.version !== version) {
      c.gesehen = jetztMs; c.version = version;
      db.from("kc_club_zugang").update({ zuletzt_gesehen: jetzt(), app_version: version }).eq("person_id", c.ich.person_id).then(() => {});
    }
    ANMELDUNG_TREFFER = true;
    return { ...c.ich, aemter: [...c.ich.aemter] };
  }
  ANMELDUNG_TREFFER = false;
  const ich = await anmeldenDb(hash, version, req.headers.get("user-agent") || "", req);
  netzKennung(req).then((n) => { NETZ_ANGEMELDET.set(n, { person: ich.person_id, t: Date.now() }); if (NETZ_ANGEMELDET.size > 400) NETZ_ANGEMELDET.delete(NETZ_ANGEMELDET.keys().next().value!); }).catch(() => {}); // 2.579.0
  if (ANMELDUNGEN.size >= ANMELDUNG_CACHE_MAX) for (const [k, v] of ANMELDUNGEN) if (v.bis <= jetztMs) ANMELDUNGEN.delete(k);
  if (ANMELDUNGEN.size < ANMELDUNG_CACHE_MAX) ANMELDUNGEN.set(hash, { ich: { ...ich, aemter: [...ich.aemter] }, bis: jetztMs + ANMELDUNG_CACHE_MS, gesehen: jetztMs, version });
  return ich;
}
async function anmeldenDb(hash: string, version: string | null, ua = "", req?: Request): Promise<Ich> {
  // 0.56.1: eine Datenbank-Runde (kc_club_anmeldung: Token-Hash prüfen, „zuletzt gesehen“ setzen, Person + Rollen liefern)
  let { data: a, error } = await db.rpc("kc_club_anmeldung", { p_hash: hash, p_version: version });
  if (error) throw new Fehler("Anmeldung gerade nicht möglich – bitte gleich noch einmal versuchen.", 503);
  // KC-CLUB-ZUGANG-VORMERKEN (1.96.0): vorgemerkter neuer Link wird beim ersten Öffnen übernommen – erst dann gilt der alte nicht mehr
  if (!a) {
    const { data: vm } = await db.from("kc_club_zugang").update({ token_hash: hash, neu_token_hash: null, neu_bis: null, erstellt_am: jetzt() })
      .eq("neu_token_hash", hash).gt("neu_bis", jetzt()).eq("aktiv", true).select("person_id");
    if (vm?.length) { anmeldungenVergessen(); await rtNeu(vm[0].person_id); await protokoll(vm[0].person_id, "zugang_uebernommen", {}); }
    // 2.1.1: auch wenn eine gleichzeitige Anfrage die Übernahme gerade gemacht hat – jetzt nochmal normal prüfen
    ({ data: a, error } = await db.rpc("kc_club_anmeldung", { p_hash: hash, p_version: version }));
    if (error) throw new Fehler("Anmeldung gerade nicht möglich – bitte gleich noch einmal versuchen.", 503);
  }
  if (!a) { if (req) fremdMerken(req, "unbekannt", hash); throw new Fehler("Kein Zugang – bitte den persönlichen Link neu öffnen.", 401); }
  const p = a.person, r = a.rollen;
  if (!p?.active) { if (req) fremdMerken(req, "gesperrt", hash, p?.person_id || null); throw new Fehler("Kein Zugang – bitte bei Hansi melden.", 401); }
  // KC-CLUB-ONLINE-PUSH (1.57.0): nach ≥ 10 Min. Pause (oder zum ersten Mal) wieder da → Admins benachrichtigen (im Hintergrund)
  if (!a.vorher || Date.now() - Date.parse(a.vorher) >= ONLINE_PUSH_PAUSE_MS) {
    const lauf = onlinePushMelden(ichAus(p, r), ua).catch((e) => console.error("online push", String(e)));
    try { (globalThis as any).EdgeRuntime?.waitUntil?.(lauf); } catch { /* ohne Hintergrund-Hilfe läuft es trotzdem an */ }
  }
  return ichAus(p, r);
}
// ----- 2.422.0 KC-CLUB-ZUGANG (Wunsch Hansi „den Zugang für Gäste und Aushilfen einschränken: Nachrichten schreiben, SOS, Clubtermine, Spiele“) -----
// Zugang aus kc_club_rollen.zugang: „mitglied“ (alles wie bisher), „aushilfe“, „gast“. Admin ist immer „mitglied“. Für Gäste und Aushilfen gilt
// NUR, was hier steht – alles andere lehnt aktionAusfuehren mit 403 ab (auf allen Wegen: Anfrage, geplante Nachricht, Notfall-Paket, Nachtrag).
// Gast: Termine, Nachrichten (an alle), SOS (nur Clubleitung), Spiele (auch gegen Mitglieder), Hilfe/Einstellungen/Technik.
// Aushilfe: dazu Mein Dienst/Dienstwünsche, Fotoalbum nur ansehen, Schulung. Kein Ablaufdatum (Hansi sperrt von Hand).
// Dieselbe Liste steht in app.js (ZUGANG_AKTIONEN) – der Vertragstest prüft, dass beide gleich sind.
type Zugang = "mitglied" | "aushilfe" | "gast";
const ZUGANG_AKTIONEN: Record<"basis" | "aushilfe", readonly string[]> = {
  basis: ["init", "kurzcode_erzeugen", "ping", "diagnose", "online", "start_melden", "spur_melden", "nutzung_melden", "video_bewerten", "stimmen",
    "vorlese_stimmen", "sicherheit_pruefen", "verbindung_melden", "sicherheit_melden", "lebenszeichen", "notbetrieb_nachtragen", "zugang_link_mailen",
    "wetter", "wetter_ort_suchen", "treffen_liste", "treffen_antwort", "erinnerung_setzen", "kalender", "kalender_abo", "kalender_abo_holen", "privattermin_speichern",
    "privattermin_loeschen", "privattermine_liste", "countdowns", "terminumfragen_liste", "terminumfrage_antwort", "mitglieder", "mitglied_details",
    "unterhaltungen", "unterhaltung", "unterhaltung_stand", "tippen_stand", "tippen", "nachricht_senden", "nachricht_details", "einzelchat_finden", "express_stand", "express_angezeigt",
    "express_antwort", "startnachricht_bestaetigen", "stadt_woche", "ferien", "geplant_speichern", "geplant_loeschen", "geplant_jetzt", "geplant_abrufen", "reaktion_setzen", "nachricht_loeschen", "nachricht_zurueckholen",
    "chat_selbstloeschen", "link_vorschau", "unterstuetzung_meine", "unterstuetzung_senden", "nachricht_bearbeiten", "nachricht_merken", "gemerkte_nachrichten", "chat_umfrage_stimmen", "nachricht_ausblenden",
    "unterhaltung_ausblenden", "unterhaltung_archivieren", "unterhaltung_leeren", "gruppe_verlassen", "anlage_hochladen", "anlage_url",
    "einmal_foto_ansehen", "meine_nachrichten_statistik", "mf_antwort", "mf_gelesen", "sos_kontakte", "sos_ort", "notfall_setzen", "spiele_liste",
    "spiel_holen", "spiel_herausfordern", "spiel_antwort", "spiel_zug", "spiel_aufgeben", "spiel_revanche", "raetsel_stand", "raetsel_ergebnis",
    "status_setzen", "einstellung_setzen", "benachrichtigung_setzen", "meine_daten", "avatar_bilder", "avatar_verlauf", "avatar_foto_setzen", "sprache_woerter",
    "sprache_lernen", "sprache_training", "sprache_training_reset", "sprache_vergessen", "sprache_unbekannt", "twinkey_daten", "twinkey_frage",
    "twinkey_gelesen", "fehler_melden", "hilfe_anfordern", "feedback_meins", "feedback_senden", "feedback_neu", "vorfuehren_antwort", "vorfuehren_holen",
    "vorfuehren_senden", "vorfuehren_ende", "vorfuehren_bild", "schnappschuss_antwort", "schnappschuss_bild", "schnappschuss_ende", "fernbedienung_melden", "push_anmelden",
    "push_pruefen", "geraete_liste", "geraet_entfernen", "andere_geraete_abmelden", "push_abmelden", "push_test"],
  aushilfe: ["mein_dienst", "dienstwunsch_laden", "dienstwunsch_speichern", "dienst_gruss", "dienste", "dienst_freigabe", "meine_eingaben",
    "eingaben_bestaetigen", "wunschbogen_mailen", "eingaben_ablegen", "fotos_neueste", "fotos_liste", "foto_oeffnen",
    "schulung_meine", "schulung_antwort",
    "sondereinsatz_zusage", "stunden_melden", "mein_ausweis", "dienst_stand", "dienst_buchen", "dienst_korrigieren", "dienst_tausch_liste", "dienst_tausch_anbieten", "dienst_tausch_aktion"], // 2.590.0: Aushilfen dürfen sich auch anmelden (Hansi 22.10.); 2.606.0: und Dienste tauschen
};
const ZUGANG_ERLAUBT = { gast: new Set(ZUGANG_AKTIONEN.basis), aushilfe: new Set([...ZUGANG_AKTIONEN.basis, ...ZUGANG_AKTIONEN.aushilfe]) };
const zugangAus = (r: any): Zugang => (r?.ist_admin ? "mitglied" : r?.zugang === "gast" || r?.zugang === "aushilfe" ? r.zugang : "mitglied");
// 2.422.0 KC-CLUB-ZUGANG: Gäste/Aushilfen nie Protokolle, nie Kontaktdaten anderer (unabhängig von den Schaltern im Rollen-Fenster)
const zugangAnwenden = (ich: Ich): Ich => (ich.zugang === "mitglied" ? ich : { ...ich, protokolle: false, kontakte: false });
function zugangPruefen(a: string, ich: Ich) {
  if (ich.zugang === "mitglied" || ZUGANG_ERLAUBT[ich.zugang].has(a)) return;
  throw new Fehler(ich.zugang === "gast" ? "Das ist für Gäste nicht freigeschaltet." : "Das ist für Aushilfen nicht freigeschaltet.", 403);
}
// Person + Rollen → angemeldetes Mitglied (gemeinsam für Anmeldung und Notfall-Paket – eine Regel, nicht zwei)
function ichAus(p: any, r: any): Ich {
  return zugangAnwenden({ person_id: p.person_id, name: p.display_name, vorname: vorname(p), admin: !!r?.ist_admin, vorstand: !!(r?.ist_vorstand || r?.ist_admin), aemter: r?.aemter ?? [], zugang: zugangAus(r),
    // Sitzungsprotokolle: Recht aus der Rollen-Registry (Standard ja; Aushilfen nein)
    protokolle: r ? r.protokolle_lesen !== false : true,
    // Kontaktdaten anderer (sofern freigegeben): Rollen-Registry (Standard ja; Aushilfen nein)
    kontakte: r ? r.kontakte_sehen !== false : true,
    buero: r?.ist_admin ? "schreiben" : (BUERO_RECHTE as readonly string[]).includes(r?.buero_recht) ? r.buero_recht : null });
}
// „vorstand“ ist intern das Recht, Treffen/Veranstaltungen/Abstimmungen anzulegen (im Club: Clubsprecher, Kassenwart, Admin)
const nurVorstand = (ich: Ich) => { if (!ich.vorstand) throw new Fehler("Das dürfen nur Clubsprecher, Kassenwart und Admin.", 403); };
const nurBueroLesen = (ich: Ich) => { if (!ich.buero) throw new Fehler("Das Büro ist für dich nicht freigeschaltet – bitte beim Admin melden.", 403); };
const nurBueroSchreiben = (ich: Ich) => { nurBueroLesen(ich); if (ich.buero !== "schreiben") throw new Fehler("Im Büro hast du nur Leserechte – Ändern und Versenden schaltet der Admin frei.", 403); };
// Termine anlegen/ändern/absagen: Clubleitung wie bisher – oder Büro mit Schreibrecht (endgültig löschen bleibt Clubleitung)
const nurTermineSchreiben = (ich: Ich) => { if (!ich.vorstand && ich.buero !== "schreiben") nurVorstand(ich); };
const nurAdmin = (ich: Ich) => { if (!ich.admin) throw new Fehler("Das darf nur der Admin.", 403); };

// ---------- KC-CLUB-SCHACH-UHR (2.23.38): Zeitüberschreitung ----------
// Zeit abgelaufen? Dann die Partie beenden (egal wer gerade nachsieht) und beiden Bescheid geben. Gibt die aktuelle Zeile zurück.
async function schachUhrPruefen(g: any) {
  if (g?.spiel !== "schach" || !g.uhr?.seit || g.status !== "laeuft" || !g.dran) return g;
  const s = schachUhrSeite(g, g.dran), ueber = Date.now() - Date.parse(g.uhr.seit) - Number(g.uhr.rest?.[s]);
  if (!(ueber > SCHACH_UHR_GNADE_MS)) return g;
  const verlierer = g.dran, gewinner = g.von === verlierer ? g.an : g.von, remis = !schachKannMatt(g.brett, s === "x" ? "b" : "w");
  const { data: neu } = await db.from("kc_club_spiele").update({ status: "beendet", dran: null, gewinner: remis ? "remis" : gewinner,
    uhr: { ...g.uhr, rest: { ...g.uhr.rest, [s]: 0 }, seit: null, aus: s }, geaendert_am: jetzt() })
    .eq("id", g.id).eq("zuege", g.zuege).eq("status", "laeuft").select("*").maybeSingle();
  if (!neu) { const { data: jetztG } = await db.from("kc_club_spiele").select("*").eq("id", g.id).maybeSingle(); return jetztG ?? g; }
  const titel = remis ? "♟️ Zeit abgelaufen – Remis" : null;
  await spielPush(verlierer, { titel: titel ?? "♟️ Deine Zeit ist abgelaufen", kurz: remis ? "Zu wenig Material zum Mattsetzen – unentschieden." : "Die Partie ist verloren – Revanche?", text: remis ? "Deine Bedenkzeit ist abgelaufen, aber dein Gegenüber konnte nicht mehr mattsetzen – Remis." : "Deine Bedenkzeit im Schach ist abgelaufen – die Partie ist verloren." }, g.id, `club-spiel:${g.id}:zeit`);
  await spielPush(gewinner, { titel: titel ?? "♟️ Zeit abgelaufen – du hast gewonnen!", kurz: remis ? "Zu wenig Material zum Mattsetzen – unentschieden." : "Die Bedenkzeit deines Gegenübers ist um.", text: remis ? "Die Bedenkzeit deines Gegenübers ist abgelaufen, du konntest aber nicht mehr mattsetzen – Remis." : "Die Bedenkzeit deines Gegenübers ist abgelaufen – du hast gewonnen." }, g.id, `club-spiel:${g.id}:zeit`);
  return neu;
}

// ---------- Eigener Status ----------
const STATUS = ["verfuegbar", "beschaeftigt", "urlaub", "krank", "abwesend"];
async function statusMap(ids?: string[], mitRuhe = false) {
  let q = db.from("kc_club_status").select("person_id,status,hinweis,bis,geaendert_am");
  if (ids) q = q.in("person_id", ids);
  const { data } = await q;
  const heute = berlinTag(new Date());
  // abgelaufener Status („bis“ vorbei) gilt wieder als verfügbar
  const m = new Map<string, any>((data ?? []).map((x: any) => [x.person_id, x.bis && x.bis < heute ? { status: "verfuegbar", hinweis: null, bis: null } : { status: x.status, hinweis: x.hinweis, bis: x.bis }]));
  // KC-CLUB-STATUS-RUHE (1.50.0): wer gerade in seiner „Nicht stören“-Zeit ist und sonst „verfügbar“ wäre, zeigt „🌙 nicht stören bis …“
  // (nur Anzeige – gespeichert wird nichts; Urlaub/krank/… haben Vorrang)
  if (mitRuhe) {
    let rq = db.from("kc_club_person_einstellung").select("person_id,wert").eq("schluessel", "ruhezeit");
    if (ids) rq = rq.in("person_id", ids);
    const { data: rz } = await rq;
    for (const x of rz ?? []) {
      const alt = m.get((x as any).person_id);
      if (inRuhezeit((x as any).wert) && (!alt || alt.status === "verfuegbar")) m.set((x as any).person_id, { status: "ruhe", hinweis: null, bis: null, uhr: (x as any).wert.bis });
    }
  }
  return m;
}

// ---------- Geburtstage (KC-CLUB-GEBURTSTAG-FREIGABE) ----------
// Nur wer „Meinen Geburtstag anzeigen“ eingeschaltet hat (eigener immer für sich selbst); nur Tag/Monat, nie das Jahr.
async function geburtstageSichtbar(ich: Ich) {
  const [leute, { data: fr }] = await Promise.all([
    aktiveMitglieder(),
    db.from("kc_club_freigaben").select("person_id").eq("bereich", "geburtstag").eq("erlaubt", true),
  ]);
  const frei = new Set((fr ?? []).map((x: any) => x.person_id));
  return leute.filter((m: any) => m.birth_date && (frei.has(m.person_id) || m.person_id === ich.person_id))
    .map((m: any) => ({ person_id: m.person_id, name: m.display_name, vorname: vorname(m), md: String(m.birth_date).slice(5, 10) }));
}

// ---------- Treffen ----------
async function treffenListe(ich: Ich, nurNaechstes = false, zeitraum?: { von: string; bis: string }) {
  let q = db.from("kc_club_treffen").select("*").order("beginn");
  // Zeitraum: alles, was ihn berührt (auch mehrtägige Veranstaltungen, die vorher beginnen)
  q = zeitraum ? q.lt("beginn", zeitraum.bis).or(`ende.gte.${zeitraum.von},and(ende.is.null,beginn.gte.${zeitraum.von})`).limit(100)
    : nurNaechstes ? q.gte("beginn", new Date(Date.now() - 3 * 3600000).toISOString()).eq("status", "geplant").eq("art", "treffen").limit(1)
    : q.gte("beginn", new Date(Date.now() - 30 * 86400000).toISOString()).limit(60);
  const { data: treffen } = nurNaechstes && !zeitraum ? await treffenGemerkt("naechstes", () => q) : await q; // KC-CLUB-START-SPARSAM-2
  const ids = (treffen ?? []).map((t: any) => t.id);
  const { data: teil } = ids.length ? await db.from("kc_club_teilnahme").select("*").in("treffen_id", ids) : { data: [] as any[] };
  const [leute, mitfahrten, suche, anl] = await Promise.all([
    personen([...(teil ?? []).map((x: any) => x.person_id), ...(treffen ?? []).map((t: any) => t.gastgeber_person_id)]),
    nurNaechstes ? Promise.resolve(new Map<string, any[]>()) : mitfahrtenZu(ich, "treffen", ids),
    nurNaechstes ? Promise.resolve(new Map<string, any[]>()) : suchendeZu(ich, "treffen", ids),
    nurNaechstes ? Promise.resolve(new Map<string, any[]>()) : objAnlagenHolen("treffen", ids), // 2.461.0 KC-CLUB-TERMIN-LINK-PROSPEKT: Prospekt (Foto/PDF)
  ]);
  return (treffen ?? []).map((t: any) => {
    const tn = (teil ?? []).filter((x: any) => x.treffen_id === t.id)
      .map((x: any) => ({ person_id: x.person_id, name: leute.get(x.person_id)?.display_name || x.person_id, antwort: x.antwort, notiz: x.notiz }))
      .sort((a: any, b: any) => a.name.localeCompare(b.name));
    const zahl = (a: string) => tn.filter((x: any) => x.antwort === a).length;
    return {
      id: t.id, titel: t.titel, beginn: t.beginn, ende: t.ende, ort: t.ort, beschreibung: t.beschreibung, status: t.status, art: t.art, ganztaegig: t.ganztaegig,
      gastgeber: t.gastgeber_person_id ? { person_id: t.gastgeber_person_id, name: leute.get(t.gastgeber_person_id)?.display_name } : null,
      teilnahme: tn, ja: zahl("ja"), nein: zahl("nein"), vielleicht: zahl("vielleicht"),
      meine: tn.find((x: any) => x.person_id === ich.person_id)?.antwort ?? null,
      mitfahrten: mitfahrten.get(t.id) ?? [], mitfahrtSuche: suche.get(t.id) ?? [],
      link: t.link ?? null, imLaufband: !!t.im_laufband, anlagen: anl.get(t.id) ?? [], // 2.461.0 KC-CLUB-TERMIN-LINK-PROSPEKT
    };
  });
}
function treffenText(t: any, gastgeber: string, anlass: "neu" | "geaendert" | "abgesagt") {
  const ort = t.ort || (gastgeber ? `bei ${gastgeber}` : "");
  const va = t.art === "veranstaltung"; // Veranstaltung (Aufbau, Markt …): keine Einladung, keine Zu-/Absage
  const kopf = anlass === "abgesagt" ? (va ? "dieser Termin fällt leider aus:" : "das Köcheclub-Treffen fällt leider aus:") : anlass === "geaendert" ? (va ? "dieser Termin hat sich geändert:" : "das Köcheclub-Treffen hat sich geändert:") : (va ? "neuer Termin im Köcheclub:" : "hiermit lade ich dich herzlich zum Köcheclub-Treffen ein:");
  return {
    betreff: `Köcheclub Werne – ${anlass === "abgesagt" ? "abgesagt: " : anlass === "geaendert" ? "geändert: " : ""}${t.titel}, ${wann(t.beginn)}`,
    titel: anlass === "abgesagt" ? "❌ Treffen abgesagt" : "📅 " + t.titel,
    kurz: `${wann(t.beginn)}${ort ? " – " + ort : ""}${anlass === "abgesagt" ? " fällt aus." : va ? "" : ". Bitte in der App zu- oder absagen."}`,
    text: ["Hallo,", "", kopf, "", `📅 ${wann(t.beginn, true)}`, ort ? `📍 ${ort}` : "", t.beschreibung ? "\n" + t.beschreibung : "", "",
      anlass === "abgesagt" ? "" : va ? `Alle Termine in der Köcheclub-App: ${APP_URL}#termine` : `Bitte sag in der Köcheclub-App zu oder ab: ${APP_URL}#termine`, "", "Viele Grüße", "Köcheclub Werne"]
      .filter((z, i, a) => !(z === "" && a[i - 1] === "")).join("\n"),
    url: APP_URL + "#termine",
  };
}

// ---------- KC-CLUB-NOTFALL-NEUSTART (2.235.0, Wunsch Hansi nach dem Ausfall 11.10. 04:21–04:46) ----------
// Hängt die Datenbank-Schnittstelle (PostgREST), kommt kein normaler Aufruf mehr an die Daten – auch nicht die Anmeldung.
// Darum läuft diese Aktion VOR der normalen Anmeldung und nur über den direkten Datenbank-Weg (SUPABASE_DB_URL):
//   - Admin (persönlicher Link, geprüft mit kc_club_anmeldung direkt in der Datenbank) oder
//   - der GitHub-Schnittstellen-Wächter (von GitHub signiertes Token, nur dieser Ablauf auf main; darf nur neu starten, wenn es wirklich hängt).
// Neustart über die Supabase-Verwaltungsschnittstelle mit dem Schlüssel aus dem Vault (kc_supabase_neustart_token, nie im Browser).
// Kritische Aktion (AGENTS 10): Prüfen → Auswirkung zeigen → Bestätigung → Ausführen → Nachprüfen (App) → Protokoll. Sperre 20 Min.
const NEUSTART_VAULT = "kc_supabase_neustart_token", NEUSTART_SPERRE_MIN = 20, PROJEKT_REF = SUPA.replace(/^https:\/\//, "").split(".")[0];
const GH_OIDC = "https://token.actions.githubusercontent.com";
const GH_JWKS = createRemoteJWKSet(new URL(GH_OIDC + "/.well-known/jwks"));
let DIREKT: ReturnType<typeof postgres> | null = null;
const direktSql = () => (dbPufferLeeren(), DIREKT ??= postgres(Deno.env.get("SUPABASE_DB_URL")!, { max: 1, prepare: false, connect_timeout: 10, idle_timeout: 20 })); // KC-CLUB-DB-SPARSAM: direkter Weg → Puffer leeren
async function neustartWaechter(req: Request) {
  const t = (req.headers.get("authorization") || "").replace(/^Bearer\s+/i, "");
  if (!t.startsWith("ey")) return false;
  try {
    const { payload: p } = await jwtVerify(t, GH_JWKS, { issuer: GH_OIDC, audience: "kc-neustart", maxTokenAge: "10m" });
    return p.repository === "Sire65/KC-Clubapp" && p.repository_id === "1392489961" && p.repository_owner_id === "297908448" && p.ref === "refs/heads/main" && p.workflow_ref === "Sire65/KC-Clubapp/.github/workflows/schnittstellen-waechter.yml@refs/heads/main"; // 2.350.0: zusätzlich feste Repository-/Besitzer-Nummer (Umbenennen/Namensklau)
  } catch { return false; }
}
async function neustartAdmin(req: Request) {
  const token = req.headers.get("x-club-token") ?? "";
  if (!/^[0-9a-f]{32,96}$/.test(token)) return null;
  const [z] = await direktSql()`select public.kc_club_anmeldung(${await sha256(token)}, ${null}) as a`;
  const a: any = z?.a;
  return a?.person?.active && a?.rollen?.ist_admin ? { person_id: String(a.person.person_id), name: String(a.person.display_name || "") } : null;
}
async function schnittstelleTesten() {
  const t0 = Date.now();
  try {
    const r = await fetch(`${SUPA}/rest/v1/kc_club_tippen?select=person_id&limit=1`, { headers: { apikey: SERVICE, authorization: `Bearer ${SERVICE}` }, signal: AbortSignal.timeout(8000) });
    await r.body?.cancel();
    return { ok: r.status < 500, ms: Date.now() - t0 };
  } catch { return { ok: false, ms: Date.now() - t0 }; }
}
async function neustartProtokoll(person: string | null, details: Record<string, unknown>) {
  try { await direktSql()`insert into public.kc_club_protokoll (person_id, aktion, details) values (${person}, 'notfall_neustart', ${direktSql().json(details as any)})`; }
  catch (e) { console.error("neustart protokoll", String(e)); }
}
async function notfallNeustart(req: Request, p: any) {
  const waechter = await neustartWaechter(req), admin = waechter ? null : await neustartAdmin(req).catch(() => null);
  if (!waechter && !admin) return json({ error: "Nur für den Admin." }, 403);
  const modus = String(p?.modus || "pruefen");
  const [sch] = await direktSql()`select decrypted_secret as s from vault.decrypted_secrets where name = ${NEUSTART_VAULT} limit 1`;
  const schluessel = String(sch?.s || "");
  const [lz] = await direktSql()`select zeit, details from public.kc_club_protokoll where aktion = 'notfall_neustart' and details->>'schritt' = 'angefordert' order by zeit desc limit 1`;
  const letzter = lz?.zeit ? new Date(lz.zeit).toISOString() : null;
  if (modus === "pruefen") return json({ ok: true, schnittstelle: await schnittstelleTesten(), schluessel: !!schluessel, letzter });
  if (modus === "schluessel") {
    if (!admin) return json({ error: "Nur für den Admin." }, 403);
    const neu = String(p?.schluessel || "").trim();
    if (!/^sbp_[A-Za-z0-9_]{20,200}$/.test(neu)) return json({ error: "Das sieht nicht wie ein Supabase-Schlüssel aus (beginnt mit „sbp_“)." }, 400);
    const r = await fetch(`https://api.supabase.com/v1/projects/${PROJEKT_REF}`, { headers: { authorization: `Bearer ${neu}` }, signal: AbortSignal.timeout(15000) }).catch(() => null);
    await r?.body?.cancel();
    if (!r?.ok) return json({ error: `Supabase lehnt den Schlüssel ab (${r?.status ?? "keine Antwort"}). Bitte Projekt und Rechte prüfen.` }, 400);
    const [v] = await direktSql()`select id from vault.secrets where name = ${NEUSTART_VAULT} limit 1`;
    if (v?.id) await direktSql()`select vault.update_secret(${v.id}, ${neu})`;
    else await direktSql()`select vault.create_secret(${neu}, ${NEUSTART_VAULT}, 'KC-CLUB-NOTFALL-NEUSTART: Supabase-Verwaltungsschlüssel (nur Neustart dieses Projekts)')`;
    await neustartProtokoll(admin.person_id, { schritt: "schluessel_hinterlegt" });
    return json({ ok: true });
  }
  if (modus !== "neustart") return json({ error: "Unbekannt" }, 400);
  if (admin && p?.bestaetigt !== true) return json({ error: "Bitte bestätigen." }, 400);
  if (!schluessel) return json({ error: "Kein Neustart-Schlüssel hinterlegt.", ohneSchluessel: true }, 409);
  const vorher = await schnittstelleTesten();
  if (waechter && vorher.ok) return json({ ok: false, text: "Schnittstelle antwortet – kein Neustart." }); // Wächter nur im echten Störfall
  if (letzter && Date.now() - Date.parse(letzter) < NEUSTART_SPERRE_MIN * 60000) return json({ error: `Vor weniger als ${NEUSTART_SPERRE_MIN} Minuten wurde schon neu gestartet – bitte abwarten.` }, 429);
  const st = await fetch(`https://api.supabase.com/v1/projects/${PROJEKT_REF}`, { headers: { authorization: `Bearer ${schluessel}` }, signal: AbortSignal.timeout(15000) }).then((r) => r.ok ? r.json() : null).catch(() => null);
  if (st?.status && st.status !== "ACTIVE_HEALTHY") return json({ error: `Supabase ist gerade nicht im Normalzustand (${st.status}) – kein Neustart.` }, 409);
  const r = await fetch(`https://api.supabase.com/v1/projects/${PROJEKT_REF}/restart`, { method: "POST", headers: { authorization: `Bearer ${schluessel}` }, signal: AbortSignal.timeout(30000) }).catch(() => null);
  await r?.body?.cancel();
  await neustartProtokoll(admin?.person_id ?? null, { schritt: r?.ok ? "angefordert" : "abgelehnt", wer: waechter ? "waechter" : "admin", http: r?.status ?? 0, schnittstelle_vorher: vorher });
  if (!r?.ok) return json({ error: `Supabase hat den Neustart abgelehnt (${r?.status ?? "keine Antwort"}).` }, 502);
  return json({ ok: true, text: "Neustart läuft – dauert 1 bis 3 Minuten." });
}

// ---------- KC-CLUB-ARCHIV-KOPIE (2.232.0, Wunsch Hansi 11.10.2026) ----------
// Zweite Kopie aller Archiv-Dateien im Neon-Dateispeicher Frankfurt (Projekt „KC Archiv Kopie“, Fach „kc-archiv“, privat, 5 GB gratis).
// Zugang nur im Vault (kc_club_archiv_kopie: endpoint, region, bucket, key, secret) – nie im Browser, Repository oder Protokoll.
// Läuft im Zeitplaner („wartung“) nur nachts 2–5 Uhr; je Lauf höchstens ARCHIV_KOPIE_JE_LAUF Dateien bzw. ARCHIV_KOPIE_MAX_BYTES.
// Gelöschte Dokumente bleiben noch ARCHIV_KOPIE_NACHLAUF_TAGE in der Kopie (Papierkorb), dann wird die Kopie entfernt.
const ARCHIV_KOPIE_GRENZE = 5 * 1024 * 1024 * 1024, ARCHIV_KOPIE_JE_LAUF = 25, ARCHIV_KOPIE_MAX_BYTES = 60 * 1024 * 1024, ARCHIV_KOPIE_NACHLAUF_TAGE = 30;
const archivKopieSchluessel = (dokId: string, attId: string) => `archiv/${dokId}/${attId}.enc`; // seit 2.369.0 verschlüsselt (KCE1)
async function archivKopieStand(status: "ok" | "warnung" | "fehler", text: string, metrics: Record<string, unknown>) {
  const { error } = await db.from("kc_club_archiv_kopie_stand").upsert({ id: 1, zeit: jetzt(), status, text: txt(text, 300), metrics });
  if (error) console.error("archiv kopie stand", error.message);
}
// KC-CLUB-ARCHIV-KOPIE Stufe 2 (2.233.0, Wunsch Hansi): PDF-Handbücher (Club-App „dokumente/“) und Schulungsunterlagen der Kasse.
// Quellen-Register: neue PDFs in diesen Paketen kommen von selbst mit. Liste über die GitHub-Schnittstelle (öffentlich, ohne Schlüssel),
// Dateien über raw.githubusercontent.com; Prüfung mit der Git-Prüfsumme (SHA-1 „blob <Länge>\0…“). Aus GitHub entfernte Dateien bleiben in der Kopie.
const DOKUMENT_QUELLEN: { paket: string; muster: RegExp }[] = [
  { paket: "Sire65/KC-Clubapp", muster: /^dokumente\/[^/]+\.pdf$/i },
  { paket: "Sire65/Kasse", muster: /\.pdf$/i },
];
const DOKUMENT_KOPIE_MAX_BYTES = 40 * 1024 * 1024;
async function gitBlobSha(inhalt: Uint8Array) {
  const kopf = new TextEncoder().encode(`blob ${inhalt.length}\0`), alles = new Uint8Array(kopf.length + inhalt.length);
  alles.set(kopf); alles.set(inhalt, kopf.length);
  return [...new Uint8Array(await crypto.subtle.digest("SHA-1", alles))].map((x) => x.toString(16).padStart(2, "0")).join("");
}
async function dokumenteKopieLauf(s3: AwsClient, url: (k: string) => string, fehler: string[]) {
  const { data: kopien } = await db.from("kc_club_dokument_kopie").select("quelle,git_sha");
  const bekannt = new Map((kopien ?? []).map((k: any) => [k.quelle, k.git_sha]));
  const offen: { paket: string; pfad: string; sha: string; groesse: number }[] = [];
  for (const q of DOKUMENT_QUELLEN) {
    try {
      const r = await fetch(`https://api.github.com/repos/${q.paket}/git/trees/HEAD?recursive=1`, { headers: { accept: "application/vnd.github+json", "user-agent": "kc-club-archiv-kopie" }, signal: AbortSignal.timeout(15000) });
      if (!r.ok) throw new Error(`GitHub-Liste ${q.paket.split("/")[1]}: ${r.status}`);
      const j = await r.json();
      for (const t of j?.tree ?? []) if (t.type === "blob" && q.muster.test(String(t.path)) && bekannt.get(`${q.paket}:${t.path}`) !== t.sha) offen.push({ paket: q.paket, pfad: String(t.path), sha: String(t.sha), groesse: Number(t.size) || 0 });
    } catch (e) { fehler.push(txt(String((e as any)?.message || e), 80)); }
  }
  let kopiert = 0, bytes = 0;
  for (const d of offen) {
    if (bytes + d.groesse > DOKUMENT_KOPIE_MAX_BYTES && kopiert > 0) break; // Rest beim nächsten Lauf
    try {
      const r = await fetch(`https://raw.githubusercontent.com/${d.paket}/HEAD/${d.pfad.split("/").map(encodeURIComponent).join("/")}`, { signal: AbortSignal.timeout(60000) });
      if (!r.ok) throw new Error(`GitHub-Datei ${r.status}`);
      const inhalt = new Uint8Array(await r.arrayBuffer());
      if ((await gitBlobSha(inhalt)) !== d.sha) throw new Error("Prüfsumme weicht ab");
      const schluessel = `dokumente/${d.paket}/${d.pfad}`;
      const p = await s3.fetch(url(schluessel), { method: "PUT", body: inhalt, headers: { "content-type": "application/pdf", "x-amz-meta-git-sha": d.sha } });
      if (!p.ok) throw new Error(`Neon antwortet ${p.status}`);
      await p.body?.cancel();
      const { error } = await db.from("kc_club_dokument_kopie").upsert({ quelle: `${d.paket}:${d.pfad}`, git_sha: d.sha, schluessel, groesse: inhalt.length, kopiert_am: jetzt() });
      if (error) throw new Error("Verzeichnis nicht gespeichert");
      kopiert++; bytes += inhalt.length;
    } catch (e) { fehler.push(txt(String((e as any)?.message || e), 80)); }
  }
  return { kopiert, offen: Math.max(0, offen.length - kopiert) };
}
// Zugang zum Neon-Dateispeicher Frankfurt (Vault kc_club_archiv_kopie) – gemeinsam für Archiv-Kopie und Frankfurt-Sicherung
async function neonDateispeicher() {
  const { data: roh } = await db.rpc("kc_communication_get_server_secret", { p_name: "kc_club_archiv_kopie" });
  let z: any = null; try { z = roh ? JSON.parse(String(roh)) : null; } catch { z = null; }
  if (!z?.endpoint || !z?.bucket || !z?.key || !z?.secret) return null;
  // KC-CLUB-RC-PRUEFUNG (20.10.2026): höchstens 2 Wiederholungen (Standard wären 10 – ein gestörter Speicher hielte jeden Lauf minutenlang auf)
  const s3 = new AwsClient({ accessKeyId: z.key, secretAccessKey: z.secret, region: z.region || "eu-central-1", service: "s3", retries: 2 });
  const basis = `${String(z.endpoint).replace(/\/$/, "")}/${encodeURIComponent(z.bucket)}`;
  const url = (k: string) => `${basis}/${k.split("/").map(encodeURIComponent).join("/")}`;
  return { s3, url, basis, fach: String(z.bucket) };
}
const hexSha256 = async (b: Uint8Array) => [...new Uint8Array(await crypto.subtle.digest("SHA-256", b))].map((x) => x.toString(16).padStart(2, "0")).join("");
// KC-CLUB-FRA-VERSCHLUESSELT (Server 2.369.0, Auftrag Hansi 14.10.2026 „alles sicher machen“): nach Frankfurt nur noch verschlüsselt.
// Gleicher Schlüssel und gleiche Ableitung wie die Neon-Sicherung (Vault kc_db_backup_key_v1, AES-256-GCM, Schlüssel = SHA-256 des Geheimnisses),
// damit die Notfall-Kopie des Schlüssels (Cloudflare-Tresor / GitHub-Secret KC_BACKUP_KEY) auch diese Dateien öffnet (tools/notfall/fra-entschluesseln.mjs).
// Dateiformat: "KCE1" (4 Byte) + IV (12 Byte) + Chiffretext mit Prüfmarke. Fehlt der Schlüssel, wird NICHTS hochgeladen – nie Klartext.
const KCE_KOPF = "KCE1", KCE_CACHE_MS = 10 * 60 * 1000;
let kceCache: { k: CryptoKey; bis: number } | null = null;
async function kceSchluessel() {
  if (kceCache && kceCache.bis > Date.now()) return kceCache.k;
  const { data, error } = await db.rpc("kc_db_backup_key_v1");
  if (error || !data) throw new Error("Sicherungsschlüssel fehlt – nichts hochgeladen");
  const k = await crypto.subtle.importKey("raw", await crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(data))), { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
  kceCache = { k, bis: Date.now() + KCE_CACHE_MS };
  return k;
}
async function kceVerschluesseln(b: Uint8Array) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, await kceSchluessel(), b));
  const aus = new Uint8Array(16 + ct.length);
  aus.set(new TextEncoder().encode(KCE_KOPF)); aus.set(iv, 4); aus.set(ct, 16);
  return aus;
}
async function kceEntschluesseln(b: Uint8Array) {
  if (b.length < 32 || new TextDecoder().decode(b.subarray(0, 4)) !== KCE_KOPF) throw new Error("Datei ist nicht verschlüsselt");
  return new Uint8Array(await crypto.subtle.decrypt({ name: "AES-GCM", iv: b.subarray(4, 16) }, await kceSchluessel(), b.subarray(16)));
}

// ---------- KC-CLUB-FRA-SICHERUNG (2.236.0, Wunsch Hansi 11.10.2026) ----------
// Tägliche Komplett-Sicherung aller Tabellen (Schema public) als gepacktes JSON nach Neon Frankfurt: datenbank/<Tag>/<tabelle>[.teilNNN].json.gz
// + manifest.json (Teile, Zeilen, Prüfsummen, Spalten je Tabelle). Danach Rücklese-Test (jede Datei zurückholen, Prüfsumme + entpacken
// + Zeilen zählen). 14 Tagesstände; ältere werden gelöscht. Der Zeitplaner ruft nachts alle 2 Min. einen Schritt (CPU-Grenze der
// Edge Function: je Schritt höchstens FRA_SCHRITT_BYTES Rohdaten). Gelesen wird über den direkten Datenbank-Weg (nicht die Schnittstelle).
// Große Tabellen werden in Blockbereichen (ctid) gesichert – stabil auch während Änderungen. Status: kc_club_fra_sicherung_stand.
const FRA_BEHALTEN_TAGE = 14, FRA_BLOECKE = 400, FRA_TEIL_BYTES = 3 * 1024 * 1024, FRA_SCHRITT_BYTES = 8 * 1024 * 1024, FRA_SCHRITT_MS = 25000, FRA_VERSUCHE = 3, FRA_GRENZE = 5 * 1024 * 1024 * 1024;
async function fraStand(lauf: string, status: string, text: string, metrics: Record<string, unknown>) {
  const { error } = await db.from("kc_club_fra_sicherung_stand").upsert({ id: 1, lauf, zeit: jetzt(), status, text: txt(text, 300), metrics });
  if (error) console.error("fra stand", error.message);
}
async function fraGzip(b: Uint8Array) { return new Uint8Array(await new Response(new Blob([b]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer()); }
async function fraGunzip(b: Uint8Array) { return new Uint8Array(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("gzip"))).arrayBuffer()); }
// Zeilenadresse (ctid „(Block,Zeile)“) als Zahl: Block × 65536 + Zeile – block_von/block_bis speichern diese Codes
const fraTidCode = (c: string) => { const m = /^\((\d+),(\d+)\)$/.exec(String(c)); return m ? Number(m[1]) * 65536 + Number(m[2]) : 0; };
const fraTid = (code: number) => `'(${Math.floor(code / 65536)},${code % 65536})'::tid`;
const fraName = (t: string) => /^[a-z0-9_]{1,63}$/.test(t) ? t : null;
// 2.369.0: Spaltenliste mit Schwärzung wie im Neon-Spiegel (kc_db_mirror_redaction): Geheimnis-Spalten leer bzw. Muster ersetzt, Typ und Reihenfolge bleiben
async function fraSpalten(sql: any, name: string) {
  const [r] = await sql`select string_agg(case when x.column_name is not null and x.muster is not null
        then format('regexp_replace(%I::text, %L, %L, ''g'')::%s as %I', a.attname, x.muster, coalesce(x.ersatz, '[entfernt]'), format_type(a.atttypid, a.atttypmod), a.attname)
      when x.column_name is not null then format('null::%s as %I', format_type(a.atttypid, a.atttypmod), a.attname)
      else format('%I', a.attname) end, ', ' order by a.attnum) as s
    from pg_attribute a left join public.kc_db_mirror_redaction x on x.table_name = ${name} and x.column_name = a.attname
    where a.attrelid = format('public.%I', ${name}::text)::regclass and a.attnum > 0 and not a.attisdropped`;
  if (!r?.s) throw new Error("Spalten nicht lesbar");
  return String(r.s);
}
async function fraSchritt(jetztErzwingen = false) {
  const t0 = Date.now(), lauf = berlinTag(new Date()), sql = direktSql();
  const nz = await neonDateispeicher();
  if (!nz) { await fraStand(lauf, "fehler", "Zugang zum Neon-Dateispeicher fehlt", {}); return { ok: false }; }
  const { s3, url, basis, fach } = nz;
  // 1) Lauf des Tages anlegen: alle Tabellen, große in Blockbereiche geteilt
  const [{ n: vorhanden }] = await sql`select count(*)::int as n from public.kc_club_fra_sicherung where lauf = ${lauf}`;
  if (!vorhanden) {
    // Teile nach echter Größe (inkl. ausgelagerter Daten/TOAST): höchstens FRA_TEIL_BYTES je Teil, aufgeteilt in Blockbereiche
    // 2.369.0: als „secret“ eingestufte Tabellen (Spiegel-Register) kommen nicht mit – Geheimnisse gehören in keine Sicherung (AGENTS.md Regel 15)
    const tabs = await sql`select c.relname as t, (pg_relation_size(c.oid) / 8192)::bigint as seiten, pg_total_relation_size(c.oid)::bigint as gesamt from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'
      and not exists (select 1 from public.kc_db_mirror_table_rules r where r.table_name = c.relname and r.sensitivity = 'secret') order by 1`;
    const zeilen: any[] = [];
    for (const r of tabs) {
      if (!fraName(r.t)) continue;
      // klein: ganze Tabelle. Groß: zeilengenau nach echter Textgröße (ausgelagerte Daten werden beim Sichern viel größer als auf der Platte)
      if (Number(r.gesamt) <= FRA_TEIL_BYTES * 1.5 || Number(r.seiten) < 1) { zeilen.push({ lauf, tabelle: r.t, teil: 0, block_von: null, block_bis: null }); continue; }
      const liste = await sql.unsafe(`select ctid::text as c, octet_length(row_to_json(x)::text)::bigint as l from public."${r.t}" x order by ctid`);
      // KICC-F-107: Grenzen des letzten geprüften Laufs übernehmen, damit unveränderte Bereiche gleich bleiben (dann nur kopiert statt neu übertragen)
      const alt = await sql`select block_von from public.kc_club_fra_sicherung where tabelle = ${r.t} and block_von is not null
        and lauf = (select max(lauf) from public.kc_club_fra_sicherung where tabelle = ${r.t} and lauf < ${lauf} and status = 'geprueft') order by teil`;
      const { teile } = fraTeileStabil(liste.map((z: any) => ({ code: fraTidCode(z.c), l: Number(z.l) || 0 })), alt.map((a: any) => Number(a.block_von)), FRA_TEIL_BYTES);
      for (const x of teile) zeilen.push({ lauf, tabelle: r.t, ...x });
    }
    for (let i = 0; i < zeilen.length; i += 200) await sql`insert into public.kc_club_fra_sicherung ${sql(zeilen.slice(i, i + 200), "lauf", "tabelle", "teil", "block_von", "block_bis")} on conflict do nothing`;
    await fraStand(lauf, "laeuft", `Sicherung gestartet: ${tabs.length} Tabellen`, { teile: zeilen.length });
  }
  let roh = 0;
  // 2) Teile sichern (abholen, packen, Prüfsumme, nach Frankfurt)
  // Teil, bei dem der Server dreimal mitten im Sichern abgebrochen ist (zu groß o. Ä.): als Fehler melden statt endlos wiederholen
  await sql`update public.kc_club_fra_sicherung set status = 'fehler', fehler = 'Abbruch beim Sichern (Teil zu groß?)' where lauf = ${lauf} and status = 'laeuft' and zeit < now() - interval '5 minutes' and versuche >= ${FRA_VERSUCHE}`;
  while (Date.now() - t0 < FRA_SCHRITT_MS && roh < FRA_SCHRITT_BYTES) {
    const [t] = await sql`update public.kc_club_fra_sicherung f set status = 'laeuft', zeit = now(), versuche = f.versuche + 1
      where (f.lauf, f.tabelle, f.teil) = (select lauf, tabelle, teil from public.kc_club_fra_sicherung where lauf = ${lauf}
        and (status = 'offen' or (status = 'laeuft' and zeit < now() - interval '5 minutes' and versuche < ${FRA_VERSUCHE}) or (status = 'fehler' and versuche < ${FRA_VERSUCHE}))
        order by tabelle, teil limit 1 for update skip locked)
      returning f.tabelle, f.teil, f.block_von, f.block_bis, f.kopiert_von`;
    if (!t) break;
    try {
      const name = fraName(t.tabelle); if (!name) throw new Error("ungültiger Tabellenname");
      const bed = t.block_von == null ? "" : t.block_bis == null ? `where ctid >= ${fraTid(Number(t.block_von))}` : `where ctid >= ${fraTid(Number(t.block_von))} and ctid < ${fraTid(Number(t.block_bis))}`;
      const spalten = await fraSpalten(sql, name);
      const schluessel = `datenbank/${lauf}/${name}${t.block_von == null ? "" : `.teil${String(t.teil).padStart(3, "0")}`}.json.gz.enc`;
      // KICC-F-107: erst nur die Prüfsumme in der Datenbank rechnen (64 Zeichen statt der ganzen Daten). Gleich wie ein geprüfter Teil
      // eines früheren Tages → Datei im Dateispeicher kopieren (nichts verlässt Supabase). Rücklese-Test prüft die Kopie wie jede Datei.
      // Kopieren nicht möglich oder Kopie war schon einmal kaputt → wie bisher abholen und hochladen.
      if (t.kopiert_von !== "kopie_fehler") {
        const [h] = await sql.unsafe(`select count(*)::bigint as n, encode(sha256(convert_to(coalesce(json_agg(x), '[]'::json)::text, 'UTF8')), 'hex') as h from (select ${spalten} from public."${name}" ${bed}) x`);
        const [v] = await sql`select lauf, schluessel, bytes, roh_bytes, sha256 from public.kc_club_fra_sicherung where tabelle = ${t.tabelle} and lauf < ${lauf} and lauf >= ${berlinTag(new Date(Date.now() - (FRA_BEHALTEN_TAGE - 1) * 86400000))}
          and status = 'geprueft' and inhalt_sha256 = ${h.h} and zeilen = ${Number(h.n)} and schluessel is not null order by lauf desc limit 1`;
        if (v) {
          const quelle = `/${encodeURIComponent(fach)}/${String(v.schluessel).split("/").map(encodeURIComponent).join("/")}`;
          const k = await s3.fetch(url(schluessel), { method: "PUT", headers: { "x-amz-copy-source": quelle } }).catch(() => null);
          const antwort = k ? await k.text().catch(() => "") : "";
          if (k?.ok && !antwort.includes("<Error>")) {
            await sql`update public.kc_club_fra_sicherung set status = 'ok', zeilen = ${Number(h.n)}, bytes = ${v.bytes}, roh_bytes = ${v.roh_bytes}, sha256 = ${v.sha256}, schluessel = ${schluessel},
              inhalt_sha256 = ${h.h}, kopiert_von = ${v.lauf}, fehler = null, zeit = now() where lauf = ${lauf} and tabelle = ${t.tabelle} and teil = ${t.teil}`;
            roh += 64 * 1024;
            continue;
          }
          console.error("fra kopie", k?.status, txt(antwort, 200));
        }
      }
      const [r] = await sql.unsafe(`select count(*)::bigint as n, coalesce(json_agg(x), '[]'::json)::text as j from (select ${spalten} from public."${name}" ${bed}) x`);
      const rohB = new TextEncoder().encode(r.j), enc = await kceVerschluesseln(await fraGzip(rohB)), sha = await hexSha256(enc), inhalt = await hexSha256(rohB);
      const p = await s3.fetch(url(schluessel), { method: "PUT", body: enc, headers: { "content-type": "application/octet-stream", "x-amz-meta-sha256": sha, "x-amz-meta-zeilen": String(r.n), "x-amz-meta-verschluesselung": "kce1-aes-256-gcm" } });
      await p.body?.cancel();
      if (!p.ok) throw new Error(`Neon antwortet ${p.status}`);
      await sql`update public.kc_club_fra_sicherung set status = 'ok', zeilen = ${Number(r.n)}, bytes = ${enc.length}, roh_bytes = ${rohB.length}, sha256 = ${sha}, schluessel = ${schluessel}, inhalt_sha256 = ${inhalt}, kopiert_von = null, fehler = null, zeit = now()
        where lauf = ${lauf} and tabelle = ${t.tabelle} and teil = ${t.teil}`;
      roh += rohB.length;
    } catch (e) {
      await sql`update public.kc_club_fra_sicherung set status = 'fehler', fehler = ${txt(String((e as any)?.message || e), 200)}, zeit = now() where lauf = ${lauf} and tabelle = ${t.tabelle} and teil = ${t.teil}`;
    }
  }
  // 3) Rücklese-Test, sobald nichts mehr offen ist: Datei holen, Prüfsumme, entpacken, Zeilen zählen
  const [{ offen }] = await sql`select count(*)::int as offen from public.kc_club_fra_sicherung where lauf = ${lauf} and (status in ('offen', 'laeuft') or (status = 'fehler' and versuche < ${FRA_VERSUCHE}))`;
  if (!offen) {
    while (Date.now() - t0 < FRA_SCHRITT_MS && roh < FRA_SCHRITT_BYTES) {
      const [t] = await sql`select tabelle, teil, schluessel, sha256, zeilen, roh_bytes, kopiert_von from public.kc_club_fra_sicherung where lauf = ${lauf} and status = 'ok' order by tabelle, teil limit 1`;
      if (!t) break;
      let ok = false, grund = "";
      try {
        const r = await s3.fetch(url(t.schluessel));
        if (!r.ok) throw new Error(`Neon antwortet ${r.status}`);
        const enc = new Uint8Array(await r.arrayBuffer());
        if ((await hexSha256(enc)) !== t.sha256) throw new Error("Prüfsumme weicht ab");
        const daten = JSON.parse(new TextDecoder().decode(await fraGunzip(await kceEntschluesseln(enc)))); // entschlüsseln prüft zugleich die Echtheit
        if (!Array.isArray(daten) || daten.length !== Number(t.zeilen)) throw new Error("Zeilenzahl weicht ab");
        ok = true; roh += Number(t.roh_bytes) || 0;
      } catch (e) { grund = txt(String((e as any)?.message || e), 200); roh += 1024 * 1024; }
      // KICC-F-107: kaputte Kopie → Teil noch einmal ganz normal abholen und hochladen (nie eine fehlerhafte Kopie behalten)
      if (!ok && t.kopiert_von && t.kopiert_von !== "kopie_fehler") {
        await sql`update public.kc_club_fra_sicherung set status = 'offen', versuche = 0, kopiert_von = 'kopie_fehler', fehler = ${"Kopie verworfen: " + grund}, zeit = now()
          where lauf = ${lauf} and tabelle = ${t.tabelle} and teil = ${t.teil}`;
        continue;
      }
      await sql`update public.kc_club_fra_sicherung set status = ${ok ? "geprueft" : "fehler"}, versuche = ${ok ? 0 : FRA_VERSUCHE}, fehler = ${ok ? null : "Rücklese-Test: " + grund}, zeit = now()
        where lauf = ${lauf} and tabelle = ${t.tabelle} and teil = ${t.teil}`;
    }
  }
  // 4) Stand + Abschluss (Inhaltsverzeichnis, alte Tage löschen)
  const [m] = await sql`select count(*)::int as teile, count(distinct tabelle)::int as tabellen, count(*) filter (where status = 'geprueft')::int as geprueft,
      count(*) filter (where status = 'fehler' and versuche >= ${FRA_VERSUCHE})::int as fehler, count(*) filter (where status in ('offen', 'laeuft', 'ok') or (status = 'fehler' and versuche < ${FRA_VERSUCHE}))::int as rest,
      coalesce(sum(zeilen), 0)::bigint as zeilen, coalesce(sum(bytes), 0)::bigint as bytes, coalesce(sum(roh_bytes), 0)::bigint as roh_bytes, min(zeit) as start, max(zeit) as ende,
      count(*) filter (where kopiert_von is not null and kopiert_von <> 'kopie_fehler')::int as kopiert, coalesce(sum(roh_bytes) filter (where kopiert_von is null or kopiert_von = 'kopie_fehler'), 0)::bigint as uebertragen
    from public.kc_club_fra_sicherung where lauf = ${lauf}`;
  const metrics: Record<string, unknown> = { lauf, tabellen: m.tabellen, teile: m.teile, geprueft: m.geprueft, fehler: m.fehler, rest: m.rest, zeilen: Number(m.zeilen), bytes: Number(m.bytes), roh_bytes: Number(m.roh_bytes), grenze: FRA_GRENZE, verschluesselt: true,
    kopiert: m.kopiert, uebertragen_roh_bytes: Number(m.uebertragen) }; // KICC-F-107: unveränderte Teile kopiert / tatsächlich übertragene Rohdaten
  if (m.rest) {
    const spaet = new Date().getUTCHours() === 3 && new Date().getUTCMinutes() >= 50; // letzte Schritte des Zeitplaner-Fensters (bis 03:58 UTC)
    const [{ gesichert }] = await sql`select count(*) filter (where status in ('ok', 'geprueft'))::int as gesichert from public.kc_club_fra_sicherung where lauf = ${lauf}`;
    await fraStand(lauf, spaet ? "fehler" : "laeuft", spaet ? `Nicht fertig geworden: ${gesichert} von ${m.teile} Teilen gesichert, ${m.geprueft} zurückgelesen` : `läuft: ${gesichert} von ${m.teile} Teilen gesichert, ${m.geprueft} zurückgelesen`, metrics);
    if (spaet) await fraAlarm(lauf, `Die Frankfurt-Sicherung ist heute nicht fertig geworden (${gesichert} von ${m.teile} Teilen gesichert, ${m.geprueft} zurückgelesen).`);
    return { ok: true, rest: m.rest };
  }
  const [st] = await sql`select lauf, status from public.kc_club_fra_sicherung_stand where id = 1`;
  if (st?.lauf === lauf && (st.status === "ok" || st.status === "warnung" || st.status === "fehler") && !jetztErzwingen) return { ok: true, fertig: true };
  // Inhaltsverzeichnis mit Spalten je Tabelle (für die Wiederherstellung)
  const teile = await sql`select tabelle, teil, schluessel, zeilen, bytes, sha256, status, fehler from public.kc_club_fra_sicherung where lauf = ${lauf} order by tabelle, teil`;
  const spalten = await sql`select table_name as t, json_agg(json_build_object('name', column_name, 'typ', data_type, 'null', is_nullable) order by ordinal_position) as s from information_schema.columns where table_schema = 'public' group by table_name`;
  const [schutz] = await sql`select (select coalesce(json_agg(table_name order by table_name), '[]'::json) from public.kc_db_mirror_table_rules where sensitivity = 'secret') as ausgeschlossen,
      (select coalesce(json_agg(json_build_object('tabelle', table_name, 'spalte', column_name, 'art', case when muster is null then 'leer' else 'ersetzt' end) order by table_name, column_name), '[]'::json) from public.kc_db_mirror_redaction) as geschwaerzt`;
  const manifest = { art: "kc-club-fra-sicherung", lauf, erstellt: jetzt(), quelle: PROJEKT_REF, teile, spalten: Object.fromEntries(spalten.map((x: any) => [x.t, x.s])),
    verschluesselung: { format: "KCE1 + IV(12) + AES-256-GCM", schluessel: "Vault kc_db_backup_key_v1 (Notfall-Kopie: KC_BACKUP_KEY)", ableitung: "SHA-256 des Geheimnisses", werkzeug: "tools/notfall/fra-entschluesseln.mjs" },
    ausgeschlossen: schutz.ausgeschlossen, geschwaerzt: schutz.geschwaerzt };
  const mb = new TextEncoder().encode(JSON.stringify(manifest));
  const mp = await s3.fetch(url(`datenbank/${lauf}/manifest.json`), { method: "PUT", body: mb, headers: { "content-type": "application/json" } }); await mp.body?.cancel();
  // alte Tage löschen (Dateien + Verzeichnis)
  const grenze = berlinTag(new Date(Date.now() - FRA_BEHALTEN_TAGE * 86400000));
  let geloescht = 0, weiter = "";
  for (let runde = 0; runde < 20; runde++) {
    const l = await s3.fetch(`${basis}?list-type=2&prefix=datenbank/${weiter ? `&continuation-token=${encodeURIComponent(weiter)}` : ""}`);
    const x = await l.text(); if (!l.ok) break;
    for (const k of [...x.matchAll(/<Key>([^<]+)<\/Key>/g)].map((a) => a[1])) {
      const tag = k.split("/")[1] || "";
      // alte Tage weg; 2.369.0: Klartext-Dateien von früher (nicht „.enc“, außer Inhaltsverzeichnis) erst, wenn der heutige Lauf ohne Fehler verschlüsselt geprüft ist
      const klartext = !m.fehler && !k.endsWith(".enc") && !k.endsWith("/manifest.json");
      if (/^\d{4}-\d{2}-\d{2}$/.test(tag) && (tag < grenze || klartext)) { const d = await s3.fetch(url(k), { method: "DELETE" }); await d.body?.cancel(); geloescht++; }
    }
    weiter = x.match(/<NextContinuationToken>([^<]+)<\/NextContinuationToken>/)?.[1] || ""; if (!weiter) break;
  }
  await sql`delete from public.kc_club_fra_sicherung where lauf < ${grenze}`;
  const status = m.fehler ? (m.geprueft ? "warnung" : "fehler") : mp.ok ? "ok" : "warnung";
  const text = m.fehler ? `${m.fehler} von ${m.teile} Teilen fehlerhaft` : mp.ok ? `${m.tabellen} Tabellen gesichert und zurückgelesen` : "Inhaltsverzeichnis nicht gespeichert";
  await fraStand(lauf, status, text, { ...metrics, geloescht, dauer_min: Math.round((Date.parse(m.ende) - Date.parse(m.start)) / 60000) });
  if (status !== "ok") await fraAlarm(lauf, `Die Frankfurt-Sicherung meldet: ${text}.`);
  await protokoll(null, "fra_sicherung", { lauf, status, ...metrics });
  return { ok: status !== "fehler", fertig: true };
}
async function fraAlarm(lauf: string, satz: string) {
  const ziel = await adminIds(); if (!ziel.length) return;
  await sendenGewaehlt("club_nachricht", ziel, ["push"], { titel: "🗄️ Frankfurt-Sicherung: bitte prüfen", kurz: satz, betreff: "Köcheclub-App: Frankfurt-Sicherung",
    text: `Hallo,\n\n${satz}\n\nDie Daten bei Supabase sind davon nicht betroffen. Admin-Zentrale → Backups zeigt Einzelheiten.`, url: APP_URL }, `club-fra-sicherung:${lauf}`).catch((e) => console.error("fra alarm", String(e)));
}

async function archivKopieLauf(erzwingen = false) {
  if (!erzwingen) { const h = berlinStunde(new Date()); if (h < 2 || h >= 5) return null; }
  const nz = await neonDateispeicher();
  if (!nz) { await archivKopieStand("fehler", "Zugang zum Neon-Dateispeicher fehlt", {}); return { ok: false }; }
  const { s3, url } = nz;
  const [{ data: doks, error: de }, { data: kopien, error: ke }] = await Promise.all([
    db.from("kc_club_archiv_dokumente").select("id,attachment_id,geloescht_am").not("attachment_id", "is", null),
    db.from("kc_club_archiv_kopie").select("dokument_id,attachment_id,schluessel,groesse"),
  ]);
  if (de || ke) { await archivKopieStand("fehler", "Archiv-Verzeichnis nicht lesbar", {}); return { ok: false }; }
  const kopie = new Map((kopien ?? []).map((k: any) => [k.dokument_id, k]));
  const dokMap = new Map((doks ?? []).map((d: any) => [d.id, d]));
  const grenzeWeg = Date.now() - ARCHIV_KOPIE_NACHLAUF_TAGE * 86400000;
  // 2.369.0: Klartext-Kopien von früher (ohne „.enc“) werden einmal verschlüsselt neu abgelegt; die alte Datei entfernt der Ersatz-Schritt unten
  const offen = (doks ?? []).filter((d: any) => !d.geloescht_am && (kopie.get(d.id)?.attachment_id !== d.attachment_id || !String(kopie.get(d.id)?.schluessel || "").endsWith(".enc")));
  const weg = (kopien ?? []).filter((k: any) => { const d: any = dokMap.get(k.dokument_id); return !d || (d.geloescht_am && new Date(d.geloescht_am).getTime() < grenzeWeg); });
  let kopiert = 0, entfernt = 0, bytes = 0; const fehler: string[] = [];
  // 1) neue/geänderte Dokumente kopieren (Prüfsumme wird mit der Anlage verglichen)
  const atts = offen.length ? (await db.from("kc_communication_attachments").select("id,bucket,object_path,mime_type,size_bytes,sha256").in("id", offen.slice(0, ARCHIV_KOPIE_JE_LAUF).map((d: any) => d.attachment_id))).data ?? [] : [];
  const attMap = new Map(atts.map((a: any) => [a.id, a]));
  for (const d of offen.slice(0, ARCHIV_KOPIE_JE_LAUF)) {
    const a: any = attMap.get(d.attachment_id);
    if (!a) { fehler.push("Anlage fehlt"); continue; }
    if (bytes + (Number(a.size_bytes) || 0) > ARCHIV_KOPIE_MAX_BYTES && kopiert > 0) break; // Rest beim nächsten Lauf
    try {
      const { data: blob, error } = await db.storage.from(a.bucket).download(a.object_path);
      if (error || !blob) throw new Error("Datei nicht lesbar");
      const inhalt = new Uint8Array(await blob.arrayBuffer());
      const hash = [...new Uint8Array(await crypto.subtle.digest("SHA-256", inhalt))].map((x) => x.toString(16).padStart(2, "0")).join("");
      if (a.sha256 && a.sha256 !== hash) throw new Error("Prüfsumme weicht ab");
      const schluessel = archivKopieSchluessel(d.id, d.attachment_id);
      const r = await s3.fetch(url(schluessel), { method: "PUT", body: await kceVerschluesseln(inhalt), headers: { "content-type": "application/octet-stream", "x-amz-meta-verschluesselung": "kce1-aes-256-gcm" } });
      if (!r.ok) throw new Error(`Neon antwortet ${r.status}`);
      await r.body?.cancel();
      const alt: any = kopie.get(d.id);
      if (alt && alt.schluessel !== schluessel) { const x = await s3.fetch(url(alt.schluessel), { method: "DELETE" }); await x.body?.cancel(); } // ersetzte Datei
      const { error: ue } = await db.from("kc_club_archiv_kopie").upsert({ dokument_id: d.id, attachment_id: d.attachment_id, schluessel, groesse: inhalt.length, sha256: hash, kopiert_am: jetzt() });
      if (ue) throw new Error("Verzeichnis nicht gespeichert");
      kopiert++; bytes += inhalt.length;
    } catch (e) { fehler.push(txt(String((e as any)?.message || e), 80)); }
  }
  // 2) endgültig gelöschte Dokumente nach der Nachlaufzeit aus der Kopie entfernen
  for (const k of weg.slice(0, ARCHIV_KOPIE_JE_LAUF)) {
    try {
      const r = await s3.fetch(url(k.schluessel), { method: "DELETE" });
      await r.body?.cancel();
      if (!r.ok && r.status !== 404) throw new Error(`Neon antwortet ${r.status}`);
      await db.from("kc_club_archiv_kopie").delete().eq("dokument_id", k.dokument_id);
      entfernt++;
    } catch (e) { fehler.push(txt(String((e as any)?.message || e), 80)); }
  }
  // 3) Stufe 2 (2.233.0): PDF-Handbücher und Schulungsunterlagen aus GitHub
  const dk = await dokumenteKopieLauf(s3, url, fehler);
  const [{ data: alle }, { data: alleDok }] = await Promise.all([db.from("kc_club_archiv_kopie").select("groesse"), db.from("kc_club_dokument_kopie").select("groesse")]);
  const summe = (l: any[] | null) => (l ?? []).reduce((s: number, x: any) => s + (Number(x.groesse) || 0), 0);
  const metrics = { kopiert: kopiert + dk.kopiert, entfernt, offen: Math.max(0, offen.length - kopiert) + dk.offen,
    dateien: (alle ?? []).length + (alleDok ?? []).length, bytes: summe(alle) + summe(alleDok), fehler: fehler.length,
    archiv: { dateien: (alle ?? []).length, bytes: summe(alle) }, dokumente: { dateien: (alleDok ?? []).length, bytes: summe(alleDok) } };
  const status = fehler.length && !kopiert && !entfernt ? "fehler" : fehler.length ? "warnung" : "ok";
  await archivKopieStand(status, fehler.length ? `${fehler.length} Fehler: ${[...new Set(fehler)].join(", ")}` : "in Ordnung", metrics);
  return { ok: status !== "fehler", ...metrics };
}

// ---------- Archiv (KC-CLUB-ARCHIV, 1.2.0) ----------
// Aktenordner mit Registern und Jahreszahl. Ordner „nur Vorstand“ sehen Clubsprecher, Kassenwart und Admin (Recht „vorstand“).
// Anlegen/Hochladen/Ändern/Löschen: Clubsprecher und Admin (Wunsch Hansi 30.09.2026). Dateien liegen im Anlagen-Kern.
// Der automatische Teil wird nur gelesen (vergangene Treffen, Protokolle, Abstimmungen, Aktionen, Pinnwand, Anhänge, Dienste).
const ARCHIV_ARTEN: Record<string, { t: string; sym: string; register: string[]; vorstand?: boolean }> = {
  satzung: { t: "Satzung & Recht", sym: "📜", register: ["Satzung", "Geschäftsordnung", "Vereinsregister", "Sonstiges"] },
  versammlung: { t: "Versammlungen", sym: "🏛️", register: ["Einladung", "Protokoll", "Anwesenheit", "Anlagen"] },
  vertraege: { t: "Verträge & Versicherungen", sym: "🤝", register: ["Verträge", "Versicherungen", "Genehmigungen", "Sonstiges"], vorstand: true },
  finanzen: { t: "Finanzen", sym: "💶", register: ["Kassenbericht", "Kassenprüfung", "Belege", "Sonstiges"], vorstand: true },
  presse: { t: "Presse", sym: "📰", register: ["Zeitung", "Internet", "Sonstiges"] },
  // KC-CLUB-CHRONIK (1.64.0, Vorschlag + Freigabe Hansi): Register nach Themen; Einträge tragen das Ereignisdatum
  chronik: { t: "Chronik", sym: "📖", register: ["Gründung", "Presse", "Rekorde & Höhepunkte", "Feste & Jubiläen", "Mitglieder im Wandel", "In Gedenken", "Ehrungen & Urkunden", "Sonstiges"] },
  sonstiges: { t: "Sonstiges", sym: "🗂️", register: ["Allgemein"] },
};
const ARCHIV_DATEITYPEN = /^(application\/pdf|image\/(jpeg|png|webp)|text\/plain|application\/msword|application\/vnd\.ms-excel|application\/vnd\.openxmlformats-officedocument\.(wordprocessingml\.document|spreadsheetml\.sheet))$/;
const ARCHIV_STOPP = 0.98; // Speicher: Archiv nimmt bis 98 % an (Fotos stoppen schon bei 95 %)
const darfArchivPflegen = (ich: Ich) => ich.admin || ich.aemter.includes("Clubsprecher");
const nurArchivPflege = (ich: Ich) => { if (!darfArchivPflegen(ich)) throw new Fehler("Das Archiv pflegen Clubsprecher und Admin.", 403); };
const darfOrdnerSehen = (ich: Ich, o: any) => !o.nur_vorstand || ich.vorstand;
// KC-CLUB-CHRONIK (1.64.0): Vereinsordner mit „einreichen“ – alle Mitglieder dürfen etwas hineinlegen, sichtbar erst nach Prüfung
// durch die Archiv-Pflege (Clubsprecher/Admin). Wer prüfen darf, bekommt Bescheid.
async function archivPflegerIds(): Promise<string[]> {
  const { data } = await db.from("kc_club_rollen").select("person_id,ist_admin,aemter");
  return (data ?? []).filter((r: any) => r.ist_admin || (r.aemter ?? []).includes("Clubsprecher")).map((r: any) => r.person_id);
}
function archivRegister(roh: unknown, art: string): string[] {
  const liste = (Array.isArray(roh) ? roh : []).map((x) => txt(x, 30)).filter(Boolean);
  const eindeutig = [...new Set(liste)].slice(0, liste.some((r) => r.includes(" › ")) ? 80 : 12); // 2.147.0 KC-CLUB-ARCHIV-UNTERREGISTER: „Jahr › Unterregister“ – mehrjährige Ordner brauchen mehr
  return eindeutig.length ? eindeutig : [...(ARCHIV_ARTEN[art]?.register ?? ["Allgemein"])];
}
const archivDatum = (v: unknown) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || "")) && !isNaN(Date.parse(String(v))) ? String(v) : null;
const archivStichworte = (v: unknown) => [...new Set((Array.isArray(v) ? v : String(v || "").split(/[,;]/)).map((x) => txt(x, 30)).filter(Boolean))].slice(0, 10);
// ----- KC-CLUB-ARCHIV-PERSOENLICH (1.5.0): eigene Ordner je Mitglied und Jahr, Zugriff nur Besitzer + gültige Freigaben -----
// Auch Admin und Clubsprecher kommen NICHT hinein (Entscheidung Hansi). Fremdversuch → Protokoll + Meldung an Besitzer und Admins.
const PERSOENLICH_REGISTER = ["Urkunden", "Schulungen", "Rechnungen", "Fotos", "Sonstiges"];
const PERSOENLICH_GRENZE = 50 * 1024 * 1024; // je Mitglied (kostenloser Speicher ist begrenzt)
const FREIGABE_MAX_TAGE = 365;
type ArchivRecht = "lesen" | "pflegen" | "hochladen";
async function meineGruppenIds(pid: string): Promise<string[]> {
  const { data } = await db.from("kc_communication_thread_participants").select("thread_id").eq("person_id", pid);
  return (data ?? []).map((x: any) => x.thread_id);
}
// gültige Freigaben für mich (optional nur bestimmte Ordner); abgelaufen/beendet zählt nicht
async function archivFreigabenFuer(pid: string, ordnerIds?: string[], auchAbgelaufen = false) {
  const gr = await meineGruppenIds(pid);
  let q = db.from("kc_club_archiv_freigaben").select("*").or(gr.length ? `an_person.eq.${pid},an_gruppe.in.(${gr.join(",")})` : `an_person.eq.${pid}`);
  if (ordnerIds) { if (!ordnerIds.length) return []; q = q.in("ordner_id", ordnerIds); }
  if (!auchAbgelaufen) q = q.is("beendet_am", null).gt("bis", jetzt());
  const { data } = await q;
  return (data ?? []) as any[];
}
const freigabeDeckt = (f: any, d: any) => (!f.dokument_id || f.dokument_id === d.id) && (!f.register || f.register === d.register);
function darfDokSehen(ich: Ich, o: any, d: any, freigaben: any[]) {
  if (!o.besitzer) return darfOrdnerSehen(ich, o) && (d.status !== "pruefung" || d.hochgeladen_von === ich.person_id || darfArchivPflegen(ich)); // 1.64.0: Einreichung erst nach Prüfung für alle
  if (o.besitzer === ich.person_id) return true;
  if (d.status === "pruefung") return d.hochgeladen_von === ich.person_id;
  return freigaben.some((f) => f.ordner_id === o.id && freigabeDeckt(f, d));
}
// KC-CLUB-SICHERHEIT-ARCHIV (1.22.1): Vereinsordner „Admin <Jahr>“ (art sonstiges, nur Clubleitung) – entsteht beim ersten Bericht
const ADMIN_ORDNER = { art: "sonstiges", titel: "Admin", farbe: 8, register: ["Sicherheitscheck", "Sonstiges"] };
// KC-CLUB-AENDERUNG (2.22.10, Wunsch Hansi): eigener Vereinsordner „Mitglieder <Jahr>“ (nur Clubleitung) für Änderungsmeldungen
const MITGLIEDER_ORDNER = { art: "sonstiges", titel: "Personal", farbe: 3, register: ["Meldungen", "Sonstiges"] }; // 2.22.19 (Wunsch Hansi): „Personal“ statt „Mitglieder“
const adminOrdner = (jahr: number, register: string) => vereinsOrdner(ADMIN_ORDNER, jahr, register);
// KC-CLUB-DIENST-ABLAGE (2.23.39, Wunsch Hansi): Büro-Ordner „Dienstpläne <Jahr>“ (nur Clubleitung) – Wünsche je Mitglied + Gesamtplan
const DIENSTPLAN_ORDNER = { art: "sonstiges", titel: "Dienstpläne", farbe: 5, register: ["Wünsche", "Gesamtplan", "Sonstiges"] };
const DIENST_REG = { wunsch: "Wünsche", gesamt: "Gesamtplan", persoenlich: "Dienstpläne" };
const dwJahr = () => Number(DW.veranstaltung.match(/\d{4}/)?.[0]) || Number(berlinTag(new Date()).slice(0, 4));
async function vereinsOrdner(def: typeof ADMIN_ORDNER, jahr: number, register: string) {
  const { data: da } = await db.from("kc_club_archiv_ordner").select("id,register").is("besitzer", null).eq("art", def.art).eq("titel", def.titel)
    .eq("jahr", jahr).is("geloescht_am", null).order("erstellt_am").limit(1).maybeSingle();
  if (da) {
    if (!(da.register || []).includes(register)) await db.from("kc_club_archiv_ordner").update({ register: [register, ...(da.register || [])], geaendert_am: jetzt() }).eq("id", da.id);
    return da.id as string;
  }
  const [admin] = await adminIds();
  const { data: neu, error } = await db.from("kc_club_archiv_ordner").insert({ art: def.art, jahr, titel: def.titel, farbe: def.farbe,
    register: [...new Set([register, ...def.register])], nur_vorstand: true, erstellt_von: admin }).select("id").single();
  if (error || !neu) throw new Error(`${def.titel}-Ordner konnte nicht angelegt werden`);
  await protokoll(null, "archiv_ordner_angelegt", { ordner: neu.id, art: def.art, jahr, titel: def.titel, nur_vorstand: true, automatisch: true });
  return neu.id as string;
}
async function sicherheitAblegen(ich: Ich, zeilen: string[], probleme: number, ms: number | null, notiz: string, version: string) {
  const heute = berlinTag(new Date()), zeit = new Intl.DateTimeFormat("de-DE", { timeZone: TZ, hour: "2-digit", minute: "2-digit" }).format(new Date());
  const ordner = await adminOrdner(Number(heute.slice(0, 4)), "Sicherheitscheck");
  const text = `Köcheclub-App – Sicherheits-Check\n${ich.name} · ${heute.split("-").reverse().join(".")} ${zeit} Uhr\nErgebnis: ${probleme ? `${probleme} Punkt(e) nicht bestätigt` : "alles in Ordnung"}\n────────────────────\n\n${zeilen.join("\n")}\n\nAntwortzeit beim Mitglied: ${ms ?? "?"} ms · App ${version || "?"}${notiz ? `\nNotiz: ${notiz}` : ""}\n\n(Der Server hat beim Absenden selbst neu geprüft.)\n`;
  const bytes = new TextEncoder().encode("\ufeff" + text);
  let b = ""; for (const x of bytes) b += String.fromCharCode(x);
  const name = `Sicherheitscheck-${heute}-${ich.vorname || "Mitglied"}.txt`.replace(/[^\w.\-äöüÄÖÜß]/g, "_");
  const datei = await dateiAblegen(ich, name, "text/plain", btoa(b), ARCHIV_DATEITYPEN);
  try {
    const { error } = await db.from("kc_club_archiv_dokumente").insert({ ordner_id: ordner, register: "Sicherheitscheck",
      titel: `Sicherheits-Check ${ich.name} – ${probleme ? `${probleme} offen` : "alles OK"}`.slice(0, 120), datum: heute, stichworte: archivStichworte(`Sicherheitscheck, ${ich.vorname || ich.name}`),
      attachment_id: datei.id, datei_name: datei.name, mime: "text/plain", groesse: datei.groesse, hochgeladen_von: ich.person_id, status: "ok" });
    if (error) throw new Error(error.message);
  } catch (e) { await dateienEntfernen([datei.id]); throw e; }
}
// ---------- KC-CLUB-WOCHENBERICHT (2.23.81, Wunsch Hansi): jeden Montag ab 8 Uhr ein Bericht an die Admins (Push + E-Mail) ----------
// Nur Zahlen und Zustände – keine Inhalte. Unbekannt bleibt „unbekannt“ (Regel 11). Einmal pro Woche (Protokoll „wochenbericht_gesendet“).
async function wochenberichtBauen() {
  const seit7 = new Date(Date.now() - 7 * 86400000).toISOString();
  const [leute, { data: zug }, { data: fp }, { data: s0, error: sErr }, { data: req }, { count: erst }, { count: aend }, { count: tw }, { data: vs }, { count: dw }, schulung, sperren] = await Promise.all([
    aktiveMitglieder(),
    db.from("kc_club_zugang").select("person_id,aktiv,zuletzt_gesehen,erstmals_gesehen,app_version").not("person_id", "like", "KC-P-TEST%"),
    db.from("kc_club_protokoll").select("aktion,details").or(FP_FILTER).gte("zeit", seit7).limit(2000),
    db.rpc("kc_club_sicherheit_status"),
    db.from("kc_communication_requests").select("status").eq("source_program", "kc-club").gte("created_at", seit7).limit(5000),
    db.from("kc_club_erstattung").select("id", { count: "exact", head: true }).eq("status", "eingereicht"),
    db.from("kc_club_aenderungen").select("id", { count: "exact", head: true }).neq("status", "erledigt"),
    db.from("kc_club_twinkey_fragen").select("id", { count: "exact", head: true }).eq("status", "offen"),
    db.from("kc_club_vorschlaege").select("art").eq("status", "offen"),
    db.from("kc_dp_wish_inbox").select("id", { count: "exact", head: true }).eq("org_id", ORG).eq("source", "club_app").eq("status", "offen"),
    schulungProtokollFehlt().catch(() => null),
    sperrenAktuell().then((x) => x.liste.size).catch(() => null),
  ]);
  const aktivIds = new Set(leute.map((x: any) => x.person_id)), mz = (zug ?? []).filter((x: any) => x.aktiv && aktivIds.has(x.person_id));
  const inWoche = (t: any) => t && Date.parse(t) > Date.now() - 7 * 86400000;
  const stufen = { schwer: 0, hinweis: 0 } as Record<string, number>;
  for (const x of fp ?? []) { const st = fpStufe((x as any).aktion, (x as any).details); if (st !== "info") stufen[st]++; }
  const st: any = s0 ?? {}, frisch = (min: unknown, grenze: number) => (typeof min === "number" ? min <= grenze : null);
  const z = (v: boolean | null) => (v === true ? "✅" : v === false ? "⚠️" : "❔ unbekannt");
  const sicher: [string, boolean | null][] = sErr ? [["Sicherheitsstatus", null]] : [
    ["Zugriffsschutz auf allen Daten", typeof st.ohne_schutz === "number" ? st.ohne_schutz === 0 : null],
    ["Sicherungskopie (Spiegel) aktuell", frisch(st.spiegel_min, 8 * 60)],
    ["Nächtliche Sicherung", frisch(st.sicherung_min, 30 * 60)],
    ["Wiederherstellung getestet", st.wiederherstellung_min == null ? null : frisch(st.wiederherstellung_min, 8 * 24 * 60) && !st.wiederherstellung_fehler_danach],
    ["Überwachung aktiv", frisch(st.ueberwachung_min, 120)],
  ];
  const r = (req ?? []) as any[], gesendet = r.filter((x) => ["sent", "delivered", "displayed", "opened"].includes(x.status)).length, fehlg = r.filter((x) => COMM_FEHLER.includes(x.status)).length;
  const abst = (vs ?? []).filter((x: any) => x.art === "abstimmung").length, vors = (vs ?? []).length - abst;
  const zahl = (n: number | null | undefined) => (typeof n === "number" ? String(n) : "unbekannt");
  const abschnitte: [string, [string, string][]][] = [
    ["👥 Nutzung (7 Tage)", [["Mitglieder aktiv", `${mz.filter((x: any) => inWoche(x.zuletzt_gesehen)).length} von ${mz.length} mit Zugang`],
      ["Zum ersten Mal dabei", String(mz.filter((x: any) => inWoche(x.erstmals_gesehen)).length)],
      ["Noch nie angemeldet", String(mz.filter((x: any) => !x.zuletzt_gesehen).length)],
      ["Mit alter App-Version", String(mz.filter((x: any) => x.zuletzt_gesehen && x.app_version && x.app_version !== SERVER_VERSION).length)]]],
    ["🩺 Fehler (7 Tage)", [["Schwerwiegend", String(stufen.schwer)], ["Hinweise", String(stufen.hinweis)]]],
    ["🛡️ Sicherheit", sicher.map(([t, v]) => [t, z(v)])],
    ["📨 Benachrichtigungen (7 Tage)", [["Zugestellt", r.length ? String(gesendet) : "keine"], ["Fehlgeschlagen", String(fehlg)]]],
    ["📋 Offen bei dir", [["Erstattungsanträge", zahl(erst)], ["Änderungsmeldungen", zahl(aend)], ["Fragen an Twinkey", zahl(tw)],
      ["Abstimmungen / Vorschläge", `${abst} / ${vors}`], ["Dienstwünsche (noch nicht übernommen)", zahl(dw)],
      ["Besuchstermine ohne Protokoll", schulung ? String(schulung.length) : "unbekannt"], ["Gesperrte Personen", zahl(sperren)]]],
  ];
  const probleme = stufen.schwer + sicher.filter(([, v]) => v === false).length + (fehlg > 0 ? 1 : 0);
  return { abschnitte, probleme, version: SERVER_VERSION };
}
async function wochenberichtSenden(erzwungen: string | null) {
  const wt = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(new Intl.DateTimeFormat("en-US", { timeZone: TZ, weekday: "short" }).format(new Date()));
  const woche = berlinTag(new Date(Date.now() - Math.max(0, wt) * 86400000)); // Montag dieser Woche
  const b = await wochenberichtBauen(), ziel = await adminIds();
  if (!ziel.length) return { ok: false, grund: "kein Admin" };
  const text = b.abschnitte.map(([t, z]) => `${t}\n${z.map(([a, w]) => `  • ${a}: ${w}`).join("\n")}`).join("\n\n");
  const versand = await sendenGewaehlt("club_nachricht", ziel, ["push", "email"], {
    titel: b.probleme ? `📊 Wochenbericht: ${b.probleme} Punkt${b.probleme === 1 ? "" : "e"} ansehen` : "📊 Wochenbericht: alles in Ordnung",
    kurz: `Köcheclub-App – Woche ab ${woche.split("-").reverse().join(".")}`,
    betreff: `Köcheclub-App: Wochenbericht ab ${woche.split("-").reverse().join(".")}${b.probleme ? ` – ${b.probleme} Punkt${b.probleme === 1 ? "" : "e"} ansehen` : " – alles in Ordnung"}`,
    text: `Hallo,\n\nhier der Wochenbericht der Köcheclub-App (nur Zahlen, keine Inhalte):\n\n${text}\n\nServer-Version ${b.version}\n\nEinzelheiten: Admin-Register in der App\n${APP_URL}\n\nViele Grüße\nKöcheclub-App`,
    url: APP_URL,
  }, `club-wochenbericht:${woche}${erzwungen ? ":" + Date.now() : ""}`);
  await protokoll(erzwungen, "wochenbericht_gesendet", { woche, probleme: b.probleme, erzwungen: !!erzwungen });
  return { ok: true, woche, probleme: b.probleme, versand, bericht: b };
}
async function wochenberichtLauf() {
  const tag = new Intl.DateTimeFormat("en-US", { timeZone: TZ, weekday: "short" }).format(new Date());
  if (tag !== "Mon" || berlinStunde(new Date()) < 8) return;
  // schon heute automatisch geschickt? (ein „jetzt senden“ des Admins zählt nicht – der Montagsbericht kommt trotzdem)
  const { data: heute } = await db.from("kc_club_protokoll").select("details").eq("aktion", "wochenbericht_gesendet").gte("zeit", new Date(Date.now() - 20 * 3600000).toISOString()).limit(20);
  if ((heute ?? []).some((x: any) => x.details?.erzwungen === false)) return;
  await wochenberichtSenden(null);
}
// KC-CLUB-SPUR (2.23.88): erlaubte Schritte (Bereichs-Kürzel) und „mit wem“ (Mitglieds-Kennung oder Unterhaltungs-ID) – nie freier Text
const SPUR_WAS = /^[a-z][a-z0-9_]{0,29}$/;
// KC-CLUB-SPRACHE-LERNEN (2.83.0, Wunsch Hansi): selbstlernende Sprachsteuerung. Ziele = gleiche Registry wie in der App (SB_ZIELE).
// Persönlich gelernt: kc_club_person_einstellung „sprache_gelernt“; für alle: kc_club_konfig „sprache_gelernt“ (Admin) – oder automatisch,
// sobald 2 verschiedene Mitglieder denselben Satz demselben Ziel zuordnen. Unbekannte Sätze (nur kurze, ohne Inhalte) → Protokoll, 30 Tage für den Admin.
const SPRACHE_ZIELE = ["start", "termine", "termin_neu", "naechster", "nachrichten", "nachricht_neu", "pinnwand", "pinnwand_neu", "mitglieder", "fotos", "foto_neu", "archiv", "erstattung", "helfen", "boerse", "protokolle", "vorschlaege", "einstellungen", "hilfe", "dienste", "brief_neu", "schilder", "studio"]; // 2.137.0: brief_neu (KC-CLUB-SPRACHE-BRIEF); 2.152.0: schilder, studio
const sprachSatz = (t: unknown) => { const s = String(t ?? "").toLowerCase().replace(/[.,!?;:„“"]/g, " ").replace(/\s+/g, " ").trim(); return s.length >= 2 && s.length <= 60 && s.split(" ").length <= 8 ? s : ""; };
const SPUR_MIT = /^(KC-P-[A-Z0-9-]{1,30}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;
const SPUR_TAGE = 30;
// KC-CLUB-STARTSTATISTIK (2.31.0, Wunsch Hansi): jeder App-Start mit Dauer, Gerät und Browser (Name nur für den Admin sichtbar), 180 Tage
const START_TAGE = 180;
// ---------- KC-CLUB-PROTOKOLL-WAECHTER (2.114.0, Wunsch Hansi „muss das Protokoll so wachsen? Wächter, der es leert, wenn zu voll“) ----------
// Das Protokoll hält fest, was in der App passiert. Drei Stufen statt „alles leer“:
//  1. Wichtig (Nachweis, Sicherheit, Rechte, Zugänge, Löschungen, Änderungen an Daten, Notfall) – wird NIE automatisch gelöscht.
//  2. Lärm (Ansehen, Diagnose, harmlose Browser-/Update-Meldungen) – nach PROT_LAERM_TAGE weg.
//  3. Alles andere – nach PROT_ALT_TAGE weg (reicht für Jahres-Statistiken).
// Dazu der Füllstand-Wächter: Sind es mehr als PROT_MAX_ZEILEN, werden die ältesten nicht-wichtigen Einträge entfernt, bis
// PROT_ZIEL_ZEILEN erreicht sind – und es steht eine Zeile „protokoll_waechter“ mit den Zahlen im Protokoll (nie Inhalte).
// Läuft im nächtlichen Wartungslauf; spur (30 Tage) und app_start (180 Tage) behalten ihre eigenen Fristen.
const PROT_LAERM_TAGE = 60, PROT_ALT_TAGE = 365, PROT_MAX_ZEILEN = 50000, PROT_ZIEL_ZEILEN = 40000;
const PROT_LAERM = ["mitglied_details", "aenderungen_angesehen", "meine_daten_angesehen", "fehler_alte_version", "fehler_umgebung", "fehler_startzeit", "sos_geoeffnet", "buero_mail_versuch"]; // 2.122.0: Mail-Bremse braucht ihn nur 1 Minute
const PROT_LAERM_PRAEFIX = ["diagnose_%", "fehler_update_%"];
const PROT_WICHTIG = ["%zugang%", "%link%", "%kurzcode%", "%sperr%", "%rolle%", "%recht%", "admin_%", "%geloescht%", "%endgueltig%", "%entfernt%",
  "%zusammengefuehrt%", "%freigab%", "%notbetrieb%", "%sicherheit%", "%schnappschuss%", "%mitschau%", "notfall_%", "hilferuf", "aenderung_%", "erstattung%",
  "protokoll_waechter", "db_aufgeraeumt", "fehler_alarm", "fp_schwer_gemeldet"];
const protNichtWichtig = (q: any) => { for (const m of PROT_WICHTIG) q = q.not("aktion", "like", m); return q; };
async function protokollWaechter() {
  const tag = (n: number) => new Date(Date.now() - n * 86400000).toISOString();
  let laerm = 0, alt = 0, voll = 0;
  { const { count } = await db.from("kc_club_protokoll").delete({ count: "exact" }).in("aktion", PROT_LAERM).lt("zeit", tag(PROT_LAERM_TAGE)); laerm += count ?? 0; }
  for (const m of PROT_LAERM_PRAEFIX) { const { count } = await db.from("kc_club_protokoll").delete({ count: "exact" }).like("aktion", m).lt("zeit", tag(PROT_LAERM_TAGE)); laerm += count ?? 0; }
  { const { count } = await protNichtWichtig(db.from("kc_club_protokoll").delete({ count: "exact" }).lt("zeit", tag(PROT_ALT_TAGE))); alt = count ?? 0; }
  const { count: n } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true });
  if ((n ?? 0) > PROT_MAX_ZEILEN) {
    // Grenze: Zeitpunkt, ab dem die jüngsten PROT_ZIEL_ZEILEN Einträge beginnen – alles Nicht-Wichtige davor geht
    const { data: g } = await db.from("kc_club_protokoll").select("zeit").order("zeit", { ascending: false }).range(PROT_ZIEL_ZEILEN, PROT_ZIEL_ZEILEN);
    if (g?.[0]?.zeit) { const { count } = await protNichtWichtig(db.from("kc_club_protokoll").delete({ count: "exact" }).lt("zeit", g[0].zeit)); voll = count ?? 0; }
  }
  if (laerm || alt || voll) await protokoll(null, "protokoll_waechter", { laerm, alt, voll, vorher: (n ?? 0) + laerm + alt, grenze: PROT_MAX_ZEILEN });
  return { laerm, alt, voll, zeilen: (n ?? 0) - voll };
}
const startZahl = (v: unknown) => { const n = Math.round(Number(v)); return Number.isFinite(n) && n >= 0 && n < 600000 ? n : null; };
const startText = (v: unknown, n = 40) => String(v ?? "").replace(/[^\p{L}\p{N} .,_()\/+-]/gu, "").slice(0, n);
// KC-CLUB-AVATAR-FOTO (2.23.89)
const AVF_CODE = /^f[0-9a-z]{9}$/;
const AVF_MAX = 90000; // Zeichen (≈ 66 KB) – die App schickt 256×256, meist 15–30 KB
// KC-CLUB-DB-AUFRAEUMEN (2.24.7, Wunsch Hansi): ab 400 MB in der Haupt-Datenbank (500 MB kostenlos) Push + E-Mail an den Admin,
// höchstens einmal am Tag. Größe unbekannt → nichts senden (UNKNOWN ≠ OK, aber auch kein Fehlalarm; die Admin-Kachel zeigt grau).
const DB_WARN_BYTES = 400 * 1024 * 1024;
async function dbWarnungLauf() {
  const { data, error } = await db.rpc("kc_club_db_groesse");
  const bytes = Number(data);
  if (error || !Number.isFinite(bytes) || bytes < DB_WARN_BYTES) return;
  const { count } = await db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "db_warnung_gesendet").gte("zeit", new Date(Date.now() - 24 * 3600000).toISOString());
  if ((count ?? 0) > 0) return;
  const ziel = await adminIds();
  if (!ziel.length) return;
  const mbText = (b: number) => `${Math.round(b / 1048576)} MB`;
  await sendenGewaehlt("club_nachricht", ziel, ["push", "email"], {
    titel: `🗄️ Datenbank fast voll: ${mbText(bytes)} von 500 MB`,
    kurz: "Bitte im Admin-Bereich unter 🗄️ Supabase → 🧹 Jetzt aufräumen",
    betreff: `Köcheclub-App: Datenbank ${mbText(bytes)} von 500 MB belegt`,
    text: `Hallo,\n\ndie Haupt-Datenbank (Supabase, kostenlos bis 500 MB) ist mit ${mbText(bytes)} belegt.\nBei 500 MB kann nichts mehr gespeichert werden.\n\nBitte in der App: Admin-Bereich → 🗄️ Supabase → 🧹 Jetzt aufräumen.\n${APP_URL}\n\nViele Grüße\nKöcheclub-App`,
    url: APP_URL,
  }, `club-db-warnung:${berlinTag(new Date())}`);
  await protokoll(null, "db_warnung_gesendet", { bytes });
}
async function adminIds(): Promise<string[]> {
  const { data } = await db.from("kc_club_rollen").select("person_id").eq("ist_admin", true);
  return (data ?? []).map((x: any) => x.person_id);
}
