async function flRollen() {
  const { data } = await db.from("kc_club_rollen").select("person_id,aemter,ist_admin");
  const mit = (wort: string) => (data ?? []).filter((r: any) => (r.aemter ?? []).some((a: string) => a.toLowerCase().startsWith(wort))).map((r: any) => r.person_id);
  return { clubsprecher: mit("clubsprecher"), kassenwart: mit("kassenwart"), admin: (data ?? []).filter((r: any) => r.ist_admin).map((r: any) => r.person_id) };
}
async function flFallHolen(id: unknown) {
  const { data: f } = await db.from("kc_club_fl_faelle").select("*").eq("id", String(id || "")).maybeSingle();
  if (!f) throw new Fehler("Fall nicht gefunden.", 404);
  return f;
}
const flTitel = (f: any, name?: string) => `${FL_ARTEN[f.art]?.sym ?? "🤍"} ${FL_ARTEN[f.art]?.t ?? f.art}${name ? ` – ${name}` : ""}`;
// Schritt mit Zuständigem → Aufgabe (wird wie alle Aufgaben mitgeteilt, erinnert und unter „Meine Aufgaben“ abgehakt)
async function flAufgabe(ich: Ich, f: any, s: { text: string; wer: string | null; bis: string | null }, name: string) {
  if (!s.wer) return null;
  const { data: a } = await db.from("kc_club_aufgaben").insert({ protokoll_id: null, person_id: s.wer, text: `${FL_ARTEN[f.art]?.sym ?? "🤍"} ${name}: ${s.text}`.slice(0, 300), faellig: s.bis, erstellt_von: ich.person_id }).select().single();
  return a ?? null;
}
async function flListe(ich: Ich) {
  const [{ data: offen }, { data: zu }] = await Promise.all([
    db.from("kc_club_fl_faelle").select("*").eq("status", "offen").order("erstellt_am", { ascending: false }).limit(50),
    db.from("kc_club_fl_faelle").select("*").eq("status", "abgeschlossen").order("abgeschlossen_am", { ascending: false }).limit(20),
  ]);
  const faelle = [...(offen ?? []), ...(zu ?? [])], ids = faelle.map((f: any) => f.id);
  const { data: sch } = ids.length ? await db.from("kc_club_fl_schritte").select("*").in("fall_id", ids).order("sort") : { data: [] as any[] };
  const aids = (sch ?? []).map((s: any) => s.aufgabe_id).filter(Boolean);
  const { data: auf } = aids.length ? await db.from("kc_club_aufgaben").select("id,erledigt_am,mitgeteilt_am").in("id", aids) : { data: [] as any[] };
  const aufrufIds = faelle.map((f: any) => f.aufruf_id).filter(Boolean);
  const [{ data: ant }, leute] = await Promise.all([
    aufrufIds.length ? db.from("kc_club_hilfe_antworten").select("aufruf_id,person_id,antwort").in("aufruf_id", aufrufIds) : Promise.resolve({ data: [] as any[] }),
    personen([...faelle.map((f: any) => f.person_id), ...(sch ?? []).map((s: any) => s.wer)]),
  ]);
  const n = (pid: string | null) => (pid ? leute.get(pid)?.display_name || pid : null);
  return {
    arten: Object.fromEntries(Object.entries(FL_ARTEN).map(([k, v]) => [k, { sym: v.sym, t: v.t, gruppe: v.gruppe, betrag: v.betrag ?? null, schritte: v.schritte }])),
    rollen: await flRollen(),
    faelle: faelle.map((f: any) => {
      const s = (sch ?? []).filter((x: any) => x.fall_id === f.id).map((x: any) => {
        const a = (auf ?? []).find((y: any) => y.id === x.aufgabe_id);
        return { id: x.id, text: x.text, wer: x.wer, werName: n(x.wer), alle: x.alle, bis: x.bis, erledigt: !!(x.erledigt_am || a?.erledigt_am), mitgeteilt: !!a?.mitgeteilt_am };
      });
      const kommen = (ant ?? []).filter((y: any) => y.aufruf_id === f.aufruf_id && y.antwort === "komme").map((y: any) => n(y.person_id));
      return { id: f.id, art: f.art, person_id: f.person_id, name: n(f.person_id), notiz: f.notiz, datum: f.datum, termin: f.termin, termin_ort: f.termin_ort,
        betrag: f.betrag === null ? null : Number(f.betrag), status: f.status, informiert_am: f.informiert_am, aufruf: f.aufruf_id ? { id: f.aufruf_id, kommen } : null,
        erstellt_am: f.erstellt_am, abgeschlossen_am: f.abgeschlossen_am, schritte: s, erledigt: s.filter((x: any) => x.erledigt).length };
    }),
  };
}

// ---------- Sitzungsprotokolle (KC-CLUB-PROTOKOLLE) & Aufgaben (KC-CLUB-AUFGABEN) ----------
// Schreiben darf jedes Mitglied mit Leserecht (der Schriftführer wechselt); ändern: Verfasser oder Organisation.
// Ablauf: Vorlage → Entwurf (Foto/Datei anhängen) → veröffentlichen → 7 Tage Einspruch → genehmigt.
const EINSPRUCH_TAGE = 7;
const nurProtokolle = (ich: Ich) => { if (!ich.protokolle) throw new Fehler("Protokolle sind nur für Mitglieder.", 403); };
const darfBearbeiten = (ich: Ich, pr: any) => pr.verfasser === ich.person_id || ich.vorstand;
// Entwurf (nie veröffentlicht): Verfasser oder Organisation; veröffentlicht: nur Organisation (Clubsprecher, Kassenwart, Admin)
const darfProtokollLoeschen = (ich: Ich, pr: any) => ich.vorstand || (pr.verfasser === ich.person_id && pr.status === "entwurf" && pr.version === 1);
async function protokollLeser(): Promise<string[]> {
  const [leute, { data: r }] = await Promise.all([aktiveMitglieder(), db.from("kc_club_rollen").select("person_id").eq("protokolle_lesen", false)]);
  const aus = new Set((r ?? []).map((x: any) => x.person_id));
  return leute.map((m) => m.person_id).filter((id) => !aus.has(id));
}
// KC-CLUB-PROTOKOLL-NAECHSTER-TERMIN (1.84.0, Wunsch Hansi): Vorschlag = die nächste geplante Sitzung nach dem Protokolldatum
async function protokollNaechsterVorschlag(pr: any) {
  // KC-CLUB-RC-PRUEFUNG (20.10.2026): Tagesende in deutscher Zeit (vorher UTC – Sitzungen am Abend nach 22/23 Uhr fielen falsch)
  const d0 = String(pr.datum || ""), ab = new Date(berlinZuUtc(Number(d0.slice(0, 4)), Number(d0.slice(5, 7)), Number(d0.slice(8, 10)), 23, 59).getTime() + 59999).toISOString();
  const { data } = await db.from("kc_club_treffen").select("titel,beginn,ort").eq("art", "treffen").neq("status", "abgesagt").gt("beginn", ab).order("beginn").limit(1);
  const t: any = data?.[0];
  return t ? txt(`${t.titel} · ${wann(t.beginn)}${t.ort ? " · " + t.ort : ""}`, 200) : null;
}
async function protokollHolen(id: unknown) {
  const { data } = await db.from("kc_club_sitzungsprotokolle").select("*").eq("id", String(id || "")).maybeSingle();
  if (!data) throw new Fehler("Protokoll nicht gefunden.", 404);
  return data;
}
function protokollStatus(pr: any, offeneEinwaende: number) {
  if (pr.status === "entwurf") return "entwurf";
  if (offeneEinwaende > 0) return "einwand";
  return pr.einspruch_bis && pr.einspruch_bis > jetzt() ? "einspruch" : "genehmigt";
}
const tagText = (d: string) => fTag.format(new Date(d + "T12:00:00Z"));
async function aufgabenMitteilen(aufgaben: any[], von: Ich, titel: string | null) {
  // je Person eine Benachrichtigung; nur einmal (mitgeteilt_am)
  const jePerson = new Map<string, any[]>();
  for (const a of aufgaben) {
    if (a.erledigt_am || a.mitgeteilt_am) continue;
    const { data: ok } = await db.from("kc_club_aufgaben").update({ mitgeteilt_am: jetzt() }).eq("id", a.id).is("mitgeteilt_am", null).select("id");
    if (!ok?.length || a.person_id === von.person_id) continue;
    jePerson.set(a.person_id, [...(jePerson.get(a.person_id) ?? []), a]);
  }
  for (const [pid, liste] of jePerson) {
    const zeilen = liste.map((a) => `📌 ${a.text}${a.faellig ? ` (bis ${tagText(a.faellig)})` : ""}`);
    await senden("club_aufgabe", [pid], {
      titel: liste.length === 1 ? "📌 Neue Aufgabe für dich" : `📌 ${liste.length} neue Aufgaben für dich`, kurz: liste.map((a) => a.text).join(" · ").slice(0, 150),
      betreff: `Köcheclub Werne – ${liste.length === 1 ? "neue Aufgabe" : "neue Aufgaben"} für dich`,
      text: `Hallo,\n\n${von.name} hat dir ${titel ? `im Protokoll „${titel}“ ` : ""}${liste.length === 1 ? "eine Aufgabe" : "Aufgaben"} eingetragen:\n\n${zeilen.join("\n")}\n\nAbhaken in der Köcheclub-App: ${APP_URL}#protokolle\n\nViele Grüße\nKöcheclub Werne`,
      url: APP_URL + "#protokolle",
    }, `club-aufgabe:${pid}:${liste.map((a) => a.id).join(",").slice(0, 80)}`);
  }
}
async function aufgabeHolen(ich: Ich, id: unknown) {
  const { data: a } = await db.from("kc_club_aufgaben").select("*").eq("id", String(id || "")).maybeSingle();
  if (!a) throw new Fehler("Aufgabe nicht gefunden.", 404);
  const pr = a.protokoll_id ? await protokollHolen(a.protokoll_id) : null;
  const verwalten = ich.vorstand || a.erstellt_von === ich.person_id || (pr ? darfBearbeiten(ich, pr) : false);
  return { a, pr, verwalten };
}

// ---------- Aktionen / Ausflüge (KC-CLUB-AKTIONEN) ----------
// Quelle ist der KC Manager (Bereich „Aktivitäten / Ausflüge“) – die Club-App liest nur, keine zweite Datenhaltung.
// Teilnehmer: Mitglied im KC Manager (m_kc_…) → kc_core_people über Nachname + Anfang des Vornamens (Anne/Annegret).
// KC-CLUB-BUERO-ADRESSEN (2.125.0): Felder der KC-Verwaltungs-Adressen (17_address_inventory_core.js), die das Büro sieht/melden darf
const ADR_FELDER: [string, number][] = [["salutation", 30], ["title", 40], ["firstName", 60], ["lastName", 60], ["company", 120], ["contactPerson", 80], ["category", 40], ["status", 20],
  ["street", 120], ["zip", 12], ["city", 80], ["country", 40], ["phone1", 40], ["phone2", 40], ["fax", 40], ["website", 160], ["email1", 120], ["email2", 120], ["notes", 1000]];
const ADR_MITGLIED_KAT = new Set(["Mitglied", "Mitarbeiter"]);
const adrIstMitglied = (a: any) => a?.sourceType === "member" || !!a?.sourceMemberId || ADR_MITGLIED_KAT.has(String(a?.category || ""));
function adrSauber(a: any, nurFelder = false): Record<string, string> {
  const o: Record<string, string> = {};
  if (!nurFelder) { o.id = txt(a?.id, 80); o.no = txt(a?.no, 20); o.geaendert = txt(a?.updatedAt, 40); }
  for (const [k, n] of ADR_FELDER) { const v = txt(a?.[k], n); if (v) o[k] = v; }
  return o;
}
const AKTIONEN_QUELLE = { tabelle: "kc_manager_state_sections", aktionen: "activities", mitglieder: "members", adressen: "addresses", auswahl: "combos" }; // adressen/auswahl: KC-CLUB-BUERO-ADRESSEN (2.125.0)
const namensSchluessel = (vor: string, nach: string) => `${String(nach || "").trim().toLowerCase()}|${String(vor || "").trim().toLowerCase().slice(0, 3)}`;
// Reiseverlauf aus der Beschreibung („11.05.2027 Bremerhaven - 12.05.2027 Seetag - …“); Preiszeilen werden abgeschnitten
function reiseverlauf(beschreibung: unknown) {
  const t = String(beschreibung ?? "").replace(/\s*\n\s*/g, " ");
  const schnitt = t.search(/[A-ZÄÖÜ]{2,}-Tarif|\bTarif\b|\d+\s*x\s|€/);
  const kurz = schnitt >= 0 ? t.slice(0, schnitt) : t;
  return [...kurz.matchAll(/(\d{2})\.(\d{2})\.(\d{4})\s+(.+?)(?=\s+-\s+\d{2}\.\d{2}\.\d{4}|\s*-?\s*$)/g)]
    .map((m) => ({ datum: `${m[3]}-${m[2]}-${m[1]}`, ort: m[4].trim() }));
}
async function aktionenRoh() {
  const { data } = await db.from(AKTIONEN_QUELLE.tabelle).select("payload,updated_at").eq("org_id", ORG).eq("section_key", AKTIONEN_QUELLE.aktionen).maybeSingle();
  const liste = (Array.isArray(data?.payload?.data) ? data.payload.data : []).filter((a: any) => /^\d{4}-\d{2}-\d{2}$/.test(String(a?.dateFrom || "")));
  return { liste, stand: data?.updated_at ?? null };
}
async function aktionenLesen(ich: Ich) {
  const [{ liste, stand }, { data: mg }, leute] = await Promise.all([
    aktionenRoh(),
    db.from(AKTIONEN_QUELLE.tabelle).select("payload").eq("org_id", ORG).eq("section_key", AKTIONEN_QUELLE.mitglieder).maybeSingle(),
    aktiveMitglieder(),
  ]);
  const kern = new Map(leute.map((p) => [namensSchluessel(p.given_name || p.display_name.split(" ")[0], (p as any).family_name || p.display_name.split(" ").slice(-1)[0]), p]));
  const mgMap = new Map((Array.isArray(mg?.payload?.data) ? mg.payload.data : []).map((m: any) => [m.id, m]));
  const aktionen = liste.map((a: any) => {
    const teilnehmer = (Array.isArray(a.participants) ? a.participants : []).map((t: any) => {
      const m: any = mgMap.get(t.memberId);
      const p: any = m ? kern.get(namensSchluessel(m.firstName, m.lastName)) : null;
      return { person_id: p?.person_id ?? null, name: p?.display_name || [m?.preferredName || m?.firstName, m?.lastName].filter(Boolean).join(" ") || "unbekannt", bestaetigt: !!t.confirmed };
    }).sort((x: any, y: any) => x.name.localeCompare(y.name));
    const dabei = teilnehmer.some((t: any) => t.person_id === ich.person_id);
    return {
      id: String(a.id), titel: txt(a.activity, 200) || "Aktion", veranstalter: txt(a.organizer, 120) || null, von: a.dateFrom, bis: a.dateTo || a.dateFrom,
      status: txt(a.status, 40) || null, stattgefunden: !!a.tookPlace, anreise: txt(a.mobility, 60) || null, verlauf: reiseverlauf(a.description), teilnehmer, dabei,
      // Kosten und Reisebüro nur für Teilnehmende und Admin; Bemerkungen (z. B. Versicherungen einzelner) nur für den Admin
      ...(dabei || ich.admin ? {
        kosten: { proPerson: Number(a.costPerPerson) || null, zusatz: Number(a.extraCostPerPerson) || null },
        reisebuero: a.travelAgency ? { name: txt(a.travelAgency, 120), kontakt: txt(a.travelAgencyContact, 120) || null, telefon: txt(a.travelAgencyPhone, 40) || null } : null,
      } : {}),
      ...(ich.admin ? { bemerkung: txt(a.remarks, 1000) || null } : {}),
    };
  }).sort((x: any, y: any) => String(x.von).localeCompare(String(y.von)));
  const mf = await mitfahrtenZu(ich, "aktion", aktionen.map((a: any) => a.id));
  const su = await suchendeZu(ich, "aktion", aktionen.map((a: any) => String(a.id)));
  for (const a of aktionen as any[]) { a.mitfahrten = mf.get(a.id) ?? []; a.mitfahrtSuche = su.get(String(a.id)) ?? []; }
  return { aktionen, stand };
}

// ---------- Mitglieder-Details (KC-CLUB-KONTAKT) ----------
// Handy, E-Mail, Adresse aus kc_core_people (führend); Festnetz nur aus dem KC Manager (Mitglieder, gleiche Zuordnung wie bei Aktionen).
// Sichtbar: eigene Daten immer; Admin alles; sonst nur, was das Mitglied freigegeben hat – und nur mit Recht „Kontakte sehen“.
const KONTAKT_FELDER = ["handy", "festnetz", "mail", "adresse"];
async function festnetzAusManager(p: any) {
  const { data: mg } = await db.from(AKTIONEN_QUELLE.tabelle).select("payload").eq("org_id", ORG).eq("section_key", AKTIONEN_QUELLE.mitglieder).maybeSingle();
  const schluessel = namensSchluessel(p.given_name || p.display_name.split(" ")[0], p.family_name || p.display_name.split(" ").slice(-1)[0]);
  const m: any = (Array.isArray(mg?.payload?.data) ? mg.payload.data : []).find((x: any) => namensSchluessel(x.firstName, x.lastName) === schluessel);
  return txt(m?.phone, 40) || null;
}

// ---------- Mitfahrgelegenheiten (KC-CLUB-MITFAHREN) ----------
// Bezug: Treffen/Veranstaltung (kc_club_treffen) oder Aktion (ID aus dem KC Manager).
async function mitfahrtenZu(ich: Ich, art: "treffen" | "aktion", ids: string[]) {
  if (!ids.length) return new Map<string, any[]>();
  const { data: mf } = await db.from("kc_club_mitfahrt").select("*").eq("bezug_art", art).in("bezug_id", ids).order("erstellt_am");
  const mids = (mf ?? []).map((m: any) => m.id);
  const { data: pl } = mids.length ? await db.from("kc_club_mitfahrt_platz").select("mitfahrt_id,person_id").in("mitfahrt_id", mids) : { data: [] as any[] };
  const leute = await personen([...(mf ?? []).map((m: any) => m.fahrer), ...(pl ?? []).map((x: any) => x.person_id)]);
  const aus = new Map<string, any[]>();
  for (const m of mf ?? []) {
    const mit = (pl ?? []).filter((x: any) => x.mitfahrt_id === m.id);
    aus.set(m.bezug_id, [...(aus.get(m.bezug_id) ?? []), {
      id: m.id, fahrer: { person_id: m.fahrer, name: leute.get(m.fahrer)?.display_name || m.fahrer }, plaetze: m.plaetze, treffpunkt: m.treffpunkt, notiz: m.notiz,
      mitfahrer: mit.map((x: any) => leute.get(x.person_id)?.display_name || x.person_id), frei: Math.max(0, m.plaetze - mit.length),
      eigen: m.fahrer === ich.person_id, dabei: mit.some((x: any) => x.person_id === ich.person_id), darfLoeschen: m.fahrer === ich.person_id || ich.vorstand,
    }]);
  }
  return aus;
}
// KC-CLUB-MITFAHRT-SUCHE (0.87.0): wer zu einem Termin/einer Aktion eine Mitfahrgelegenheit sucht
async function suchendeZu(ich: Ich, art: "treffen" | "aktion", ids: string[]) {
  const aus = new Map<string, any[]>();
  if (!ids.length) return aus;
  const { data: s } = await db.from("kc_club_mitfahrt_suche").select("bezug_id,person_id,notiz").eq("bezug_art", art).in("bezug_id", ids).order("erstellt_am");
  const leute = await personen((s ?? []).map((x: any) => x.person_id));
  for (const x of s ?? []) aus.set(x.bezug_id, [...(aus.get(x.bezug_id) ?? []), { person_id: x.person_id, name: leute.get(x.person_id)?.display_name || x.person_id, notiz: x.notiz, eigen: x.person_id === ich.person_id }]);
  return aus;
}
// Mitfahren (suchen, anbieten, Platz buchen) bei Treffen nur nach Zusage („Ich komme“); Veranstaltungen/Aktionen ohne Zusage
async function mitfahrtErlaubt(ich: Ich, art: string, bid: string) {
  if (art !== "treffen") return;
  const { data: t } = await db.from("kc_club_treffen").select("art,status").eq("id", bid).maybeSingle();
  if (!t || t.status !== "geplant") throw new Fehler("Dieser Termin ist nicht mehr offen.", 409);
  if (t.art === "veranstaltung") return;
  const { data: tn } = await db.from("kc_club_teilnahme").select("antwort").eq("treffen_id", bid).eq("person_id", ich.person_id).maybeSingle();
  if (tn?.antwort !== "ja") throw new Fehler("Bitte zuerst „✅ Ich komme“ antippen – dann kannst du mitfahren oder eine Fahrt anbieten.", 409);
}
async function mitfahrtBezugTitel(art: string, id: string) {
  if (art === "treffen") {
    const { data: t } = await db.from("kc_club_treffen").select("id,titel,beginn").eq("id", id).maybeSingle();
    return t ? `${t.titel} (${wann(t.beginn)})` : null;
  }
  const a: any = (await aktionenRoh()).liste.find((x: any) => String(x.id) === id);
  return a ? txt(a.activity, 200) : null;
}

// ---------- KC-CLUB-LIVE-TERMIN (2.231.0, Wunsch Hansi): Live-Abstimmung über den nächsten Sitzungstermin ----------
// Am Ende der Sitzung startet der Clubsprecher (Vorstand/Admin) eine Live-Abstimmung – Vorschlag aus dem Kalender: letzter Freitag
// des nächsten Monats, Uhrzeit/Ort wie beim letzten Köcheclub-Treffen. Alle mit offener App bekommen ein Fenster mit dem Termin,
// einem Blick in ihren Club-App-Kalender (Treffen, eigene Termine, Dienste) und „✅ Ich kann / ❔ Unter Vorbehalt / ❌ Ich kann nicht“.
// Der Sprecher sieht das Ergebnis live und legt fest (vorhandener Kern terminumfrage_festlegen: Termin + Zusagen) oder schlägt eine
// Alternative vor. Nach dem Festlegen fragt jede App: „In deinen Kalender eintragen?“. Läuft höchstens LIVE_TERMIN_STD Stunden.
const LIVE_TERMIN_STD = 3;
// KC-CLUB-ONLINE-SPARSAM: für die Online-Meldung 15 s gemerkt (KC-CLUB-START-SPARSAM-2: 30 s; Speichern einer Umfrage leert den Merker) (alle Mitglieder fragen dasselbe; Start/Ende einer Live-Umfrage meldet zusätzlich die direkte Leitung)
let LIVE_KURZ: { t: number; v: Promise<any> } | null = null;
function liveTerminKurz() { if (!LIVE_KURZ || Date.now() - LIVE_KURZ.t > 30000) LIVE_KURZ = { t: Date.now(), v: liveTerminAktiv().catch((e) => { LIVE_KURZ = null; throw e; }) }; return LIVE_KURZ.v; }
async function liveTerminAktiv() {
  const { data } = await db.from("kc_club_terminumfragen").select("*").eq("live", true).gte("erstellt_am", new Date(Date.now() - LIVE_TERMIN_STD * 3600000).toISOString())
    .order("erstellt_am", { ascending: false }).limit(1).maybeSingle();
  return data ?? null;
}
// Blick in den eigenen Club-App-Kalender am Vorschlagstag (nur eigene Daten): Club-Termine, private Termine, eigene Dienste
async function liveTerminKalender(ich: Ich, beginn: string) {
  const tag = berlinTag(new Date(beginn)), [y, m, d] = tag.split("-").map(Number);
  const von = berlinZuUtc(y, m, d, 0, 0).toISOString(), bis = berlinZuUtc(y, m, d + 1, 0, 0).toISOString();
  const [{ data: tr }, priv, { data: di }] = await Promise.all([
    db.from("kc_club_treffen").select("titel,beginn,ganztaegig").eq("status", "geplant").gte("beginn", von).lt("beginn", bis).order("beginn").limit(10),
    privatListe(ich, von, bis).catch(() => [] as any[]),
    db.from("kc_dp_plan_published").select("start_time,end_time,area").eq("org_id", ORG).eq("status", "published").eq("person_id", ich.person_id).eq("work_date", tag),
  ]);
  const zeit = (b: string, g?: boolean) => (g ? "ganztägig" : new Intl.DateTimeFormat("de-DE", { timeZone: TZ, hour: "2-digit", minute: "2-digit" }).format(new Date(b)) + " Uhr");
  return [
    ...(tr ?? []).map((t: any) => ({ art: "club", text: `📅 ${txt(t.titel, 80)} (${zeit(t.beginn, t.ganztaegig)})` })),
    ...priv.filter((x: any) => x.beginn >= von && x.beginn < bis).map((x: any) => ({ art: "privat", text: `🔒 ${txt(x.titel, 80)} (${zeit(x.beginn, x.ganztaegig)})` })),
    ...(di ?? []).map((x: any) => ({ art: "dienst", text: `🗓️ Dienst ${String(x.start_time).slice(0, 5)}–${String(x.end_time).slice(0, 5)} Uhr${x.area ? " · " + txt(x.area, 40) : ""}` })),
  ];
}
// Vorschlag „aus dem Kalender“: letzter Freitag des nächsten Monats, Uhrzeit + Ort wie beim letzten Köcheclub-Treffen
async function liveTerminVorschlag() {
  const { data: letzt } = await db.from("kc_club_treffen").select("beginn,ort,titel").eq("art", "treffen").lte("beginn", new Date(Date.now() + 60 * 86400000).toISOString())
    .order("beginn", { ascending: false }).limit(1).maybeSingle();
  const hm = letzt ? new Intl.DateTimeFormat("de-DE", { timeZone: TZ, hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).format(new Date(letzt.beginn)) : "19:00";
  const h = berlinTag(new Date()), j = +h.slice(0, 4), mo = +h.slice(5, 7);
  const ny = mo === 12 ? j + 1 : j, nm = mo === 12 ? 1 : mo + 1; // nächster Monat
  let tag = new Date(Date.UTC(ny, nm, 0)).getUTCDate(); while (new Date(Date.UTC(ny, nm - 1, tag)).getUTCDay() !== 5) tag--;
  const [hh, mm] = hm.split(":").map(Number);
  return { beginn: berlinZuUtc(ny, nm, tag, hh, mm).toISOString(), ort: letzt?.ort ?? null, titel: "Köcheclub-Treffen" };
}
async function liveTerminStand(ich: Ich, u: any) {
  const { data: opt } = await db.from("kc_club_terminumfrage_optionen").select("id,beginn").eq("umfrage_id", u.id).order("reihenfolge");
  const o = (opt ?? []).find((x: any) => x.id === u.live_option) ?? (opt ?? [])[(opt ?? []).length - 1];
  const { data: ant } = o ? await db.from("kc_club_terminumfrage_antworten").select("person_id,antwort").eq("option_id", o.id) : { data: [] as any[] };
  const leiter = ich.vorstand || u.erstellt_von === ich.person_id;
  const leute = leiter ? await personen((ant ?? []).map((x: any) => x.person_id)) : new Map();
  const liste = (w: string) => (ant ?? []).filter((x: any) => x.antwort === w);
  let treffen: any = null;
  if (u.status === "festgelegt" && u.festgelegt_treffen_id) {
    const { data: t } = await db.from("kc_club_treffen").select("id,titel,beginn,ende,ort,beschreibung,ganztaegig").eq("id", u.festgelegt_treffen_id).maybeSingle();
    treffen = t ?? null;
  }
  return { id: u.id, status: u.status, titel: u.titel, ort: u.ort, stand: u.geaendert_am, leiter, von: vorname((await personen([u.erstellt_von])).get(u.erstellt_von)) || "",
    option: o ? { id: o.id, beginn: o.beginn } : null, alternativen: Math.max(0, (opt ?? []).length - 1),
    zahlen: { ja: liste("ja").length, vielleicht: liste("vielleicht").length, nein: liste("nein").length },
    namen: leiter ? Object.fromEntries(["ja", "vielleicht", "nein"].map((w) => [w, liste(w).map((x: any) => vorname(leute.get(x.person_id)) || x.person_id).sort()])) : null,
    meine: (ant ?? []).find((x: any) => x.person_id === ich.person_id)?.antwort ?? null,
    kalender: o && u.status === "offen" ? await liveTerminKalender(ich, o.beginn).catch(() => null) : null, treffen };
}

// ---------- Terminfindung (KC-CLUB-TERMINFINDUNG) ----------
async function terminumfragenListe(ich: Ich) {
  const [{ data: offen }, { data: fertig }] = await Promise.all([
    db.from("kc_club_terminumfragen").select("*").eq("status", "offen").order("erstellt_am", { ascending: false }).limit(20),
    db.from("kc_club_terminumfragen").select("*").neq("status", "offen").order("geaendert_am", { ascending: false }).limit(5),
  ]);
  const alle = [...(offen ?? []), ...(fertig ?? [])];
  const ids = alle.map((u: any) => u.id);
  const { data: opt } = ids.length ? await db.from("kc_club_terminumfrage_optionen").select("*").in("umfrage_id", ids).order("beginn") : { data: [] as any[] };
  const oids = (opt ?? []).map((o: any) => o.id);
  const { data: ant } = oids.length ? await db.from("kc_club_terminumfrage_antworten").select("option_id,person_id,antwort").in("option_id", oids) : { data: [] as any[] };
  const [leute, anl] = await Promise.all([personen([...alle.map((u: any) => u.erstellt_von), ...(ant ?? []).map((x: any) => x.person_id)]), objAnlagenHolen("terminumfrage", ids)]); // 2.448.0: + Anlagen
  const name = (id: string) => leute.get(id)?.display_name || id;
  return alle.map((u: any) => {
    const o = (opt ?? []).filter((x: any) => x.umfrage_id === u.id);
    const a = (ant ?? []).filter((x: any) => o.some((y: any) => y.id === x.option_id));
    return {
      id: u.id, titel: u.titel, beschreibung: u.beschreibung, ort: u.ort, art: u.art, status: u.status, frist: u.frist, festgelegt_option: u.festgelegt_option, anlagen: anl.get(u.id) ?? [],
      von: name(u.erstellt_von), antwortende: new Set(a.map((x: any) => x.person_id)).size,
      optionen: o.map((x: any) => {
        const z = (w: string) => a.filter((y: any) => y.option_id === x.id && y.antwort === w).map((y: any) => name(y.person_id)).sort();
        return { id: x.id, beginn: x.beginn, ja: z("ja"), vielleicht: z("vielleicht"), nein: z("nein"), meine: a.find((y: any) => y.option_id === x.id && y.person_id === ich.person_id)?.antwort ?? null };
      }),
      darfFestlegen: u.status === "offen" && (ich.vorstand || u.erstellt_von === ich.person_id),
      darfLoeschen: ich.vorstand || u.erstellt_von === ich.person_id,
    };
  });
}

// ---------- KC-CLUB-SCHULUNGSTERMINE (2.23.59, Wunsch Hansi): Schulungs-/Besuchstermine aus Hansis Termin-Programm (kc_termin_*) ----------
// Nur lesend (Adapter auf die Tabellen des Termin-Programms – es bleibt die führende Stelle). Admin sieht alle, Mitglieder nur ihre eigenen.
// Gebucht = vorgemerkt/bestätigt, Termin nicht abgesagt, keine Testtermine. Namen aus kc_core_people, keine Kontaktdaten.
const SCHULUNG_ART: Record<string, string> = { bei_hansi: "bei Hansi", beim_mitglied: "beim Mitglied" };
async function schulungenListe(ich: Ich, von: string, bis: string) {
  // KC-CLUB-SCHULUNG-ABGESAGT-KALENDER (2.30.1, Wunsch Hansi): abgesagte Termine bleiben im Kalender stehen – andere Farbe, „abgesagt“.
  // Abgesagt = eine schon bestätigte Buchung wurde storniert (Termin abgesagt oder Mitglied hat abgesagt); bloß geänderte Vormerkungen nicht.
  const { data: sl, error } = await db.from("kc_termin_slots").select("id,beginn,ende,besuchsart,status,ist_test").in("status", ["offen", "abgesagt"]).eq("ist_test", false).gte("beginn", von).lt("beginn", bis).limit(300);
  if (error || !sl?.length) return [];
  const { data: buRoh } = await db.from("kc_termin_buchungen").select("id,slot_id,einladung_id,personen,besuchsart,status,besuch_id,bestaetigung_gesendet_am").in("slot_id", sl.map((x: any) => x.id)).in("status", ["vorgemerkt", "bestaetigt", "storniert"]);
  const bu = (buRoh ?? []).filter((b: any) => b.status !== "storniert" || b.besuch_id || b.bestaetigung_gesendet_am).map((b: any) => (b.status === "storniert" ? { ...b, status: "abgesagt" } : b));
  const vorbehalt = ich.admin ? await schulungVorbehalt(sl, buRoh ?? []) : []; // KC-CLUB-SCHULUNG-VORBEHALT (2.120.0)
  if (!bu.length) return vorbehalt;
  const { data: ei } = await db.from("kc_termin_einladungen").select("id,person_ids,ist_test").in("id", bu.map((b: any) => b.einladung_id).filter(Boolean));
  const einl = new Map((ei ?? []).map((e: any) => [e.id, e]));
  const liste = bu.map((b: any) => ({ b, s: sl.find((x: any) => x.id === b.slot_id), e: einl.get(b.einladung_id) as any }))
    .filter((x: any) => x.s && x.e && !x.e.ist_test && (ich.admin || (x.e.person_ids ?? []).includes(ich.person_id)));
  const leute = await personen(liste.flatMap((x: any) => x.e.person_ids ?? []));
  return liste.map((x: any) => ({ id: x.b.id, beginn: x.s.beginn, ende: x.s.ende, status: x.b.status, art: SCHULUNG_ART[x.b.besuchsart || x.s.besuchsart] || "",
    besuch: x.b.besuch_id || null, namen: (x.e.person_ids ?? []).map((id: string) => vorname(leute.get(id)) || leute.get(id)?.display_name || "Mitglied"),
    ichDabei: (x.e.person_ids ?? []).includes(ich.person_id) })).concat(vorbehalt).sort((a: any, b: any) => String(a.beginn).localeCompare(String(b.beginn)));
}
// KC-CLUB-SCHULUNG-VORBEHALT (2.120.0, Wunsch Hansi „Termine unter Vorbehalt im Kalender – da ist nix drin“): angebotene Termine,
// die noch niemand gewählt hat, stehen für den Admin im Kalender – „unter Vorbehalt“, mit den Vornamen der Eingeladenen, denen der
// Termin gerade angeboten wird (offene, gültige Einladung; leere slot_ids = alle freien Termine). Nur lesend, nur Admin.
async function schulungVorbehalt(sl: any[], buRoh: any[]) {
  const aktiv = new Set(buRoh.filter((b: any) => b.status === "vorgemerkt" || b.status === "bestaetigt").map((b: any) => b.slot_id));
  const jetztIso = new Date().toISOString();
  const frei = sl.filter((s: any) => s.status === "offen" && !aktiv.has(s.id) && s.beginn > jetztIso);
  if (!frei.length) return [];
  const { data: ei } = await db.from("kc_termin_einladungen").select("person_ids,slot_ids").eq("status", "offen").eq("ist_test", false).gt("gueltig_bis", jetztIso).limit(100);
  const leute = await personen((ei ?? []).flatMap((e: any) => e.person_ids ?? []));
  return frei.map((s: any) => {
    const an = (ei ?? []).filter((e: any) => !(e.slot_ids ?? []).length || (e.slot_ids ?? []).includes(s.id)).flatMap((e: any) => e.person_ids ?? []);
    return { id: "vb:" + s.id, beginn: s.beginn, ende: s.ende, status: "vorbehalt", art: SCHULUNG_ART[s.besuchsart] || "", besuch: null,
      namen: [...new Set(an)].map((id: string) => vorname(leute.get(id)) || leute.get(id)?.display_name || "Mitglied"), ichDabei: false };
  });
}

// ---------- KC-CLUB-SCHULUNG-HINWEIS (2.23.68, Wunsch Hansi): was wartet, was ist neu, was steht an – nur lesend ----------
const SCHULUNG_NEU = ["link_geoeffnet", "termin_gewaehlt", "gegenvorschlag", "abgesagt", "antwort_zurueckgenommen", "frist_abgelaufen", "erinnerung_gesendet"];
// KC-CLUB-SCHULUNG-PROTOKOLL (2.23.69): bestätigte Termine der letzten 30 Tage, deren Besuchsprotokoll noch fehlt (kein Besuch oder noch „geplant“)
async function schulungProtokollFehlt() {
  const jetztMs = Date.now();
  const { data: sl } = await db.from("kc_termin_slots").select("id,beginn,ende").eq("ist_test", false).lt("ende", new Date(jetztMs).toISOString()).gt("ende", new Date(jetztMs - 30 * 86400000).toISOString()).limit(200);
  if (!sl?.length) return [];
  const { data: bu } = await db.from("kc_termin_buchungen").select("id,slot_id,einladung_id,besuch_id").eq("status", "bestaetigt").in("slot_id", sl.map((x: any) => x.id));
  if (!bu?.length) return [];
  const bids = bu.map((b: any) => b.besuch_id).filter(Boolean);
  const { data: be } = bids.length ? await db.from("kc_besuche").select("besuch_id,status").in("besuch_id", bids) : { data: [] as any[] };
  const fertig = new Set((be ?? []).filter((x: any) => x.status !== "geplant").map((x: any) => x.besuch_id));
  const offen = bu.filter((b: any) => !b.besuch_id || !fertig.has(b.besuch_id));
  if (!offen.length) return [];
  const { data: ei } = await db.from("kc_termin_einladungen").select("id,person_ids,ist_test").in("id", offen.map((b: any) => b.einladung_id));
  const em = new Map<string, any>((ei ?? []).filter((e: any) => !e.ist_test).map((e: any) => [e.id, e]));
  const leute = await personen([...em.values()].flatMap((e: any) => e.person_ids ?? []));
  return offen.filter((b: any) => em.has(b.einladung_id)).map((b: any) => ({ beginn: sl.find((x: any) => x.id === b.slot_id)?.beginn || null,
    namen: (em.get(b.einladung_id).person_ids ?? []).map((id: string) => vorname(leute.get(id)) || leute.get(id)?.display_name || "Mitglied").join(" & ") }));
}
// KC-CLUB-SCHULUNG-VERSANDSTAND (2.25.2, Hinweis Hansi „die Sachen sind über den Club rübergekommen“): Belege je Einladung und Schritt
// (einladung/bestaetigung/erinnerung/dank) aus drei Wegen – Termin-Programm (Protokoll mit Versandergebnis je Person, „nicht zugestellt“
// zählt NICHT), Club-Chat (eigene Nachricht in einer Unterhaltung, deren Teilnehmer nur Admin + Personen dieser Einladung sind – keine
// großen Gruppen) und Communicator-Mail von Hand (geplanter Versand an diese Personen). Chat/Mail werden über Stichwort + Zeitfenster
// zugeordnet: Erinnerung = „erinner…“ in den 3 Tagen vor Beginn, Dank = „dank…“ bis 7 Tage nach Beginn. Belege tragen Zeit, Weg, Personen.
const SC_VS_AKTION: Record<string, string> = { eingeladen: "einladung", erneut_eingeladen: "einladung", neue_termine_angeboten: "einladung",
  buchung_bestaetigt: "bestaetigung", gegenvorschlag_angenommen: "bestaetigung", termin_direkt_bestaetigt: "bestaetigung", termin_geaendert: "bestaetigung", erinnerung_gesendet: "erinnerung" };
const SC_VS_TAG = 86400000;
// KC-CLUB-AMPEL (2.287.0): je Einladung, wer sie wirklich bekommen hat – Push auf dem Handy angezeigt/geöffnet, vom Mail-Anbieter bestätigt
// oder die Club-App seit dem Versand geöffnet (dort steht die Einladung auch). Gesendet, Link geöffnet und Antwort stehen schon in der Einladung.
async function schulungAmpel(j: any) {
  const eins = (j.einladungen ?? []).filter((e: any) => e.gesendet_am && !e.ist_test && !["zurueckgezogen"].includes(e.status)).slice(0, 60);
  const aus: Record<string, any> = {};
  if (!eins.length) return aus;
  const alle = [...new Set(eins.flatMap((e: any) => e.person_ids ?? []))] as string[];
  const [{ data: req }, { data: zg }, inko] = await Promise.all([
    db.from("kc_communication_requests").select("id,correlation_id,audit_meta,channel,status").like("correlation_id", "termin-mitglied:%").gte("created_at", new Date(Math.min(...eins.map((e: any) => Date.parse(e.gesendet_am))) - 3600000).toISOString()).limit(2000),
    alle.length ? db.from("kc_club_zugang").select("person_id,zuletzt_gesehen").in("person_id", alle).not("zuletzt_gesehen", "is", null) : Promise.resolve({ data: [] as any[] }),
    inkognitoSet(alle)]);
  const rIds = (req ?? []).map((r: any) => r.id);
  const { data: ev } = rIds.length ? await db.from("kc_communication_delivery_events").select("request_id,event_type,created_at").in("request_id", rIds).in("event_type", ["delivered", "displayed", "opened"]) : { data: [] as any[] };
  for (const e of eins) {
    const zu: Record<string, { am: string; wie: string }> = {};
    for (const r of (req ?? []).filter((x: any) => String(x.correlation_id).startsWith(`termin-mitglied:${e.id}:`))) {
      const pid = String(r.audit_meta?.personId || ""); if (!pid) continue;
      for (const x of (ev ?? []).filter((y: any) => y.request_id === r.id)) if (!zu[pid] || x.created_at < zu[pid].am) zu[pid] = { am: x.created_at, wie: x.event_type === "delivered" ? "vom Mail-Anbieter bestätigt" : "Push auf dem Handy angezeigt" };
    }
    for (const pid of e.person_ids ?? []) {
      const z = (zg ?? []).find((x: any) => x.person_id === pid);
      if (!zu[pid] && z && !inko.has(pid) && String(z.zuletzt_gesehen) >= e.gesendet_am) zu[pid] = { am: z.zuletzt_gesehen, wie: "Club-App seitdem geöffnet" };
    }
    aus[e.id] = { angekommen: zu };
  }
  return aus;
}
async function schulungVersandstand(j: any, ich: Ich) {
  const eins = (j.einladungen ?? []).filter((e: any) => e.status !== "zurueckgezogen" && !e.ist_test).slice(0, 40);
  const st: Record<string, Record<string, any[]>> = {};
  if (!eins.length) return st;
  const add = (eid: string, k: string, beleg: any) => { const x = st[eid] || (st[eid] = {}); (x[k] || (x[k] = [])).push(beleg); };
  const pm = await personen(eins.flatMap((e: any) => e.person_ids ?? []));
  const nameVon = (id: string) => pm.get(id)?.display_name || id;
  // 1) Termin-Programm: Protokoll mit Versandergebnis („Name: Mail + Push“ bzw. „Name: nicht zugestellt (…)“)
  const { data: pr } = await db.from("kc_termin_protokoll").select("zeit,aktion,einladung_id,details").in("einladung_id", eins.map((e: any) => e.id))
    .in("aktion", Object.keys(SC_VS_AKTION)).order("zeit").limit(1000);
  for (const x of pr ?? []) {
    const v = String(x.details?.versand ?? ""); if (!v || v === "keiner") continue;
    const teile = v.split("; ").map((t) => { const i = t.indexOf(": "); return { name: t.slice(0, i), wie: t.slice(i + 2) }; }).filter((t) => t.name);
    add(x.einladung_id, SC_VS_AKTION[x.aktion], { zeit: x.zeit, weg: "termin", an: teile.filter((t) => /^(Mail|Push)/.test(t.wie)).map((t) => t.name),
      nicht: teile.filter((t) => !/^(Mail|Push)/.test(t.wie)).map((t) => t.name), text: v.slice(0, 200) });
  }
  // Beginn je Einladung (bestätigte, sonst vorgemerkte Buchung)
  const beginn = new Map<string, number>();
  for (const e of eins) {
    const bs = (j.buchungen ?? []).filter((b: any) => b.einladung_id === e.id), b = bs.find((x: any) => x.status === "bestaetigt") || bs.find((x: any) => x.status === "vorgemerkt");
    const s = b && (j.slots ?? []).find((x: any) => x.id === b.slot_id); if (s?.beginn) beginn.set(e.id, new Date(s.beginn).getTime());
  }
  if (!beginn.size) return st;
  const fenster = (eid: string, zeit: string, text: string) => { const t = new Date(zeit).getTime(), b = beginn.get(eid)!;
    return /erinner/i.test(text) && t >= b - 3 * SC_VS_TAG && t <= b ? "erinnerung" : /dank/i.test(text) && t >= b && t <= b + 7 * SC_VS_TAG ? "dank" : null; };
  const alle = [...new Set(eins.filter((e: any) => beginn.has(e.id)).flatMap((e: any) => e.person_ids ?? []))], frueh = new Date(Math.min(...beginn.values()) - 3 * SC_VS_TAG).toISOString();
  // 2) Club-Chat: nur Unterhaltungen, in denen außer mir ausschließlich Personen dieser Einladung sind
  const { data: tp } = alle.length ? await db.from("kc_communication_thread_participants").select("thread_id").in("person_id", alle).limit(2000) : { data: [] as any[] };
  const tIds = [...new Set((tp ?? []).map((x: any) => x.thread_id))];
  if (tIds.length) {
    const [{ data: teil }, { data: msgs }] = await Promise.all([
      db.from("kc_communication_thread_participants").select("thread_id,person_id").in("thread_id", tIds).limit(5000),
      db.from("kc_communication_messages").select("thread_id,body,created_at").in("thread_id", tIds).eq("sender_person_id", ich.person_id).gte("created_at", frueh).order("created_at").limit(1000)]);
    const tMap = new Map<string, string[]>(); for (const x of teil ?? []) { const l = tMap.get(x.thread_id) || []; l.push(x.person_id); tMap.set(x.thread_id, l); }
    for (const m of msgs ?? []) for (const e of eins) {
      if (!beginn.has(e.id)) continue;
      const andere = (tMap.get(m.thread_id) ?? []).filter((id) => id !== ich.person_id);
      if (!andere.length || !andere.every((id) => (e.person_ids ?? []).includes(id))) continue;
      const k = fenster(e.id, m.created_at, m.body || ""); if (k) add(e.id, k, { zeit: m.created_at, weg: "chat", an: andere.map(nameVon), nicht: [], text: String(m.body || "").slice(0, 160) });
    }
  }
  // 3) Communicator-Mail von Hand (geplanter Versand) an Personen dieser Einladung
  const { data: jobs } = await db.from("kc_communication_scheduled_jobs").select("audience,subject,message,status,result,processed_at,scheduled_for").gte("scheduled_for", frueh).in("status", ["sent", "partial"]).limit(500);
  for (const jb of jobs ?? []) {
    const ids: string[] = jb.audience?.type === "persons" && Array.isArray(jb.audience.personIds) ? jb.audience.personIds : [];
    const ok = new Set(((jb.result?.attempts ?? []) as any[]).filter((a) => a.ok).map((a) => a.personId));
    for (const e of eins) {
      if (!beginn.has(e.id)) continue;
      const treffer = ids.filter((id) => (e.person_ids ?? []).includes(id)); if (!treffer.length) continue;
      const k = fenster(e.id, jb.processed_at || jb.scheduled_for, `${jb.subject || ""} ${jb.message || ""}`);
      if (k) add(e.id, k, { zeit: jb.processed_at || jb.scheduled_for, weg: "mail", an: treffer.filter((id) => ok.has(id)).map(nameVon), nicht: treffer.filter((id) => !ok.has(id)).map(nameVon), text: String(jb.subject || "").slice(0, 160) });
    }
  }
  return st;
}
async function schulungStand(ich: Ich, seit: string | null) {
  const [{ data: vb }, { data: ei }] = await Promise.all([
    db.from("kc_termin_buchungen").select("id,slot_id,einladung_id").eq("status", "vorgemerkt").limit(100),
    db.from("kc_termin_einladungen").select("id,person_ids,status,ist_test").in("status", ["gegenvorschlag", "abgelaufen"]).eq("ist_test", false).limit(100)]);
  const ids = [...new Set((vb ?? []).map((b: any) => b.einladung_id))];
  const { data: ve } = ids.length ? await db.from("kc_termin_einladungen").select("id,person_ids,ist_test").in("id", ids) : { data: [] as any[] };
  const { data: vs } = (vb ?? []).length ? await db.from("kc_termin_slots").select("id,beginn").in("id", (vb ?? []).map((b: any) => b.slot_id)) : { data: [] as any[] };
  // 2.301.0 KC-CLUB-SCHNECKE-START: die drei unabhängigen Lesungen sofort mitstarten (vorher nacheinander am Ende); Fehler wirken wie bisher beim await
  const jetztMs = Date.now(), pProtFehlt = schulungProtokollFehlt(), pNachfrage = schulungNachfrageFaellig(),
    pBald = schulungenListe(ich, new Date(jetztMs).toISOString(), new Date(jetztMs + 2 * 86400000).toISOString());
  for (const x of [pProtFehlt, pNachfrage, pBald]) x.catch(() => {}); // nur „behandelt“ markieren – kein unbehandelter Fehler, falls vorher etwas abbricht
  let neu: any[] = [];
  if (seit) {
    const { data: pr } = await db.from("kc_termin_protokoll").select("zeit,aktion,einladung_id,details").in("wer", ["mitglied", "system"]).in("aktion", SCHULUNG_NEU)
      .gt("zeit", seit).order("zeit", { ascending: false }).limit(20);
    neu = pr ?? [];
  }
  const alleE = new Map([...(ve ?? []), ...(ei ?? [])].map((e: any) => [e.id, e]));
  const fehlend = [...new Set(neu.map((x) => x.einladung_id).filter((id) => id && !alleE.has(id)))];
  if (fehlend.length) { const { data: ne } = await db.from("kc_termin_einladungen").select("id,person_ids,ist_test").in("id", fehlend); for (const e of ne ?? []) alleE.set(e.id, e); }
  const leute = await personen([...alleE.values()].flatMap((e: any) => e.person_ids ?? []));
  const namen = (e: any) => (e?.person_ids ?? []).map((id: string) => vorname(leute.get(id)) || leute.get(id)?.display_name || "Mitglied").join(" & ");
  const wartet = [
    ...(vb ?? []).filter((b: any) => alleE.get(b.einladung_id) && !alleE.get(b.einladung_id).ist_test)
      .map((b: any) => ({ art: "gewaehlt", namen: namen(alleE.get(b.einladung_id)), beginn: (vs ?? []).find((s: any) => s.id === b.slot_id)?.beginn || null })),
    ...(ei ?? []).map((e: any) => ({ art: e.status, namen: namen(e), beginn: null })),
    ...(await pProtFehlt).map((x: any) => ({ art: "protokoll", namen: x.namen, beginn: x.beginn })), // 2.23.69
    ...(await pNachfrage).map((b: any) => ({ art: "nachfrage", namen: b.mitglied, beginn: b.datum + "T12:00:00Z", besuch_id: b.besuch_id }))]; // 2.35.0
  const bald = (await pBald).filter((x: any) => x.status === "bestaetigt")
    .map((x: any) => ({ beginn: x.beginn, ende: x.ende, namen: x.namen.join(" & "), art: x.art }));
  return { wartet, bald, neu: neu.filter((x) => !alleE.get(x.einladung_id)?.ist_test).map((x) => ({ zeit: x.zeit, aktion: x.aktion, namen: (x.details?.namen as string) || namen(alleE.get(x.einladung_id)) })) };
}

// ---------- KC-CLUB-SCHULUNG-ADMIN (2.23.60, Wunsch Hansi): Termin-Programm als Admin-Bereich „🎓 Schulungen“ der Club-App ----------
// Die Bedienung gehört jetzt zur Club-App (kein zweites Programm, keine zweite Anmeldung). Die Termin-Logik bleibt EIN Kern:
// der vorhandene Baustein kc-termine (sichere Platzvergabe, Fristen, Erinnerungen, Mails mit Link für Mitglieder ohne App,
// Google-Abgleich) – die Club-App ruft ihn intern mit dem Admin-Schlüssel aus dem Vault auf. Nichts wird doppelt gebaut.
const SCHULUNG_AKTIONEN = new Set([ // nur Admin-Aktionen; Mitglieder gehen über schulung_meine/schulung_antwort
  "t_init", "t_chronologie", "t_slots_anlegen", "t_slot_absagen", "t_slot_loeschen", "t_einladen", "t_erneut_einladen",
  "t_link", "t_buchung_entscheiden", "t_vorschlag_entscheiden", "t_zurueckziehen", "t_besuch_termin",
  "t_kalender_schluessel"]); // 2.23.65: Google-Kalender verbinden (Schlüssel wird nur einmal angezeigt, nicht protokolliert)
async function schulungAufruf(a: string, daten: Record<string, unknown>) {
  const { data: token } = await db.rpc("kc_communication_get_server_secret", { p_name: "kc_termine_admin_token" });
  if (!token) throw new Fehler("Der Termin-Baustein ist nicht erreichbar (Schlüssel fehlt).", 503);
  const r = await fetch(`${SUPA}/functions/v1/kc-termine`, { method: "POST", signal: AbortSignal.timeout(25000),
    headers: { "Content-Type": "application/json", "x-kc-termine-admin-token": String(token) }, body: JSON.stringify({ ...daten, action: a, test: false }) });
  dbPufferLeeren(); // KC-CLUB-DB-SPARSAM: der Termin-Baustein schreibt selbst
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Fehler(String(j?.error || "Der Termin-Baustein antwortet nicht."), r.status >= 500 ? 502 : r.status === 401 ? 503 : r.status);
  return j;
}

// ---------- KC-CLUB-BESUCHE (2.23.61, Wunsch Hansi): Besuchsprotokoll in der Club-App (Stufe 2, Admin) ----------
// Übernommen aus dem Besuchsprotokoll (gleiche Tabelle kc_besuche, gleiche Fotos) – die Club-App ist ab jetzt der Ort dafür;
// das alte Programm bleibt bis zur Abschaltung nur zum Nachschauen. Ohne Foto-Auswertung (kostenpflichtig, Wunsch Hansi: weglassen).
// Zusammenfassung nach dem Besuch: Push + Mail (BCC an Hansi) über die Club-Benachrichtigung, Kopie in den Archiv-Ordner des Mitglieds.
const BESUCH_FELDER = ["person_ids", "mitglied", "anwesende", "ort", "datum", "zeit_von", "zeit_bis", "km_einfach", "f1_praesentation", "f2_bild_spruch", "f2_spruch",
  "f3_kasse", "f4_dienstplan", "f5_verwaltung", "f6_router", "f7_thema", "f7_antwort", "notizen", "vereinbarungen", "bemerkungen", "status", "besuchsart",
  "zusammenfassung_senden", "schulung_thema", "installiert_auf", "programme"];
const BESUCH_BUCKET = "kc-besuche-fotos", BESUCH_REGISTER = "Schulung";
const BESUCH_TEXTE: Record<string, [string, Record<string, string>]> = {
  f1_praesentation: ["Weihnachtsmarkt-Präsentation", { rathaus: "Rathaus-Version", rot: "Rote Version", offen: "noch offen" }],
  f2_bild_spruch: ["Mit Bild und Spruch in der Präsentation", { ja: "ja", nein: "nein", klaeren: "wird noch geklärt" }],
  f3_kasse: ["Kassenprogramm", { alt: "alte Oberfläche", neu: "neue Oberfläche", offen: "Entscheidung offen" }],
  f4_dienstplan: ["Dienstplanprogramm", { ja: "ja", nein: "nein", spaeter: "später entscheiden" }],
  f5_verwaltung: ["KC Verwaltung", { ja: "ja", nein: "nein", spaeter: "später entscheiden" }],
  f6_router: ["Stand-Vernetzung mit 5G-Router", { ja: "ja", nein: "nein", spaeter: "später entscheiden" }],
};
const BESUCH_GERAETE: Record<string, string> = { tablet: "Tablet", notebook: "Notebook", pc: "PC", handy: "Handy", leih: "Leihgerät (folgt)" }; // 2.35.0: Notebook, Leihgerät
// KC-CLUB-SCHULUNG-NACHFRAGE (2.35.0, Wunsch Hansi): welche Programme gezeigt/installiert wurden – EINE Liste (die App bekommt sie vom Server)
const SCHULUNG_PROGRAMME: Record<string, [string, string, string]> = { // Kennung → [Symbol, Name, „den/die/das …“ für den Nachfragetext]
  bilderrechner: ["🖼️", "Bilderrechner", "den Bilderrechner"], clubapp: ["📱", "Köcheclub-App", "die Köcheclub-App"], kasse: ["🧾", "Kassenprogramm", "das Kassenprogramm"],
  dienstplan: ["🗓️", "Dienstplan", "den Dienstplan"], verwaltung: ["🗂️", "KC Verwaltung", "die KC Verwaltung"], praesentation: ["🎄", "Weihnachtsmarkt-Präsentation", "die Weihnachtsmarkt-Präsentation"] };
const NACHFRAGE_TAGE = 28;
// fällig: fertiger Besuch vor ≥ 4 Wochen, noch nicht nachgefragt, nicht abgewählt; nur Leihgerät (noch nicht da) → noch warten
async function schulungNachfrageFaellig() {
  const bis = berlinTag(new Date(Date.now() - NACHFRAGE_TAGE * 86400000));
  const { data, error } = await db.from("kc_besuche").select("besuch_id,person_ids,mitglied,datum,installiert_auf,programme,nachfrage_erinnert_am")
    .eq("status", "fertig").lte("datum", bis).gte("datum", "2026-09-01").is("nachfrage_gesendet_am", null).eq("nachfrage_aus", false).limit(100);
  if (error) return [];
  return (data ?? []).filter((b: any) => !(b.installiert_auf ?? []).includes("leih") || (b.installiert_auf ?? []).some((g: string) => g !== "leih"));
}
// einmal je Besuch: Push/Mail an den Admin „Nachfrage fällig“ (gesendet wird nur von Hand, mit einem Tipp – nie automatisch an Mitglieder)
// ---------- KC-CLUB-DIENST-GRUSS (2.224.0, Wunsch Hansi „Weihnachtsmarkt: Freitag, Samstag, Sonntag rote Kochjacken, den Rest der
// Woche weiße – täglich daran erinnern, wenn man Dienst hat; Wetter prüfen und Kleidungs-Hinweise geben (–5 Grad: Handschuhe und Mütze;
// Regen: Schirm …); beim Programmstart ein Fenster: ich wünsche einen angenehmen Dienst heute“) ----------
// Regeln als Registry: weitere Veranstaltung/Kleiderordnung = weiterer Eintrag. Wochentage: 0 = Sonntag … 6 = Samstag.
const DIENST_KLEIDUNG = [
  { id: "markt", re: /weihnachtsmarkt/i, ohne: /aufbau|abbau|nachbereitung|vorbereitung/i, jacke: (wt: number) => ([5, 6, 0].includes(wt) ? "rot" : "weiss") },
];
const DG_WIND_KMH = 40; // ab diesen Böen Hinweis „Stand sichern“ (wie Wetter-Hinweis in der App)
const JACKE_TEXT: Record<string, string> = { rot: "🔴 rote Kochjacke", weiss: "⚪ weiße Kochjacke" };
const berlinWochentag = (tag: string) => new Date(tag + "T12:00:00Z").getUTCDay();
async function dienstVeranstaltung(tag: string) {
  const { data } = await db.from("kc_club_treffen").select("id,titel,beginn,ende").eq("art", "veranstaltung").eq("status", "geplant")
    .lte("beginn", new Date(Date.parse(tag + "T23:59:59Z") + 2 * 3600000).toISOString()).order("beginn").limit(60);
  for (const t of data ?? []) {
    const von = berlinTag(new Date(t.beginn)), bis = berlinTag(new Date(t.ende || t.beginn));
    if (von > tag || bis < tag) continue;
    const r = DIENST_KLEIDUNG.find((x) => x.re.test(String(t.titel || "")) && !x.ohne.test(String(t.titel || "")));
    if (r) return { titel: txt(t.titel, 120), jacke: r.jacke(berlinWochentag(tag)) };
  }
  return null;
}
// Kleidungs-Hinweise aus dem Wetter am Ort des Clubs für die Dienstzeit (3-Stunden-Werte, sonst Tageswerte). Ohne Daten: ehrlich „unbekannt“.
const WETTER_REGEN = (c: number) => (c >= 51 && c <= 67) || (c >= 80 && c <= 82) || c >= 95, WETTER_SCHNEE = (c: number) => (c >= 71 && c <= 77) || c === 85 || c === 86;
async function dienstWetter(tag: string, von: string, bis: string) {
  const k = await wetterKonfig(), { c, fehler } = await wetterHolen(k);
  const t = c?.daten?.tage?.find((x) => x.datum === tag);
  if (!t) return { ort: k.ort.name, hinweise: [] as string[], unbekannt: true, fehler: fehler || "Für heute liegen keine Wetterdaten vor" };
  const st = (t.stunden ?? []).filter((x) => x.zeit >= String(von).slice(0, 2) + ":00" && x.zeit <= String(bis).slice(0, 5));
  const temps = st.length ? st.map((x) => x.temp) : [t.min, t.max], codes = st.length ? st.map((x) => x.code) : [t.code];
  const min = Math.round(Math.min(...temps)), max = Math.round(Math.max(...temps));
  const regen = Math.max(...(st.length ? st.map((x) => x.regenWkt ?? 0) : [t.regenWkt ?? 0]));
  const h: string[] = [];
  if (min <= 0) h.push(`🥶 Heute bis ${min} Grad – denk an Handschuhe, Mütze und warme Schuhe.`);
  else if (min <= 6) h.push(`🧣 Kühl (${min} Grad) – warme Jacke, Schal und Mütze einpacken.`);
  if (codes.some(WETTER_SCHNEE)) h.push("❄️ Schnee möglich – feste, rutschfeste Schuhe anziehen.");
  if (codes.some((x) => x >= 95)) h.push("⛈️ Gewitter möglich – Stand und Schirme gut sichern.");
  if (regen >= 50 || codes.some(WETTER_REGEN)) h.push(`☂️ Regen möglich${regen ? ` (${regen} %)` : ""} – denk an den Schirm oder die Regenjacke.`);
  if ((t.boeenMax ?? 0) >= DG_WIND_KMH) h.push(`💨 Windig (Böen bis ${Math.round(t.boeenMax ?? 0)} km/h) – Deko und Stand gut befestigen.`);
  if (!h.length) h.push(max >= 25 ? "☀️ Warm – genug trinken und an Sonnenschutz denken." : "🌤️ Kein Regen gemeldet – angenehmes Dienstwetter.");
  return { ort: k.ort.name, min, max, code: codes[0], regen, hinweise: h, stand: c ? new Date(c.zeit).toISOString() : null, unbekannt: false };
}
async function dienstGruss(pid: string, tag: string) {
  const { data: sch } = await db.from("kc_dp_plan_published").select("start_time,end_time,area").eq("org_id", ORG).eq("status", "published")
    .eq("person_id", pid).eq("work_date", tag).order("start_time");
  if (!sch?.length) return null;
  const schichten = sch.map((x: any) => ({ start: String(x.start_time).slice(0, 5), ende: String(x.end_time).slice(0, 5), bereich: x.area ?? null }));
  const [veranstaltung, wetter] = await Promise.all([
    dienstVeranstaltung(tag).catch((e) => { console.error("dienst veranstaltung", String(e)); return null; }),
    dienstWetter(tag, schichten[0].start, schichten[schichten.length - 1].ende).catch((e) => ({ hinweise: [] as string[], unbekannt: true, fehler: txt(String(e?.message || e), 120) })),
  ]);
  return { tag, schichten, veranstaltung, jacke: veranstaltung?.jacke ?? null, wetter };
}
// Morgens ab 8 Uhr: wer heute auf dem Weihnachtsmarkt (o. ä., siehe DIENST_KLEIDUNG) Dienst hat, bekommt einmal Kochjacke + Wetter
async function dienstGrussSenden() {
  if (berlinStunde(new Date()) < 8) return;
  const tag = berlinTag(new Date());
  const v = await dienstVeranstaltung(tag); if (!v) return;
  const { data: sch } = await db.from("kc_dp_plan_published").select("person_id").eq("org_id", ORG).eq("status", "published").eq("work_date", tag);
  const ids = [...new Set((sch ?? []).map((x: any) => x.person_id).filter(Boolean))] as string[];
  if (!ids.length) return;
  const { data: schon } = await db.from("kc_club_person_einstellung").select("person_id,wert").eq("schluessel", "dienst_gruss_gesendet").in("person_id", ids);
  const offen = ids.filter((pid) => (schon ?? []).find((x: any) => x.person_id === pid)?.wert?.tag !== tag);
  for (const pid of offen) {
    const g = await dienstGruss(pid, tag); if (!g) continue;
    const zeiten = g.schichten.map((x) => `${x.start}–${x.ende} Uhr${x.bereich ? " · " + x.bereich : ""}`).join(", ");
    const jacke = g.jacke ? JACKE_TEXT[g.jacke] : "", hw = g.wetter.hinweise.length ? g.wetter.hinweise : ["❔ Das Wetter konnte gerade nicht abgerufen werden."];
    await senden("club_nachricht", [pid], {
      titel: `👨‍🍳 Heute Dienst – ${jacke || txt(v.titel, 40)}`, kurz: `${zeiten}${hw[0] ? " · " + hw[0] : ""}`,
      betreff: `Köcheclub Werne – heute Dienst: ${txt(v.titel, 60)}`,
      text: `Hallo,\n\nich wünsche dir einen angenehmen Dienst heute!\n\n🕐 ${zeiten}\n${jacke ? `👨‍🍳 Heute bitte die ${jacke.replace(/^\S+ /, "")} anziehen.\n` : ""}\n${hw.join("\n")}\n\n${APP_URL}#dienstgruss\n\nViele Grüße\nKöcheclub Werne`,
      url: APP_URL + "#dienstgruss",
    }, `club-dienst-gruss:${pid}:${tag}`).catch((e) => console.error("dienst gruss senden", String(e)));
    await db.from("kc_club_person_einstellung").upsert({ person_id: pid, schluessel: "dienst_gruss_gesendet", wert: { tag }, geaendert_am: jetzt() }, { onConflict: "person_id,schluessel" });
  }
  await protokoll(null, "dienst_gruss_gesendet", { tag, veranstaltung: v.titel, anzahl: offen.length });
}
// ---------- KC-CLUB-RT-SPARBREMSE (2.230.0, Wunsch Hansi „was, wenn es mehr Aufrufe werden als kostenlos enthalten?“) ----------
// Supabase Realtime kostenlos: 2 Mio. Signale je Monat. Die Datenbank zählt mit (kc_club_rt_zaehler) und bremst selbst: ab 70 % keine
// „teuren“ Signale (tippt, Live-Bild, online, Pinnwand, Termine, Abstimmungen), ab 95 % nur noch Alarm (kc_club_rt_klingeln).
// Hier nur die Warnung an den Admin – je Stufe einmal im Monat (Push). Die App fragt bei gebremsten Signalen wie früher selbst nach.
const RT_GRENZE = 2000000, RT_STUFEN: [number, string][] = [[50, "Hälfte erreicht – alles läuft normal weiter"], [70, "Sparbremse aktiv: „schreibt gerade“, Live-Bild, Online, Pinnwand, Termine und Abstimmungen kommen wieder über das normale Nachfragen"], [95, "nur noch Alarm über die direkte Leitung – alles andere über das normale Nachfragen"]];
// KC-CLUB-GASTGEBER-STAND (2.238.0, Wunsch Hansi): Wer bei einem Treffen als Gastgeber/in eingetragen ist (z. B. Anne), bekommt
// am Vorabend (ab 18 Uhr) und 2 Stunden vor Beginn Push + E-Mail mit dem Anmeldestand (Zusagen mit Namen, vielleicht, Absagen, offen,
// Notizen wie „bringe Gast mit“) – die Clubleitung (Vorstand + Admin) bekommt dasselbe. Jede Stufe nur einmal (Merker im Protokoll).
// 2.481.0 KC-CLUB-GASTGEBER-FRUEHWARNUNG (Wunsch Hansi „1 Tag vorher E-Mail und Push, wie viele sich angemeldet haben, 2 Stunden vorher nochmal –
// aber nur, falls Änderungen da sind; ansonsten nur bei Änderung“): Vorabend (ab 18 Uhr) wie bisher immer; danach meldet jede Änderung
// (Zu-/Absage, Notiz) kurz an die Gastgeberin – gesammelt (höchstens alle 15 Min.), nachts (22–7 Uhr) zurückgehalten; 2 Stunden vorher der
// ganze Stand nur, wenn sich seit der letzten Meldung etwas geändert hat. Merker: der gemeldete Stand steht im Protokoll (details.stand).
const GG_PAUSE_MS = 15 * 60000;
const ggTeil = (v: string) => { const i = (v || "").indexOf("|"); return i < 0 ? [v || "", ""] : [v.slice(0, i), v.slice(i + 1)]; };
function ggStand(an: any[]) { const s: Record<string, string> = {}; for (const x of an) if (x.antwort && x.antwort !== "keine") s[x.person_id] = `${x.antwort}|${String(x.notiz || "").trim()}`; return s; }
function ggUnterschiede(alt: Record<string, string>, neu: Record<string, string>, name: (id: string) => string) {
  const z: string[] = [];
  for (const id of new Set([...Object.keys(alt), ...Object.keys(neu)])) {
    const [a, an] = ggTeil(alt[id]), [b, bn] = ggTeil(neu[id]);
    if (a !== b) z.push(b === "ja" ? `✅ ${name(id)} hat zugesagt` : b === "nein" ? `❌ ${name(id)} hat abgesagt` : b === "vielleicht" ? `❔ ${name(id)}: vielleicht` : `↩️ ${name(id)} hat die Antwort zurückgenommen`);
    else if (an !== bn && bn) z.push(`📝 ${name(id)}: ${bn}`);
  }
  return z;
}
async function gastgeberStandLauf() {
  const jetztMs = Date.now(), std = berlinStunde(new Date()), heuteAbend = std >= 18, nachts = std >= 22 || std < 7, morgen = berlinTag(new Date(jetztMs + 86400000));
  const { data: ts } = await db.from("kc_club_treffen").select("id,titel,beginn,ort,gastgeber_person_id").eq("status", "geplant").eq("art", "treffen")
    .gte("beginn", new Date(jetztMs).toISOString()).lte("beginn", new Date(jetztMs + 2 * 86400000).toISOString());
  for (const t of ts ?? []) {
    const bis = Date.parse(t.beginn) - jetztMs; if (bis <= 0) continue;
    const { data: frueher } = await db.from("kc_club_protokoll").select("zeit,details").eq("aktion", "gastgeber_stand").eq("details->>treffen", t.id).order("zeit", { ascending: false }).limit(30);
    const war = (st: string) => (frueher ?? []).some((x: any) => x.details?.stufe === st), letzte = (frueher ?? []).find((x: any) => x.details?.stand) as any;
    const vorabendFaellig = !war("vorabend") && heuteAbend && berlinTag(new Date(t.beginn)) === morgen;
    const zweiStd = bis <= 2 * 3600000 && !war("2std");
    const altVorabend = !letzte && war("vorabend"); // Vorabend noch von einer älteren Serverversion (ohne gemerkten Stand) → 2 Std. vorher wie bisher
    if (!vorabendFaellig && !letzte && !(zweiStd && altVorabend)) continue; // vor dem Vorabend nichts – Änderungen davor stehen in der Vorabend-Meldung
    const [{ data: an }, mitglieder] = await Promise.all([db.from("kc_club_teilnahme").select("person_id,antwort,notiz").eq("treffen_id", t.id), aktiveMitglieder()]);
    const stand = ggStand(an ?? []);
    const pm = await personen([...new Set([...Object.keys(stand), ...Object.keys(letzte?.details?.stand ?? {}), ...(t.gastgeber_person_id ? [t.gastgeber_person_id] : [])])]);
    const name = (id: string) => { const x = pm.get(id); return x ? x.display_name || vorname(x) : id; };
    const aenderungen = letzte ? ggUnterschiede(letzte.details.stand, stand, name) : [];
    let stufe: string | null = null;
    if (vorabendFaellig) stufe = "vorabend";
    else if (zweiStd) stufe = aenderungen.length || altVorabend ? "2std" : "2std_ruhig";
    else if (aenderungen.length && !nachts && jetztMs - Date.parse(letzte.zeit) >= GG_PAUSE_MS) stufe = "aenderung";
    if (!stufe) continue;
    if (stufe === "2std_ruhig") { await protokoll(null, "gastgeber_stand", { treffen: t.id, stufe: "2std", uebersprungen: "keine Änderung", stand }); continue; }
    const gruppe = (a: string) => (an ?? []).filter((x: any) => x.antwort === a);
    const ja = gruppe("ja"), vl = gruppe("vielleicht"), nein = gruppe("nein");
    const geantwortet = new Set((an ?? []).map((x: any) => x.person_id)), offen = mitglieder.filter((m) => !geantwortet.has(m.person_id));
    const notizen = (an ?? []).filter((x: any) => x.notiz && x.antwort !== "nein").map((x: any) => `• ${name(x.person_id)}: ${x.notiz}`);
    const liste = (l: any[]) => l.map((x) => name(x.person_id)).sort((a, b) => a.localeCompare(b, "de")).join(", ");
    const g = t.gastgeber_person_id ? pm.get(t.gastgeber_person_id) : null;
    const wo = t.ort || (g ? `bei ${vorname(g)}` : "");
    const wannText = stufe === "2std" ? `in 2 Stunden (${fZeit.format(new Date(t.beginn))} Uhr)` : stufe === "aenderung" ? wann(t.beginn, true) : `morgen, ${wann(t.beginn, true)}`;
    const zahl = `✅ ${ja.length} Zusage${ja.length === 1 ? "" : "n"}${vl.length ? ` · ❔ ${vl.length} vielleicht` : ""} · ❌ ${nein.length} Absage${nein.length === 1 ? "" : "n"} · ⏳ ${offen.length} noch offen`;
    const text = (fuerGast: boolean) => `Hallo,\n\n${fuerGast ? `du bist Gastgeberin/Gastgeber beim Treffen „${t.titel}“ – ` : `Stand der Anmeldungen für „${t.titel}“ – `}${wannText}${wo ? ", " + wo : ""}.\n\n`
      + (aenderungen.length ? `Neu seit der letzten Meldung:\n${aenderungen.join("\n")}\n\n` : "") + `${zahl}\n\n`
      + (ja.length ? `Zugesagt: ${liste(ja)}\n` : "Noch keine Zusagen.\n") + (vl.length ? `Vielleicht: ${liste(vl)}\n` : "") + (nein.length ? `Abgesagt: ${liste(nein)}\n` : "")
      + (notizen.length ? `\nHinweise:\n${notizen.join("\n")}\n` : "")
      + (fuerGast ? `\nBitte plane für ${ja.length}${vl.length ? ` bis ${ja.length + vl.length}` : ""} Personen.\n` : "")
      + `\nAktueller Stand jederzeit in der Köcheclub-App: ${APP_URL}#termine\n\nViele Grüße\nKöcheclub Werne`;
    const neuKurz = aenderungen.slice(0, 2).join(" · ") + (aenderungen.length > 2 ? ` (+${aenderungen.length - 2})` : "");
    const kurz = stufe === "aenderung" ? `${neuKurz} – jetzt ${ja.length} Zusagen${vl.length ? `, ${vl.length} vielleicht` : ""}`
      : `${t.titel} ${stufe === "2std" ? "in 2 Std." : "morgen"}: ${ja.length} Zusagen${vl.length ? `, ${vl.length} vielleicht` : ""}, ${offen.length} offen`;
    // Änderungen nur an die Gastgeberin; Vorabend und 2 Std. vorher (mit Änderung) auch an die Clubleitung – wie bisher
    const leitung = stufe === "aenderung" ? [] : (await leitungIds()).filter((id) => id !== t.gastgeber_person_id);
    const kopf = stufe === "2std" ? "Gleich" : stufe === "aenderung" ? "Änderung" : "Morgen";
    await protokoll(null, "gastgeber_stand", { treffen: t.id, stufe, ja: ja.length, vielleicht: vl.length, nein: nein.length, offen: offen.length, gastgeber: t.gastgeber_person_id, leitung: leitung.length, aenderungen: aenderungen.length, stand }); // erst merken, dann senden – nie doppelt
    if (t.gastgeber_person_id) await sendenGewaehlt("club_erinnerung", [t.gastgeber_person_id], ["push", "email"], {
      titel: `🏠 ${kopf} bei dir: ${ja.length} Zusagen`, kurz, betreff: `Köcheclub Werne – ${stufe === "aenderung" ? "Änderung bei den Anmeldungen" : "Anmeldestand"}: ${t.titel}, ${wann(t.beginn)}`,
      text: text(true), url: APP_URL + "#termine" }, `club-gastgeber-stand:${t.id}:${stufe}:${jetztMs}`).catch((e) => console.error("gastgeber stand", String(e)));
    if (leitung.length) await sendenGewaehlt("club_erinnerung", leitung, ["push", "email"], {
      titel: `📋 Anmeldestand ${t.titel}: ${ja.length} Zusagen`, kurz, betreff: `Köcheclub Werne – Anmeldestand (Clubleitung): ${t.titel}, ${wann(t.beginn)}`,
      text: text(false), url: APP_URL + "#termine" }, `club-gastgeber-stand-leitung:${t.id}:${stufe}`).catch((e) => console.error("gastgeber stand leitung", String(e)));
  }
}
// 2.481.0 KC-CLUB-GASTGEBER-FRUEHWARNUNG: die Gastgeberin bekommt Einladung, Änderung und Absage immer per Push UND E-Mail (egal welcher Weg
// sonst gewählt ist) – mit Hinweis, dass sie Gastgeberin ist, und dem aktuellen Stand der Zusagen. Liefert true, wenn gesendet.
async function gastgeberMitteilen(t: any, ich: string, art: "einladung" | "geaendert" | "abgesagt", vars: { titel: string; kurz: string; betreff: string; text: string; url: string }) {
  if (!t.gastgeber_person_id || t.gastgeber_person_id === ich) return false;
  const { count } = await db.from("kc_club_teilnahme").select("person_id", { count: "exact", head: true }).eq("treffen_id", t.id).eq("antwort", "ja");
  const vorn = art === "abgesagt" ? "Du warst als Gastgeberin/Gastgeber eingetragen – das Treffen fällt aus." : `Du bist Gastgeberin/Gastgeber – aktuell ${count ?? 0} Zusage${count === 1 ? "" : "n"}. Am Vorabend bekommst du den genauen Stand, danach jede Änderung.`;
  await sendenGewaehlt("club_erinnerung", [t.gastgeber_person_id], ["push", "email"], { ...vars, titel: `🏠 ${vars.titel}`, kurz: `${vars.kurz}`,
    text: String(vars.text).replace(/^Hallo,\n\n/, `Hallo,\n\n${vorn}\n\n`) }, `club-gastgeber-${art}:${t.id}:${Date.now()}`).catch((e) => console.error("gastgeber mitteilen", String(e)));
  await protokoll(ich, "gastgeber_mitgeteilt", { treffen: t.id, art });
  return true;
}
// ---------- 2.482.0 KC-CLUB-STARTNACHRICHT (Wunsch Hansi „als Admin direkt eine Startnachricht an alle, eine Gruppe oder ausgewählte Personen –
// als wichtig markierbar; beim Programmstart bekommen die Ausgewählten sie; Pflicht-Knopf ‚Gelesen‘ und ein Rückfrage-Knopf, die Antwort kommt bei mir an;
// auch für Clubsprecher und Kassenwart bauen, aber für die beiden noch nicht freischalten“) ----------
// Ohne neue Tabelle und ohne zusätzliche Abfrage beim Start: jede Startnachricht steht beim Empfänger in kc_club_person_einstellung
// (Schlüssel „startnachricht“), die der Start ohnehin ganz lädt. Mitglieder können den Schlüssel NICHT selbst setzen (nicht in EINSTELLUNGEN) –
// gelesen/Rückfrage gehen nur über startnachricht_bestaetigen. Freischaltung für Clubsprecher/Kassenwart: kc_club_konfig „startnachricht“ {aemter}.
const SN_SCHLUESSEL = "startnachricht", SN_MAX_JE_PERSON = 20, SN_MAX_EMPFAENGER = 300, SN_AEMTER = /^(clubsprecher|kassenwart)/i;
async function snAemterFrei() { const { data } = await konfigZeile("startnachricht"); return !!(data?.wert as any)?.aemter; }
async function snDarf(ich: Ich) {
  if (ich.admin) return true;
  if (!(ich.aemter || []).some((x) => SN_AEMTER.test(x))) return false;
  return await snAemterFrei();
}
async function snNurWennDarf(ich: Ich) { if (!(await snDarf(ich))) throw new Fehler("Startnachrichten darfst du (noch) nicht schicken.", 403); }
const snListe = (w: any): any[] => (Array.isArray(w?.liste) ? w.liste : []).filter((x: any) => x && typeof x.id === "string");
async function snEmpfaenger(ich: Ich, an: any): Promise<string[]> {
  const ids = new Set(await empfaengerAufloesen(ich, { personen: an?.personen, aemter: an?.aemter, alle: !!an?.alle }));
  const gruppe = String(an?.gruppe || "");
  if (gruppe) { // Chat-Gruppe – auch ohne selbst darin zu sein (nur wer Startnachrichten schicken darf)
    const { data: g } = await db.from("kc_club_gruppen").select("thread_id").eq("thread_id", gruppe).maybeSingle();
    if (!g) throw new Fehler("Gruppe nicht gefunden.", 404);
    const { data: tn } = await db.from("kc_communication_thread_participants").select("person_id").eq("thread_id", gruppe);
    const aktiv = new Set((await aktiveMitglieder()).map((x) => x.person_id));
    (tn ?? []).forEach((x: any) => { if (x.person_id !== ich.person_id && aktiv.has(x.person_id)) ids.add(String(x.person_id)); });
  }
  return [...ids];
}
// KC-CLUB-ANTWORT-ERINNERUNG-2T (2.240.0, Wunsch Hansi): 2 Tage (48 Std.) vor einem Köcheclub-Treffen eine Push-Erinnerung an alle,
// die noch nicht zu- oder abgesagt haben („vielleicht“ zählt nicht) – passend zum rot blinkenden Hinweis in der App. Einmal je Treffen.
async function antwortErinnerung2T() {
  const jetztMs = Date.now();
  const { data: ts } = await db.from("kc_club_treffen").select("id,titel,beginn,ort").eq("status", "geplant").eq("art", "treffen")
    .gt("beginn", new Date(jetztMs + 6 * 3600000).toISOString()).lte("beginn", new Date(jetztMs + 48 * 3600000).toISOString());
  for (const t of ts ?? []) {
    const { data: schon } = await db.from("kc_club_protokoll").select("id").eq("aktion", "treffen_erinnerung_2t").eq("details->>treffen", t.id).limit(1);
    if (schon?.length) continue;
    const { data: an } = await db.from("kc_club_teilnahme").select("person_id,antwort").eq("treffen_id", t.id).in("antwort", ["ja", "nein"]);
    const klar = new Set((an ?? []).map((x: any) => x.person_id));
    const ziel = (await sammelEmpfaenger()).map((x) => x.person_id).filter((id) => !klar.has(id));
    await protokoll(null, "treffen_erinnerung_2t", { treffen: t.id, empfaenger: ziel.length }); // erst merken, dann senden – nie doppelt
    if (!ziel.length) continue;
    await sendenGewaehlt("club_erinnerung", ziel, ["push"], {
      titel: "🔴 Bitte zu- oder absagen", kurz: `${t.titel} am ${wann(t.beginn)}${t.ort ? " – " + t.ort : ""}: Kommst du?`,
      betreff: `Köcheclub Werne – bitte zu- oder absagen: ${t.titel}, ${wann(t.beginn)}`,
      text: `Hallo,\n\nin 2 Tagen ist unser Treffen „${t.titel}“ (${wann(t.beginn, true)}${t.ort ? ", " + t.ort : ""}).\n\nBitte kurz zu- oder absagen: ${APP_URL}#termine\n\nViele Grüße\nKöcheclub Werne`,
      url: APP_URL + "#termine" }, `club-antwort-2t:${t.id}`).catch((e) => console.error("antwort 2t", String(e)));
  }
}
// KC-CLUB-WICHTIG-UNGELESEN (2.287.0, Wunsch Hansi „nachvollziehen, ob er sie gelesen hat“): Eine ❗ wichtige Nachricht ist nach 24 Std.
// bei jemandem noch nicht gelesen → EINMAL ein Push an den Absender mit den Namen. Ältere als 3 Tage werden nicht mehr nachgemeldet.
// „Schon gemeldet“ steht im Protokoll (erst merken, dann senden – nie doppelt). Notfälle laufen über ihren eigenen Weg.
async function wichtigUngelesenMelden() {
  const j = Date.now();
  const { data: ms } = await db.from("kc_communication_messages").select("id,thread_id,sender_person_id,created_at,body")
    .lte("created_at", new Date(j - 24 * 3600000).toISOString()).gte("created_at", new Date(j - 72 * 3600000).toISOString()).order("created_at").limit(2000);
  if (!ms?.length) return;
  const { data: wi } = await db.from("kc_club_nachricht_wichtig").select("message_id").in("message_id", ms.map((m: any) => m.id));
  const wichtige = ms.filter((m: any) => (wi ?? []).some((w: any) => w.message_id === m.id) && !String(m.body || "").startsWith(NOTFALL_MARKE)).slice(0, 30);
  for (const m of wichtige) {
    const { data: schon } = await db.from("kc_club_protokoll").select("id").eq("aktion", "wichtig_ungelesen").eq("details->>nachricht", m.id).limit(1);
    if (schon?.length) continue;
    const { data: tn } = await db.from("kc_communication_thread_participants").select("person_id,last_read_at").eq("thread_id", m.thread_id).neq("person_id", m.sender_person_id);
    const offen = (tn ?? []).filter((x: any) => !x.last_read_at || x.last_read_at < m.created_at).map((x: any) => x.person_id);
    await protokoll(null, "wichtig_ungelesen", { nachricht: m.id, ungelesen: offen.length });
    if (!offen.length) continue;
    const pm = await personen(offen), namen = offen.slice(0, 5).map((id: string) => pm.get(id)?.display_name || "Mitglied").join(", ") + (offen.length > 5 ? ` und ${offen.length - 5} weitere` : "");
    await sendenGewaehlt("club_nachricht", [m.sender_person_id], ["push"], {
      titel: "❗ Wichtige Nachricht noch ungelesen", kurz: `Seit 24 Std. nicht gelesen: ${namen}`,
      betreff: "Köcheclub Werne – deine wichtige Nachricht ist noch ungelesen",
      text: `Hallo,\n\ndeine wichtige Nachricht „${txt(m.body, 120)}“ ist seit 24 Stunden noch nicht gelesen von: ${namen}.\n\nVielleicht kurz anrufen? In der App unter ℹ️ an der Nachricht siehst du die Ampel je Empfänger.\n\n${APP_URL}#nachricht=${m.thread_id}`,
      url: `${APP_URL}#nachricht=${m.thread_id}` }, `club-wichtig-ungelesen:${m.id}`).catch((e) => console.error("wichtig ungelesen senden", String(e)));
  }
}
async function rtZaehlerWarnen() {
  const monat = berlinTag(new Date()).slice(0, 7);
  const { data } = await db.from("kc_club_rt_zaehler").select("anzahl,gewarnt").eq("monat", monat).maybeSingle();
  if (!data) return;
  const pct = (Number(data.anzahl) / RT_GRENZE) * 100, gewarnt = { ...(data.gewarnt || {}) };
  const stufe = [...RT_STUFEN].reverse().find(([p]) => pct >= p && !gewarnt[String(p)]);
  if (!stufe) return;
  const ziel = await adminIds(); if (!ziel.length) return;
  await sendenGewaehlt("club_nachricht", ziel, ["push"], { titel: `⚡ Direkte Leitung: ${Math.round(pct)} % des Gratis-Kontingents`,
    kurz: stufe[1], betreff: "Köcheclub-App: Kontingent der direkten Leitung",
    text: `Hallo,\n\ndiesen Monat sind ${Number(data.anzahl).toLocaleString("de-DE")} von ${RT_GRENZE.toLocaleString("de-DE")} kostenlosen Signalen der direkten Leitung verbraucht (${Math.round(pct)} %).\n${stufe[1]}.\n\nEs entstehen keine Kosten. Am Monatsanfang beginnt die Zählung neu.`,
    url: APP_URL }, `club-rt-kontingent:${monat}:${stufe[0]}`).catch((e) => console.error("rt warnen", String(e)));
  for (const [p] of RT_STUFEN) if (pct >= p) gewarnt[String(p)] = jetzt();
  await db.from("kc_club_rt_zaehler").update({ gewarnt }).eq("monat", monat);
  await protokoll(null, "rt_kontingent_warnung", { monat, anzahl: data.anzahl, prozent: Math.round(pct) });
}
// KC-CLUB-REISE-CHECKLISTE (2.223.0, Wunsch Hansi „Erinnerung 2 Tage vorher“): ab 9 Uhr, 2 Tage vor einer Kreuzfahrt, jede/r
// Teilnehmende, deren Checkliste noch nicht ganz abgehakt ist (oder die sie noch nie geöffnet haben), einmal Push/E-Mail.
// „Schon erinnert“ merkt sich nur der Server (eigener Schlüssel, die App kann ihn nicht setzen) – kein doppelter Versand.
const RC_KREUZFAHRT = /schiff|kreuz|cruis|fjord|fähre/i; // wie aktionSymbol() in der App
const RC_ERINNERN_TAGE = 2;
async function reiseChecklisteErinnern() {
  if (berlinStunde(new Date()) < 9) return;
  const ziel = berlinTag(new Date(Date.now() + RC_ERINNERN_TAGE * 86400000));
  const { aktionen } = await aktionenLesen({ person_id: "-", name: "System", vorname: "System", admin: false, vorstand: false, aemter: [], protokolle: false, kontakte: false, buero: null, zugang: "mitglied", nurLesen: true }); // KC-CLUB-RC-PRUEFUNG (20.10.2026): zugang ergänzt (Typ Ich)
  for (const a of (aktionen as any[]).filter((x) => x.von === ziel && RC_KREUZFAHRT.test(`${x.titel} ${x.veranstalter || ""}`))) {
    const ids = [...new Set((a.teilnehmer as any[]).map((t) => t.person_id).filter(Boolean))] as string[];
    if (!ids.length) continue;
    const { data: es } = await db.from("kc_club_person_einstellung").select("person_id,schluessel,wert").in("person_id", ids).in("schluessel", ["reise_checkliste", "reise_checkliste_erinnert"]);
    const wert = (pid: string, k: string) => (es ?? []).find((x: any) => x.person_id === pid && x.schluessel === k)?.wert as any;
    for (const pid of ids) {
      const schon: string[] = Array.isArray(wert(pid, "reise_checkliste_erinnert")?.ids) ? wert(pid, "reise_checkliste_erinnert").ids : [];
      if (schon.includes(a.id)) continue;
      const r = wert(pid, "reise_checkliste")?.reisen?.[a.id];
      if (r?.aus) continue; // 2.224.0: Mitglied hat „Nicht mehr erinnern“ gewählt
      if (r?.art && Number(r.offen) === 0 && r.art === "bildschirm") continue; // am Bildschirm alles abgehakt → keine Erinnerung
      const offen = r?.art === "bildschirm" ? Number(r.offen) || 0 : null, url = `${APP_URL}#reisecheckliste=${encodeURIComponent(a.id)}`;
      await senden("club_nachricht", [pid], {
        titel: "🧳 In 2 Tagen geht es los!",
        kurz: offen ? `Auf deiner Checkliste für „${txt(a.titel, 60)}“ sind noch ${offen} Punkte offen.` : `Denk an deine persönliche Checkliste für „${txt(a.titel, 60)}“.`,
        betreff: `Köcheclub Werne – in 2 Tagen: ${txt(a.titel, 80)}`,
        text: `Hallo,\n\nin 2 Tagen beginnt „${txt(a.titel, 120)}“.\n${offen ? `Auf deiner persönlichen Checkliste sind noch ${offen} Punkte offen.` : "Hast du schon an alles gedacht? Deine persönliche Checkliste hilft beim Packen."}\n\n${url}\n\nGute Reise wünscht\nKöcheclub Werne`,
        url,
      }, `club-reise-checkliste:${a.id}:${pid}`).catch((e) => console.error("reise checkliste senden", String(e)));
      await db.from("kc_club_person_einstellung").upsert({ person_id: pid, schluessel: "reise_checkliste_erinnert", wert: { ids: [...schon, a.id].slice(-20) }, geaendert_am: jetzt() }, { onConflict: "person_id,schluessel" });
      await protokoll(null, "reise_checkliste_erinnert", { aktion: a.id, person: pid, offen });
    }
  }
}
async function schulungNachfrageErinnern() {
  const f = (await schulungNachfrageFaellig()).filter((b: any) => !b.nachfrage_erinnert_am);
  if (!f.length) return;
  const ziel = await adminIds(); if (!ziel.length) return;
  const namen = f.map((b: any) => `${b.mitglied} (Schulung ${String(b.datum).slice(8, 10)}.${String(b.datum).slice(5, 7)}.)`);
  await sendenGewaehlt("club_nachricht", ziel, ["push"], { titel: `📨 4-Wochen-Nachfrage fällig: ${f.length === 1 ? f[0].mitglied : f.length + " Mitglieder"}`,
    kurz: "In der App unter 🎓 Schulungen: Text ansehen und mit einem Tipp senden", betreff: "Köcheclub-App: Nachfrage nach der Schulung fällig",
    text: `Hallo,\n\nfür diese Schulungen sind 4 Wochen um:\n${namen.map((n) => "• " + n).join("\n")}\n\nIn der App unter 🎓 Schulungen liegt der fertige Text – ansehen, ändern und mit einem Tipp senden.`,
    url: APP_URL + "#schulungen" }, `club-nachfrage:${berlinTag(new Date())}:${f.map((b: any) => b.besuch_id).join(",")}`);
  await db.from("kc_besuche").update({ nachfrage_erinnert_am: jetzt() }).in("besuch_id", f.map((b: any) => b.besuch_id));
  await protokoll(null, "schulung_nachfrage_erinnert", { besuche: f.map((b: any) => b.besuch_id) });
}
const aufzaehlenUnd = (t: string[]) => (t.length > 1 ? t.slice(0, -1).join(", ") + " und " + t[t.length - 1] : (t[0] ?? ""));
function besuchPunkte(b: any) {
  const pk: { titel: string; wert: string }[] = [];
  for (const [f, [titel, werte]] of Object.entries(BESUCH_TEXTE)) {
    if (!b[f]) continue;
    let wert = werte[b[f]] ?? b[f];
    if (f === "f2_bild_spruch" && b[f] === "ja" && b.f2_spruch) wert += ` – Spruch: „${b.f2_spruch}“`;
    pk.push({ titel, wert });
  }
  if (b.f7_thema) pk.push({ titel: b.f7_thema, wert: b.f7_antwort || "" });
  return pk;
}
const besuchDatum = (d: string) => d.split("-").reverse().join(".");
async function besuchLeute(b: any) {
  if (!b.person_ids?.length) return [];
  const { data } = await db.from("kc_core_people").select("person_id,preferred_name,given_name,display_name,email").in("person_id", b.person_ids);
  const { data: anr } = await db.from("kc_besuche_anrede").select("person_id,anrede").in("person_id", b.person_ids);
  const an = new Map((anr ?? []).map((a: any) => [a.person_id, a.anrede]));
  return (data ?? []).map((m: any) => ({ person_id: m.person_id, vorname: m.preferred_name || m.given_name || m.display_name, mail: !!m.email, anrede: an.get(m.person_id) || null }));
}
// Dankes-Text (gleiche Worte wie bisher): ein/mehrere Mitglieder, bei ihnen/bei Hansi, Thema, Installation
function besuchMail(b: any, leute: { person_id: string; vorname: string; anrede: string | null }[]) {
  const mehr = leute.length > 1;
  const w = mehr ? { du: "ihr", dir: "euch", dich: "euch", dein: "eurem", hast: "habt", bist: "seid", scheue: "scheut euch" }
    : { du: "du", dir: "dir", dich: "dich", dein: "deinem", hast: "hast", bist: "bist", scheue: "scheue dich" };
  const anrede = leute.length && leute.every((l) => l.anrede)
    ? leute.map((l, i) => (i === 0 ? l.anrede! : l.anrede!.toLowerCase()) + " " + l.vorname).join(", ") + ","
    : `Hallo ${aufzaehlenUnd(leute.map((l) => l.vorname)) || "zusammen"},`;
  const thema = String(b.schulung_thema || "").trim();
  const abs = [`ich danke ${w.dir}, dass ${w.du} ${b.besuchsart === "bei_hansi" ? `zu mir gekommen ${w.bist}` : `mich empfangen ${w.hast}`}. Es war eine angenehme Atmosphäre und mir hat es Spaß gemacht, ${w.dich} in ${thema || "unsere Programme"} einzuführen. Ich hoffe, ${w.dir} hat es auch gefallen. Vielen Dank für ${mehr ? "eure" : "deine"} Zeit und ${mehr ? "euer" : "dein"} tolles Mitmachen!`]; // 2.308.1 (Wunsch Hansi)
  const pk = besuchPunkte(b);
  if (pk.length || b.vereinbarungen) abs.push("Im Anschluss haben wir noch ein paar Punkte besprochen. Deren Auswertung steht weiter unten.");
  const geraete = (b.installiert_auf ?? []).map((g: string) => BESUCH_GERAETE[g]).filter(Boolean);
  abs.push((geraete.length ? `Ich konnte die Schulungsversion auf ${w.dein} ${aufzaehlenUnd(geraete)} installieren. ` : "") + `Wenn etwas nicht klappt, ${w.scheue} nicht, mich zu kontaktieren. Gerne stehe ich ${w.dir} bei Fragen zur Verfügung.`);
  const text = [anrede, "", ...abs.flatMap((a) => [a, ""]), ...(pk.length ? ["Besprochen:", ...pk.map((p) => `• ${p.titel}: ${p.wert}`), ""] : []),
    ...(b.vereinbarungen ? ["Vereinbart / nächste Schritte:", b.vereinbarungen, ""] : []), "Viele Grüße", "Hansi", "Köcheclub Werne"].join("\n");
  return { betreff: `Köcheclub Werne – Danke für das Treffen am ${besuchDatum(b.datum)}`, text, kurz: pk.slice(0, 4).map((p) => `${p.titel}: ${p.wert}`).join(" · ") };
}
// Versand + Ablage; Zeitstempel nur bei Erfolg (sonst beim nächsten Speichern erneut)
async function besuchVersand(ich: Ich, b: any) {
  const leute = await besuchLeute(b), m = besuchMail(b, leute), erg: string[] = [];
  if (!leute.length) return erg;
  const ids = leute.map((l) => l.person_id), korr = `club-besuch:${b.besuch_id}`;
  const upd: Record<string, unknown> = {};
  if (!b.push_gesendet_am) {
    const r = await routerSenden("club_nachricht_push", ids, { titel: "Köcheclub Werne – Zusammenfassung Schulung", kurz: `Danke für das Treffen am ${besuchDatum(b.datum)}!${m.kurz ? " " + m.kurz : ""}`.slice(0, 180), url: APP_URL }, korr + ":push");
    erg.push(r.gesendet ? `Push an ${r.gesendet}` : "kein Push"); if (!r.fehler) upd.push_gesendet_am = jetzt();
  }
  if (!b.mail_gesendet_am) {
    const mitMail = leute.filter((l) => l.mail);
    if (!mitMail.length) { upd.mail_gesendet_am = jetzt(); upd.mail_empfaenger = "(keine E-Mail-Adresse)"; erg.push("keine E-Mail-Adresse"); }
    else {
      const r = await routerSenden("club_nachricht_mail", mitMail.map((l) => l.person_id), { titel: "Köcheclub Werne", kurz: m.betreff, betreff: m.betreff, text: m.text }, korr + ":mail",
        ich.person_id && !mitMail.some((l) => l.person_id === ich.person_id) ? { bcc: [ich.person_id] } : undefined);
      erg.push(r.gesendet ? `Mail an ${mitMail.map((l) => l.vorname).join(", ")} (BCC an dich)` : "Mail-Fehler");
      if (r.gesendet) { upd.mail_gesendet_am = jetzt(); upd.mail_empfaenger = `${mitMail.length} Mitglied(er)`; }
    }
  }
  // Kopie in den Archiv-Ordner jedes Mitglieds (Register „Schulung“) – nur einmal je Besuch
  const jahr = Number(String(b.datum).slice(0, 4)) || new Date().getFullYear();
  for (const l of leute) {
    try {
      const o = await persoenlicherOrdner(l.person_id, l.vorname, jahr, BESUCH_REGISTER); if (!o) continue;
      const titel = `Schulung am ${besuchDatum(b.datum)} (${b.besuch_id})`;
      const { data: da } = await db.from("kc_club_archiv_dokumente").select("id").eq("ordner_id", o).eq("titel", titel).is("geloescht_am", null).maybeSingle();
      if (!da) await archivTextAblegen(ich, o, BESUCH_REGISTER, titel, `Schulung-${b.datum}-${b.besuch_id}.txt`, m.text, "Schulung, Besuch, Zusammenfassung");
    } catch (e) { console.error("besuch ablage", String(e)); }
  }
  upd.versand_fehler = erg.join("; ") || null;
  await db.from("kc_besuche").update(upd).eq("besuch_id", b.besuch_id);
  return erg;
}

// ---------- Handy-Kalender (KC-CLUB-KALENDERABO) ----------
// Persönlicher, geheimer Abo-Link (nur Hash gespeichert). Enthält Treffen/Veranstaltungen, Aktionen und freigegebene Geburtstage.
const icsText = (s: unknown) => String(s ?? "").replace(/\\/g, "\\\\").replace(/;/g, "\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
const icsZeit = (iso: string) => new Date(iso).toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
const icsTag = (d: string) => d.replace(/-/g, "");
const tagDanach = (d: string) => new Date(new Date(d + "T12:00:00Z").getTime() + 86400000).toISOString().slice(0, 10);
function icsFalten(zeile: string) {
  // Zeilen über 75 Zeichen umbrechen (RFC 5545)
  const teile: string[] = []; let rest = zeile;
  while (rest.length > 74) { teile.push(rest.slice(0, 74)); rest = " " + rest.slice(74); }
  teile.push(rest); return teile.join("\r\n");
}
async function kalenderIcs(token: string) {
  const { data: abo } = await db.from("kc_club_kalender_abo").select("person_id").eq("token_hash", await sha256(token)).maybeSingle();
  if (!abo) return new Response("Kalender-Link ungültig – bitte in der App neu erzeugen.", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
  const { data: pe } = await db.from("kc_core_people").select("person_id,display_name,given_name,preferred_name,active").eq("person_id", abo.person_id).maybeSingle();
  if (!pe?.active) return new Response("Kein Zugang.", { status: 403 });
  // 2.425.0 KC-CLUB-GENERALCHECK: entzogener Zugang (Link gesperrt) oder Sperre gilt auch für das Kalender-Abo
  const [{ data: zg }, sp] = await Promise.all([db.from("kc_club_zugang").select("aktiv").eq("person_id", abo.person_id).maybeSingle(), sperreFuer(abo.person_id)]);
  if (!zg?.aktiv || sp) return new Response("Kein Zugang.", { status: 403 });
  db.from("kc_club_kalender_abo").update({ zuletzt_abgerufen: jetzt() }).eq("person_id", abo.person_id).then(() => {});
  const ich = { person_id: pe.person_id, name: pe.display_name, vorname: vorname(pe), admin: false, vorstand: false, aemter: [], protokolle: false, kontakte: false, buero: null, zugang: "mitglied" } as Ich; // KC-CLUB-RC-PRUEFUNG (20.10.2026): zugang ergänzt (nur Geburtstage, kein Recht daran geknüpft)
  const [{ data: tr }, akt, geb] = await Promise.all([
    db.from("kc_club_treffen").select("*").gte("beginn", new Date(Date.now() - 60 * 86400000).toISOString()).lte("beginn", new Date(Date.now() + 500 * 86400000).toISOString()).order("beginn"),
    aktionenRoh(), geburtstageSichtbar(ich),
  ]);
  const stamp = icsZeit(jetzt()), z: string[] = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Koecheclub Werne//Club-App//DE", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
    "X-WR-CALNAME:Köcheclub Werne", "X-WR-TIMEZONE:Europe/Berlin", "REFRESH-INTERVAL;VALUE=DURATION:PT6H", "X-PUBLISHED-TTL:PT6H"];
  for (const t of tr ?? []) {
    const ort = t.ort || "";
    z.push("BEGIN:VEVENT", `UID:treffen-${t.id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SUMMARY:${icsText((t.art === "veranstaltung" ? "🎪 " : "🍳 ") + t.titel)}`);
    if (t.ganztaegig) z.push(`DTSTART;VALUE=DATE:${icsTag(berlinTag(new Date(t.beginn)))}`, `DTEND;VALUE=DATE:${icsTag(tagDanach(berlinTag(new Date(t.ende || t.beginn))))}`);
    else z.push(`DTSTART:${icsZeit(t.beginn)}`, `DTEND:${icsZeit(t.ende || new Date(new Date(t.beginn).getTime() + 3 * 3600000).toISOString())}`);
    if (ort) z.push(`LOCATION:${icsText(ort)}`);
    z.push(`DESCRIPTION:${icsText((t.beschreibung ? t.beschreibung + "\n\n" : "") + APP_URL + "#termine")}`, `STATUS:${t.status === "abgesagt" ? "CANCELLED" : "CONFIRMED"}`, "END:VEVENT");
  }
  for (const a of akt.liste as any[]) {
    z.push("BEGIN:VEVENT", `UID:aktion-${icsText(a.id)}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SUMMARY:${icsText("🧳 " + txt(a.activity, 200))}`,
      `DTSTART;VALUE=DATE:${icsTag(a.dateFrom)}`, `DTEND;VALUE=DATE:${icsTag(tagDanach(a.dateTo || a.dateFrom))}`, `DESCRIPTION:${icsText(APP_URL + "#aktion=" + a.id)}`, "END:VEVENT");
  }
  // KC-CLUB-TERMINANFRAGE (0.92.0): eigene Anfragen und die, denen ich zugesagt habe (Ja/Vielleicht)
  for (const x of await terminanfragenListe(ich, { von: new Date(Date.now() - 60 * 86400000).toISOString(), bis: new Date(Date.now() + 500 * 86400000).toISOString() })) {
    if (!x.vonMir && x.meine !== "ja" && x.meine !== "vielleicht") continue;
    // 2.23.58 KC-CLUB-ANFRAGE-KALENDER: verlegte Anfragen ersetzen den alten Eintrag (gleiche UID); Vorbehalt = „vorläufig“
    z.push("BEGIN:VEVENT", `UID:anfrage-${x.id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SEQUENCE:${Math.floor(new Date(x.beginn).getTime() / 60000) % 100000000}`,
      `SUMMARY:${icsText("📨 " + x.anlass + (x.vonMir ? "" : " (" + x.von.vorname + ")") + (x.vorbehalt ? " – unter Vorbehalt" : ""))}`,
      `DTSTART:${icsZeit(x.beginn)}`, `DTEND:${icsZeit(x.ende || new Date(new Date(x.beginn).getTime() + 3600000).toISOString())}`);
    if (x.ort) z.push(`LOCATION:${icsText(x.ort)}`);
    z.push(`DESCRIPTION:${icsText((x.notiz ? x.notiz + "\n\n" : "") + APP_URL + "#termine")}`, `STATUS:${x.status === "abgesagt" ? "CANCELLED" : x.meine === "vielleicht" || x.vorbehalt ? "TENTATIVE" : "CONFIRMED"}`, "END:VEVENT");
  }
  // KC-CLUB-SCHULUNGSTERMINE (2.23.59): Schulungs-/Besuchstermine (Admin alle, Mitglieder ihre eigenen) – Verlegen/Absagen kommt von selbst
  const { data: rolleAbo } = await db.from("kc_club_rollen").select("ist_admin").eq("person_id", ich.person_id).maybeSingle(); // nur für die Schulungstermine
  for (const x of await schulungenListe({ ...ich, admin: !!rolleAbo?.ist_admin }, new Date(Date.now() - 60 * 86400000).toISOString(), new Date(Date.now() + 500 * 86400000).toISOString()).catch(() => [])) {
    z.push("BEGIN:VEVENT", `UID:schulung-${x.id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SEQUENCE:${Math.floor(new Date(x.beginn).getTime() / 60000) % 100000000}`,
      `SUMMARY:${icsText("🎓 Schulung: " + x.namen.join(", ") + (x.art ? " (" + x.art + ")" : ""))}`, `DTSTART:${icsZeit(x.beginn)}`, `DTEND:${icsZeit(x.ende)}`,
      `STATUS:${x.status === "bestaetigt" ? "CONFIRMED" : x.status === "abgesagt" ? "CANCELLED" : "TENTATIVE"}`, "END:VEVENT");
  }
  // KC-CLUB-PRIVATTERMIN (1.0.0): eigene private Einträge im eigenen Abo
  const { data: pReihen } = await db.from("kc_club_privattermine").select("*").eq("person_id", ich.person_id).neq("wiederholung", "keine").limit(200);
  const lokal = (iso: string) => { const t = berlinTeile(new Date(iso)); return `${t.y}${String(t.m).padStart(2, "0")}${String(t.d).padStart(2, "0")}T${String(t.h).padStart(2, "0")}${String(t.mi).padStart(2, "0")}00`; };
  for (const r of pReihen ?? []) {
    const t0 = berlinTeile(new Date(r.beginn)), wt = ["SU", "MO", "TU", "WE", "TH", "FR", "SA"][new Date(Date.UTC(t0.y, t0.m - 1, t0.d)).getUTCDay()];
    const nth = t0.d + 7 > new Date(Date.UTC(t0.y, t0.m, 0)).getUTCDate() ? -1 : Math.ceil(t0.d / 7);
    const rr = { taeglich: "FREQ=DAILY", werktags: "FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR", woechentlich: "FREQ=WEEKLY", zweiwoechentlich: "FREQ=WEEKLY;INTERVAL=2",
      monatlich: "FREQ=MONTHLY", monatlich_wochentag: `FREQ=MONTHLY;BYDAY=${nth}${wt}`, jaehrlich: "FREQ=YEARLY" }[r.wiederholung as string];
    if (!rr) continue;
    z.push("BEGIN:VEVENT", `UID:privat-${r.id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SUMMARY:${icsText("🔒 " + r.titel)}`, "CLASS:PRIVATE");
    if (r.ganztaegig) z.push(`DTSTART;VALUE=DATE:${icsTag(berlinTag(new Date(r.beginn)))}`, `DTEND;VALUE=DATE:${icsTag(tagDanach(berlinTag(new Date(r.beginn))))}`);
    else z.push(`DTSTART;TZID=Europe/Berlin:${lokal(r.beginn)}`, `DTEND;TZID=Europe/Berlin:${lokal(r.ende || new Date(new Date(r.beginn).getTime() + 3600000).toISOString())}`);
    z.push(`RRULE:${rr}${r.wiederholung_bis ? ";UNTIL=" + String(r.wiederholung_bis).replace(/-/g, "") + "T225959Z" : ""}`);
    for (const a of r.ausnahmen || []) z.push(r.ganztaegig ? `EXDATE;VALUE=DATE:${String(a).replace(/-/g, "")}` : `EXDATE;TZID=Europe/Berlin:${String(a).replace(/-/g, "")}T${lokal(r.beginn).slice(9)}`);
    if (r.ort) z.push(`LOCATION:${icsText(r.ort)}`);
    if (r.notiz) z.push(`DESCRIPTION:${icsText(r.notiz)}`);
    z.push("END:VEVENT");
  }
  for (const x of (await privatListe(ich, new Date(Date.now() - 60 * 86400000).toISOString(), new Date(Date.now() + 500 * 86400000).toISOString())).filter((x: any) => !x.serienBeginn)) {
    z.push("BEGIN:VEVENT", `UID:privat-${x.id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SUMMARY:${icsText("🔒 " + x.titel)}`, "CLASS:PRIVATE");
    if (x.ganztaegig) z.push(`DTSTART;VALUE=DATE:${icsTag(berlinTag(new Date(x.beginn)))}`, `DTEND;VALUE=DATE:${icsTag(tagDanach(berlinTag(new Date(x.ende || x.beginn))))}`);
    else z.push(`DTSTART:${icsZeit(x.beginn)}`, `DTEND:${icsZeit(x.ende || new Date(new Date(x.beginn).getTime() + 3600000).toISOString())}`);
    if (x.ort) z.push(`LOCATION:${icsText(x.ort)}`);
    if (x.notiz) z.push(`DESCRIPTION:${icsText(x.notiz)}`);
    z.push("END:VEVENT");
  }
  const jahr = Number(berlinTag(new Date()).slice(0, 4));
  for (const g of geb) {
    if (g.person_id === ich.person_id) continue;
    const d = `${jahr}-${g.md}`;
    if (g.md === "02-29") continue; // Schalttag: im Abo ausgelassen (App zeigt ihn am 28.02.)
    z.push("BEGIN:VEVENT", `UID:geburtstag-${g.person_id}@koecheclub-werne`, `DTSTAMP:${stamp}`, `SUMMARY:${icsText("🎂 " + g.name)}`,
      `DTSTART;VALUE=DATE:${icsTag(d)}`, `DTEND;VALUE=DATE:${icsTag(tagDanach(d))}`, "RRULE:FREQ=YEARLY", "TRANSP:TRANSPARENT", "END:VEVENT");
  }
  z.push("END:VCALENDAR");
  return new Response(z.map(icsFalten).join("\r\n") + "\r\n", { headers: { ...cors, "Content-Type": "text/calendar; charset=utf-8", "Cache-Control": "no-store", "Content-Disposition": 'inline; filename="koecheclub.ics"' } });
}

// ---------- Nachrichten ----------
// KC-CLUB-CHAT-STAND (2.510.0, Chat sparsamer Schritt 3): Fingerabdruck eines Chats für die Person in EINER Abfrage (Migration
// 20261020_kc_club_chat_stand.sql). null = nicht im Chat, undefined = gerade nicht berechenbar (dann lädt die App einfach den ganzen Chat).
async function chatStand(threadId: string, person: string): Promise<string | null | undefined> {
  if (!/^[0-9a-f-]{36}$/i.test(threadId)) return null;
  const r: any = await Promise.resolve(db.rpc("kc_club_chat_stand", { p_thread: threadId, p_person: person, p_jetzt: jetzt(), p_online_sek: ONLINE_SEK,
    p_zuletzt_tage: ZULETZT_TAGE, p_einmal_tage: EINMAL_TAGE, p_bearbeiten_min: BEARBEITEN_MIN })).catch((e: unknown) => ({ data: undefined, error: e }));
  if (r.error) { console.error("chat stand", String(r.error?.message ?? r.error)); return undefined; }
  return typeof r.data === "string" ? r.data : null;
}
// 2.578.0 KC-CLUB-CHAT-PAKET (Fund Hansi „das Laden der Daten in einem Chat dauert, bis die Nachrichten erscheinen“, Wahl Hansi „schön vorsichtig,
// damit alles lauffähig bleibt“): beim Öffnen eines Chats die Rohdaten in EINEM Datenbank-Aufruf (kc_club_unterhaltung_paket) statt ~28 nacheinander.
// Jeder Teil ist genau die bisherige Abfrage; gerechnet wird wie bisher. Klappt der Aufruf nicht oder ist der Not-Aus gesetzt
// (kc_club_konfig 'chat_paket' = {"aus": true}), nimmt jede Stelle von selbst den bisherigen Weg. Jeder CHAT_PAKET_VERGLEICH-te Aufruf vergleicht
// nebenbei alt ↔ neu und schreibt Abweichungen ins Protokoll (chat_paket_abweichung).
const CHAT_PAKET_VERGLEICH = 10;
async function chatPaket(threadId: string, person: string): Promise<any | null> {
  if (!/^[0-9a-f-]{36}$/i.test(threadId)) return null;
  try {
    const k: any = await konfigZeile("chat_paket").catch(() => ({ data: null }));
    if (k?.data?.wert?.aus) return null;
    const r: any = await Promise.resolve(db.rpc("kc_club_unterhaltung_paket", { p_thread: threadId, p_person: person, p_jetzt: jetzt(), p_online_sek: ONLINE_SEK,
      p_zuletzt_tage: ZULETZT_TAGE, p_einmal_tage: EINMAL_TAGE, p_bearbeiten_min: BEARBEITEN_MIN }));
    const d = r?.data;
    return !r?.error && d && typeof d === "object" && Array.isArray(d.msgs) && Array.isArray(d.tn) ? d : null;
  } catch { return null; }
}
async function chatPaketVergleich(threadId: string, person: string, pk: any) { // nebenbei: bisherige Einzelabfragen gegen das Paket (ohne „tippen“/Lesestand – ändern sich laufend)
  const [{ data: t }, { data: msgsRoh }] = await Promise.all([
    db.from("kc_communication_threads").select("id,subject,created_by_person_id").eq("id", threadId).single(),
    db.from("kc_communication_messages").select("id,sender_person_id,body,created_at,reply_to_message_id").eq("thread_id", threadId).order("created_at").limit(500),
  ]);
  const alleIds = (msgsRoh ?? []).map((m: any) => m.id), leer = { data: [] as any[] };
  const [{ data: weg }, { data: ablauf }] = alleIds.length ? await Promise.all([
    db.from("kc_communication_message_hidden").select("message_id").eq("person_id", person).in("message_id", alleIds),
    db.from("kc_club_nachricht_ablauf").select("message_id,loescht_am").in("message_id", alleIds),
  ]) : [leer, leer];
  const wegIds = new Set([...(weg ?? []).map((x: any) => x.message_id), ...(ablauf ?? []).filter((x: any) => Date.parse(String(x.loescht_am)) <= Date.now()).map((x: any) => x.message_id)]);
  const mids = alleIds.filter((x: string) => !wegIds.has(x));
  const [{ data: ma }, { data: rk }, { data: ew }, { data: bearb }, { data: umf }, { data: stim }, { data: wicht }, { data: lvs }, { data: ex }] = mids.length ? await Promise.all([
    db.from("kc_communication_message_attachments").select("message_id,attachment_id").in("message_id", mids),
    db.from("kc_club_reaktionen").select("message_id,person_id,emoji").in("message_id", mids),
    db.from("kc_club_erwaehnungen").select("message_id,person_id").in("message_id", mids),
    db.from("kc_club_nachricht_bearbeitet").select("message_id,bearbeitet_am").in("message_id", mids),
    db.from("kc_club_chat_umfrage").select("message_id,frage,optionen,mehrfach").in("message_id", mids),
    db.from("kc_club_chat_stimme").select("message_id,person_id,option").in("message_id", mids),
    db.from("kc_club_nachricht_wichtig").select("message_id").in("message_id", mids),
    db.from("kc_club_link_vorschau").select("message_id,url,titel,text,bild,seite").in("message_id", mids),
    db.from("kc_club_express").select("message_id").in("message_id", mids),
  ]) : [leer, leer, leer, leer, leer, leer, leer, leer, leer];
  const aids = (ma ?? []).map((x: any) => x.attachment_id);
  const { data: att } = aids.length ? await db.from("kc_communication_attachments").select("id,file_name,mime_type,size_bytes").in("id", aids) : leer;
  const abw: string[] = [], pr = (k: string, alt: any, neu: any) => { if (!spGleich(alt, neu)) abw.push(k); };
  pr("t", t, pk.t); pr("msgs", msgsRoh, pk.msgs); pr("weg", (weg ?? []).map((x: any) => x.message_id), pk.weg); pr("ablauf", ablauf, pk.ablauf); pr("ma", ma, pk.ma); pr("att", att, pk.att);
  pr("rk", rk, pk.rk); pr("ew", ew, pk.ew); pr("bearb", bearb, pk.bearb); pr("umf", umf, pk.umf); pr("stim", stim, pk.stim); pr("wicht", wicht, pk.wicht); pr("lvs", lvs, pk.lvs);
  pr("ex", (ex ?? []).map((x: any) => x.message_id), pk.ex);
  if (abw.length) await protokoll(person, "chat_paket_abweichung", { thread: threadId, teile: abw });
}
async function binTeilnehmer(threadId: string, person: string) {
  const { data } = await db.from("kc_communication_thread_participants").select("thread_id").eq("thread_id", threadId).eq("person_id", person).maybeSingle();
  if (!data) throw new Fehler("Unterhaltung nicht gefunden.", 404);
}
// KC-CLUB-ZENTRALE (0.44.0): Wer darf wen erreichen? Beschluss Admin 29.09.2026: alle Mitglieder dürfen alle anschreiben,
// anrufen und anklopfen (vorher „Alle“ nur Clubleitung). Umschaltbar an dieser einen Stelle.
const KOMMUNIKATION = { alleDarfJeder: true };
// KC-CLUB-NOTFALL-MELDUNG (2.21.0, Wunsch Hansi): Alarmstufe Rot – eine Unterhaltung „🚨 Notfall-Meldungen“ mit allen aktiven Mitgliedern.
// Erkennungszeichen im Text (nur der Admin darf es setzen; bei anderen wird es entfernt).
const NOTFALL_MARKE = "🚨 NOTFALL:", NOTFALL_RE = /^\s*🚨\s*NOTFALL\s*:?\s*/i, NOTFALL_BETREFF = "🚨 Notfall-Meldungen";
async function notfallUnterhaltung(ich: Ich): Promise<string> {
  const { data: alt } = await db.from("kc_communication_threads").select("id").eq("org_id", ORG).eq("subject", NOTFALL_BETREFF).order("created_at").limit(1).maybeSingle();
  let id = alt?.id as string | undefined;
  if (!id) {
    const { data: th, error } = await db.from("kc_communication_threads").insert({ org_id: ORG, subject: NOTFALL_BETREFF, created_by_person_id: ich.person_id }).select("id").single();
    if (error || !th) throw new Fehler("Notfall-Unterhaltung konnte nicht angelegt werden.", 500);
    id = th.id as string;
  }
  // alle aktiven Mitglieder (auch neue) sind dabei
  const alle = [ich.person_id, ...(await aktiveMitglieder()).map((m) => m.person_id)];
  const { data: tn } = await db.from("kc_communication_thread_participants").select("person_id").eq("thread_id", id);
  const da = new Set((tn ?? []).map((x: any) => x.person_id));
  const fehlt = [...new Set(alle)].filter((x) => !da.has(x));
  if (fehlt.length) await db.from("kc_communication_thread_participants").insert(fehlt.map((person_id) => ({ thread_id: id, person_id })));
  return id;
}
async function empfaengerAufloesen(ich: Ich, e: any): Promise<string[]> {
  const ids = new Set<string>((Array.isArray(e?.personen) ? e.personen : []).map(String));
  if (e?.alle) { if (!KOMMUNIKATION.alleDarfJeder) nurVorstand(ich); (await sammelEmpfaenger()).forEach((p) => ids.add(p.person_id)); }
  const aemter = (Array.isArray(e?.aemter) ? e.aemter : []).map(String);
  if (aemter.length) {
    const { data } = await db.from("kc_club_rollen").select("person_id,aemter").overlaps("aemter", aemter);
    (data ?? []).forEach((r: any) => ids.add(r.person_id));
  }
  if (e?.vorstand) { const { data } = await db.from("kc_club_rollen").select("person_id").eq("ist_vorstand", true); (data ?? []).forEach((r: any) => ids.add(r.person_id)); }
  ids.delete(ich.person_id);
  const aktiv = new Set((await aktiveMitglieder()).map((p) => p.person_id));
  return [...ids].filter((id) => aktiv.has(id));
}


// ---------- KC-CLUB-TERMINANFRAGE (0.92.0) ----------
// Jedes Mitglied fragt Einzelne, mehrere oder eine Gruppe persönlich an (Anlass, Datum/Uhrzeit, Ort) – Antwort ja / vielleicht / nein.
// Eigene Tabellen (nicht kc_club_treffen): eine private Anfrage darf nie in Liste, Kalender-Abo oder „Demnächst“ aller landen.
// Sichtbar nur für Absender und Empfänger; die Antworten sehen alle Beteiligten (wie bei Treffen).
const ANFRAGE_MAX_EMPFAENGER = 100, ANFRAGE_MAX_JE_TAG = 30;
// Empfänger: einzelne Personen und/oder eine Gruppe (= Teilnehmer der Gruppen-Unterhaltung) – ohne mich, nur aktive Mitglieder
async function zielPersonen(ich: Ich, an: any): Promise<string[]> {
  const ids = new Set<string>((Array.isArray(an?.personen) ? an.personen : []).map(String).slice(0, 300));
  const gruppe = String(an?.gruppe || "");
  if (gruppe) {
    await binTeilnehmer(gruppe, ich.person_id);
    const { data: g } = await db.from("kc_club_gruppen").select("thread_id").eq("thread_id", gruppe).maybeSingle();
    if (!g) throw new Fehler("Gruppe nicht gefunden.", 404);
    const { data: tn } = await db.from("kc_communication_thread_participants").select("person_id").eq("thread_id", gruppe);
    (tn ?? []).forEach((x: any) => ids.add(String(x.person_id)));
  }
  ids.delete(ich.person_id);
  const aktiv = new Set((await aktiveMitglieder()).map((x) => x.person_id));
  return [...ids].filter((id) => aktiv.has(id));
}
// Terminanfrage absagen – eine Stelle für „🚫 Absagen“ und für Spiel-Termine, deren Herausforderung endet, bevor gespielt wurde
// (KC-CLUB-SPIEL-TERMIN-ABSAGE 2.23.29). Benachrichtigt werden alle Beteiligten außer mir (Empfänger ohne „nein“, ggf. wer angefragt hat).
async function anfrageAbsagen(ich: Ich, a: any, grund: string, benachrichtigen: boolean) {
  const { data: weg } = await db.from("kc_club_terminanfragen").update({ status: "abgesagt", geaendert_am: jetzt() }).eq("id", a.id).eq("status", "offen").select("id");
  if (!weg?.length) return null; // schon abgesagt
  const { data: e } = await db.from("kc_club_terminanfrage_empfaenger").select("person_id,antwort").eq("anfrage_id", a.id);
  const ziel = [...new Set([...(e ?? []).filter((x: any) => x.antwort !== "nein").map((x: any) => x.person_id), a.erstellt_von])].filter((id) => id !== ich.person_id) as string[];
  const versand = benachrichtigen && ziel.length ? await senden("club_treffen", ziel, {
    titel: `🚫 Abgesagt: ${a.anlass}`, kurz: `${ich.vorname} hat die Anfrage für ${wann(a.beginn)} abgesagt${grund ? " – " + grund : ""}`,
    betreff: `Köcheclub Werne – abgesagt: ${a.anlass} (${wann(a.beginn)})`,
    text: `Hallo,\n\n${ich.name} hat die Terminanfrage abgesagt:\n\n📌 ${a.anlass}\n📅 ${anfrageWann(a)}${grund ? "\n📝 " + grund : ""}\n\nViele Grüße\nKöcheclub Werne`,
    url: APP_URL + "#termine",
  }, `club-terminanfrage-absage:${a.id}`) : null;
  await protokoll(ich.person_id, "terminanfrage_abgesagt", { anfrage: a.id, versand, ...(a.spiel_id ? { spiel: a.spiel_id } : {}) });
  return versand;
}
async function spielTerminAbsagen(ich: Ich, spielId: string, grund: string, benachrichtigen: boolean) {
  const { data: offen } = await db.from("kc_club_terminanfragen").select("*").eq("spiel_id", spielId).eq("status", "offen");
  for (const a of offen ?? []) await anfrageAbsagen(ich, a, grund, benachrichtigen);
}
async function terminanfragenListe(ich: Ich, zeitraum?: { von: string; bis: string }) {
  const von = zeitraum?.von ?? new Date(Date.now() - 14 * 86400000).toISOString();
  const { data: empf } = await db.from("kc_club_terminanfrage_empfaenger").select("anfrage_id").eq("person_id", ich.person_id);
  const empfIds = [...new Set((empf ?? []).map((x: any) => String(x.anfrage_id)))];
  const basis = () => { let q = db.from("kc_club_terminanfragen").select("*").gte("beginn", von); if (zeitraum?.bis) q = q.lte("beginn", zeitraum.bis); return q; };
  const [{ data: eigene }, { data: fremde }] = await Promise.all([
    basis().eq("erstellt_von", ich.person_id),
    empfIds.length ? basis().in("id", empfIds.slice(0, 500)) : Promise.resolve({ data: [] as any[] }),
  ]);
  const alle = new Map<string, any>();
  for (const a of [...(eigene ?? []), ...(fremde ?? [])]) alle.set(a.id, a);
  const liste = [...alle.values()].sort((a, b) => String(a.beginn).localeCompare(String(b.beginn)));
  if (!liste.length) return [];
  const [{ data: zeilen }, erin] = await Promise.all([db.from("kc_club_terminanfrage_empfaenger").select("*").in("anfrage_id", liste.map((a) => a.id)),
    meineErinnerungen(ich.person_id, liste.map((a) => a.id))]); // KC-CLUB-ERINNERUNG-WAHL
  const [leute, anl] = await Promise.all([personen([...liste.map((a) => a.erstellt_von), ...(zeilen ?? []).map((z: any) => z.person_id)]), objAnlagenHolen("terminanfrage", liste.map((a) => a.id))]); // 2.448.0: + Anlagen
  const name = (id: string) => leute.get(id)?.display_name || "Mitglied";
  return liste.map((a) => {
    const e = (zeilen ?? []).filter((z: any) => z.anfrage_id === a.id);
    const mein = e.find((z: any) => z.person_id === ich.person_id);
    return {
      id: a.id, anlass: a.anlass, beginn: a.beginn, ende: a.ende, ort: a.ort, notiz: a.notiz, frist: a.frist, status: a.status, spiel: !!a.spiel_id, vorbehalt: a.vorbehalt ?? null, anlagen: anl.get(a.id) ?? [],
      vonMir: a.erstellt_von === ich.person_id, von: { person_id: a.erstellt_von, name: name(a.erstellt_von), vorname: vorname(leute.get(a.erstellt_von)) || name(a.erstellt_von) },
      meine: mein?.antwort ?? null, meineNotiz: mein?.notiz ?? null, meinGelesen: mein?.gelesen_am ?? null, // KC-CLUB-TERMINANFRAGE-STATUS (2.23.50)
      meinVorschlag: mein?.vorschlag_beginn ? { beginn: mein.vorschlag_beginn, ende: mein.vorschlag_ende } : null, erinnerung: erin.get(a.id) ?? null, erinnerungStandard: a.erinnerung_min || 0,
      empfaenger: e.map((z: any) => ({ person_id: z.person_id, name: name(z.person_id), vorname: vorname(leute.get(z.person_id)) || name(z.person_id), antwort: z.antwort, notiz: z.notiz, geantwortet_am: z.geantwortet_am,
        gelesen_am: z.gelesen_am, vorschlag: z.vorschlag_beginn ? { beginn: z.vorschlag_beginn, ende: z.vorschlag_ende } : null }))
        .sort((x: any, y: any) => x.name.localeCompare(y.name, "de")),
    };
  });
}
const ANTWORT_TEXT: Record<string, string> = { ja: "✅ Ja", vielleicht: "🤔 Vielleicht", nein: "❌ Nein" };
// KC-CLUB-ANFRAGE-ALLE-INFO (19.10.2026, Wunsch Hansi „wenn Zusagen, Absagen, andere Vorschläge kommen, müssen alle benachrichtigt werden“):
// bei Anfragen an mehrere Personen erfahren auch die übrigen Eingeladenen von Antworten und Gegenvorschlägen (ohne Anfragenden und ohne den Antwortenden selbst)
async function anfrageMitEingeladene(a: any, ohne: string): Promise<string[]> {
  const { data } = await db.from("kc_club_terminanfrage_empfaenger").select("person_id").eq("anfrage_id", a.id);
  return [...new Set((data ?? []).map((x: any) => String(x.person_id)))].filter((id) => id !== ohne && id !== a.erstellt_von);
}
// ---------- KC-CLUB-ERINNERUNG-WAHL (2.23.22, Wunsch Hansi): jede Person stellt ihre Erinnerung zu einer Terminanfrage selbst ein ----------
// wann: 15/30/60/120 Min. vorher (0 = keine), zusätzlich am Vortag; wie: Push und/oder E-Mail. Kalender mit Alarm macht die App selbst.
// Ohne eigene Zeile gilt wie bisher die Erinnerung der Anfrage (erinnerung_min) über die allgemeinen Benachrichtigungs-Einstellungen.
const ERIN_MINUTEN = [0, 15, 30, 60, 120];
async function meineErinnerungen(pid: string, ids: string[]) {
  if (!ids.length) return new Map<string, any>();
  const { data } = await db.from("kc_club_erinnerungen").select("anfrage_id,minuten,vortag,wege").eq("person_id", pid).in("anfrage_id", ids);
  return new Map<string, any>((data ?? []).map((x: any) => [x.anfrage_id, { minuten: x.minuten, vortag: x.vortag, wege: x.wege }]));
}
const erinText = (min: number) => min >= 60 ? `${Math.round(min / 60)} Std.` : `${min} Min.`;
function anfrageWann(a: any) { return wann(a.beginn, true) + (a.ende ? ` bis ${fZeit.format(new Date(a.ende))} Uhr` : ""); }

// ---------- KC-CLUB-STANDORT (0.92.0) ----------
// Live teilen: nur an Gewählte, nur für die gewählte Dauer (höchstens 8 Std.), danach löscht die Wartung die Zeile.
// Beenden löscht sofort. Einmal senden läuft ohne Tabelle als normale Nachricht mit Kartenlink.
const STANDORT_MAX_MIN = 480;
function koordinaten(p: any) {
  const lat = Number(p.lat), lon = Number(p.lon), gen = p.genauigkeit == null ? null : Number(p.genauigkeit);
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) throw new Fehler("Standort ungültig – bitte erneut versuchen.");
  return { lat: Math.round(lat * 1e6) / 1e6, lon: Math.round(lon * 1e6) / 1e6, genauigkeit: gen != null && Number.isFinite(gen) ? Math.min(Math.max(0, gen), 100000) : null };
}


// ---------- KC-CLUB-FEHLERPROTOKOLL (0.93.0) ----------
// Die App schreibt jede Kleinigkeit mit, die beim Start oder in der Bedienung schiefgeht (Skriptfehler, Serverantworten,
// Start hängt, alte Version, falscher Browser …). Einträge werden auf dem Gerät gesammelt und gebündelt geschickt –
// nach der Anmeldung mit Namen, vorher (Link fehlt/ungültig) anonym mit Geräte-Kennung. Nie Zugangsdaten oder Inhalte.
const FP_MAX_JE_SENDUNG = 25, FP_ANONYM_JE_STUNDE = 150, FP_GERAET_JE_STUNDE = 40;
function fpSauber(d: any): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  if (!d || typeof d !== "object") return out;
  for (const [k, v] of Object.entries(d).slice(0, 25)) {
    const key = txt(k, 30).replace(/[^A-Za-z0-9_]/g, "");
    if (!key || /token|key|schluessel|passwort|password/i.test(key)) continue;
    out[key] = typeof v === "number" || typeof v === "boolean" ? v : txt(typeof v === "object" ? JSON.stringify(v) : v, 400).replace(/[?&]k=[0-9a-f]{16,}/gi, "?k=…");
  }
  return out;
}
const fpArt = (x: unknown) => txt(x, 24).toLowerCase().replace(/[^a-z_]/g, "") || "allg";
// ---------- 2.550.0 KC-CLUB-FEHLVERSUCHE (Wunsch Hansi „herausfinden, wer ohne gültigen Link in unsere App will“) ----------
// Öffnet dasselbe Gerät (anonyme Geräte-Kennung der App) die App FV_SCHWELLE-mal in FV_STUNDEN Stunden ohne gültigen Link, bekommen die
// Admins einen Push mit Anzahl, Uhrzeit und grobem Gerätetyp (System/Browser, wie die App sie meldet). Je Gerät höchstens 1× am Tag,
// insgesamt höchstens FV_MAX_TAG Meldungen am Tag. Keine IP-Adresse; Roboter/Vorschau-Dienste kommen gar nicht bis hierher (FP_ROBOTER).
const FV_SCHWELLE = 3, FV_STUNDEN = 2, FV_MAX_TAG = 5;
async function fehlversucheMelden(geraet: string, e: any) {
  const seit = new Date(Date.now() - FV_STUNDEN * 3600000).toISOString(), tag = new Date(Date.now() - 86400000).toISOString();
  const [{ count: n }, { count: schon }, { count: heute }] = await Promise.all([
    db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).in("aktion", ["fehler_anonym_ohne_link", "fehler_anonym_link_ungueltig"]).eq("details->>geraet", geraet).gte("zeit", seit),
    db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "fehlversuche_gemeldet").eq("details->>geraet", geraet).gte("zeit", tag),
    db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "fehlversuche_gemeldet").gte("zeit", tag),
  ]);
  if ((n ?? 0) < FV_SCHWELLE || (schon ?? 0) > 0 || (heute ?? 0) >= FV_MAX_TAG) return;
  const geraetText = [txt(e?.system, 40), txt(e?.browser, 40)].filter(Boolean).join(", ") || "unbekanntes Gerät";
  const art = fpArt(e?.art) === "link_ungueltig" ? "mit einem ungültigen Link" : "ohne persönlichen Link";
  await protokoll(null, "fehlversuche_gemeldet", { geraet, anzahl: n, art: fpArt(e?.art), system: txt(e?.system, 40), browser: txt(e?.browser, 40) });
  const adm = await adminIds(); if (!adm.length) return;
  await routerSenden("club_nachricht_push", adm, { titel: `🔑 ${n}× versucht, die Club-App ${art} zu öffnen`,
    kurz: `${geraetText} · zuletzt ${NOT_UHR.format(new Date())} Uhr · Gerät ${geraet}`, betreff: "Köcheclub-App: wiederholte Versuche ohne gültigen Link",
    text: `Dasselbe Gerät hat in den letzten ${FV_STUNDEN} Stunden ${n}-mal versucht, die Club-App ${art} zu öffnen.\nGerät: ${geraetText}\nGeräte-Kennung: ${geraet}\nGesehen hat es nur den Anmelde-Hinweis – keine Club-Daten.\nEinzelheiten: Admin → 🩺 Fehler.`,
    url: APP_URL }, `club-fehlversuche:${geraet}:${berlinTag(new Date())}`);
}
// KC-CLUB-FEHLER-ALARM (2.48.0, Wunsch Hansi: „bekomme ich als Admin Push und E-Mail über solche Fälle?“): ernste Fälle eines
// angemeldeten Mitglieds → Admins sofort per Push + E-Mail (wie „Problem melden“, Weg club_nachricht). Nicht an den Verursacher selbst,
// keine Testpersonen. Grenzen: je Mitglied höchstens 1 Alarm in 6 Stunden, insgesamt höchstens 3 je Stunde. Jeder Alarm steht im
// Protokoll (fehler_alarm). Inhalt nur Art, Fehlertext des Programms, Bereich, Gerät und Version – nie Nachrichten oder Eingaben.
const FA_ARTEN: Record<string, string> = { skript: "Programmfehler", gefangen: "Programmfehler (abgefangen)", instabil: "Mehrere Programmfehler kurz hintereinander",
  haenger: "App hat länger gehangen", start_kaputt: "App startet nicht", versprechen: "Programmfehler im Hintergrund" };
async function fehlerAlarm(ich: Ich, liste: any[], ua: string, version: string) {
  if (/^KC-P-TEST/.test(ich.person_id)) return;
  const ernst = liste.find((e: any) => { const a = fpArt(e?.art); return a in FA_ARTEN && a !== "versprechen" && (a !== "haenger" || Number(e?.ms) >= 10000); });
  if (!ernst) return;
  const jetztMs = Date.now();
  const [{ count: jeMitglied }, { count: alle }] = await Promise.all([
    db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "fehler_alarm").eq("details->>fuer", ich.person_id).gte("zeit", new Date(jetztMs - 6 * 3600000).toISOString()),
    db.from("kc_club_protokoll").select("id", { count: "exact", head: true }).eq("aktion", "fehler_alarm").gte("zeit", new Date(jetztMs - 3600000).toISOString()),
  ]);
  if ((jeMitglied ?? 0) > 0 || (alle ?? 0) >= 3) return;
  const ziel = (await adminIds()).filter((id) => id !== ich.person_id);
  if (!ziel.length) return;
  const art = fpArt(ernst.art), was = FA_ARTEN[art], weitere = liste.length - 1;
  const geraet = /iPhone|iPad/.test(ua) ? "iPhone/iPad" : /Android/.test(ua) ? "Android" : /Windows/.test(ua) ? "Windows" : /Mac/.test(ua) ? "Mac" : "Gerät";
  const browser = /Edg\//.test(ua) ? "Edge" : /SamsungBrowser/.test(ua) ? "Samsung Internet" : /Chrome\//.test(ua) ? "Chrome" : /Firefox\//.test(ua) ? "Firefox" : /Safari\//.test(ua) ? "Safari" : "Browser";
  const fehlertext = ohneLinks(txt(ernst.text, 220)), bereich = txt(ernst.sicht, 40);
  await protokoll(null, "fehler_alarm", { fuer: ich.person_id, art, version });
  await senden("club_nachricht", ziel, {
    titel: `🩺 ${was}: ${ich.name}`, kurz: `${fehlertext || was}${bereich ? " · " + bereich : ""} · ${geraet}/${browser} · v${version || "?"}`,
    betreff: `Köcheclub-App: ${was} bei ${ich.name}`,
    text: `Hallo,\n\nbei ${ich.name} ist in der Club-App etwas schiefgelaufen.\n\nArt: ${was}\n${fehlertext ? "Fehler: " + fehlertext + "\n" : ""}${bereich ? "Bereich: " + bereich + "\n" : ""}Gerät: ${geraet} · ${browser}\nApp-Version: ${version || "?"}${weitere > 0 ? `\nWeitere Einträge in dieser Meldung: ${weitere}` : ""}\n\nDas Mitglied hat eine verständliche Meldung gesehen. Einzelheiten: Admin-Zentrale → 🩺 Fehlerprotokoll.\nWeitere Alarme zu ${ich.name} frühestens in 6 Stunden.\n${APP_URL}\n\nViele Grüße\nKöcheclub-App`,
    url: APP_URL,
  }, `club-fehler-alarm:${ich.person_id}:${Math.floor(jetztMs / 3600000)}`);
}

// ---------- KC-CLUB-WIEDERHOLUNG (1.1.0): Termine wiederholen – immer in deutscher Ortszeit (18:00 bleibt 18:00, auch nach der Zeitumstellung) ----------
const WDH = ["keine", "taeglich", "werktags", "woechentlich", "zweiwoechentlich", "monatlich", "monatlich_wochentag", "jaehrlich"];
const WDH_TEXT: Record<string, string> = { taeglich: "täglich", werktags: "werktags (Mo–Fr)", woechentlich: "wöchentlich", zweiwoechentlich: "alle 2 Wochen",
  monatlich: "monatlich", monatlich_wochentag: "monatlich am gleichen Wochentag", jaehrlich: "jährlich" };
function berlinTeile(d: Date) {
  const f = new Intl.DateTimeFormat("en-CA", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(d);
  const g = (t: string) => Number(f.find((x) => x.type === t)?.value);
  return { y: g("year"), m: g("month"), d: g("day"), h: g("hour"), mi: g("minute") };
}
function berlinZuUtc(y: number, m: number, d: number, h: number, mi: number) {
  const probe = Date.UTC(y, m - 1, d, h, mi), t = berlinTeile(new Date(probe));
  return new Date(probe - (Date.UTC(t.y, t.m - 1, t.d, t.h, t.mi) - probe));
}
// Alle Termine einer Reihe zwischen von und bis (ISO-Zeiten der Beginne), höchstens max
function wiederholungen(beginnIso: string, regel: string, von: Date, bis: Date, grenze?: string | null, ausnahmen: string[] = [], max = 400): string[] {
  const s0 = berlinTeile(new Date(beginnIso)), aus = new Set(ausnahmen.map(String)), out: string[] = [];
  const ende = grenze ? berlinZuUtc(Number(grenze.slice(0, 4)), Number(grenze.slice(5, 7)), Number(grenze.slice(8, 10)), 23, 59) : null;
  const tagZahl = (y: number, m: number) => new Date(Date.UTC(y, m, 0)).getUTCDate();
  const nterWochentag = Math.ceil(s0.d / 7), wtag = new Date(Date.UTC(s0.y, s0.m - 1, s0.d)).getUTCDay(), letzter = s0.d + 7 > tagZahl(s0.y, s0.m);
  for (let k = 0, n = 0; k < 6000 && n < max; k++) {
    let y = s0.y, m = s0.m, d = s0.d;
    if (regel === "taeglich" || regel === "werktags") { const t = new Date(Date.UTC(s0.y, s0.m - 1, s0.d + k)); y = t.getUTCFullYear(); m = t.getUTCMonth() + 1; d = t.getUTCDate();
      if (regel === "werktags" && [0, 6].includes(t.getUTCDay())) continue; }
    else if (regel === "woechentlich" || regel === "zweiwoechentlich") { const t = new Date(Date.UTC(s0.y, s0.m - 1, s0.d + k * (regel === "woechentlich" ? 7 : 14))); y = t.getUTCFullYear(); m = t.getUTCMonth() + 1; d = t.getUTCDate(); }
    else if (regel === "monatlich" || regel === "monatlich_wochentag") {
      const t = new Date(Date.UTC(s0.y, s0.m - 1 + k, 1)); y = t.getUTCFullYear(); m = t.getUTCMonth() + 1;
      if (regel === "monatlich") d = Math.min(s0.d, tagZahl(y, m));
      else { const erster = (wtag - new Date(Date.UTC(y, m - 1, 1)).getUTCDay() + 7) % 7 + 1; d = erster + 7 * (nterWochentag - 1);
        if (letzter || d > tagZahl(y, m)) { d = erster; while (d + 7 <= tagZahl(y, m)) d += 7; } }
    }
    else if (regel === "jaehrlich") { y = s0.y + k; d = Math.min(s0.d, tagZahl(y, s0.m)); }
    else { if (k > 0) break; }
    const t = berlinZuUtc(y, m, d, s0.h, s0.mi);
    if (t > bis || (ende && t > ende)) break;
    const tag = `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    if (t >= von && !aus.has(tag)) { out.push(t.toISOString()); n++; }
  }
  return out;
}

// ---------- KC-CLUB-SPAETER-SENDEN (2.362.0, Wunsch Hansi „zeitversetzt senden – bedienerfreundlich, einfach; auch Wiederholungen,
// z. B. jeden Montag um 8 Uhr die gleiche Nachricht“) ----------
// Geplant wird nur Text in einem vorhandenen Chat. Der Server sendet zur Zeit selbst (auch wenn das Handy aus ist): pg_cron schaut jede Minute
// in kc_club_geplant und ruft „geplant_faellig“ nur, wenn etwas fällig ist. Gesendet wird genau wie von Hand (nachricht_senden im Namen des
// Absenders – Push/Mail, stumm, Erwähnung, Selbstlöschen des Chats gelten wie immer). Wiederholungen rechnen ab der ersten Zeit (Berliner Uhr,
// Sommer-/Winterzeit richtig); verpasste Termine (Server-Störung) werden einmal nachgeholt, nie gestapelt.
const EXPRESS_MAX = 5, EXPRESS_SPAETER_MIN = 30; // 2.362.0 KC-CLUB-EXPRESS
// 2.391.0 KC-CLUB-EXPRESS-ZAEHLER (Wunsch Hansi „bei 5 lassen und in der Express 1/5 anzeigen“): genutzt in den letzten 24 Std.,
// bei voll: ab wann wieder frei (älteste Sendung + 24 Std.). Admin: unbegrenzt.
async function expressStand(ich: Ich) {
  if (ich.admin) return { genutzt: 0, max: EXPRESS_MAX, unbegrenzt: true, wieder: null };
  const { data } = await db.from("kc_club_express").select("erstellt_am").eq("absender", ich.person_id).gte("erstellt_am", new Date(Date.now() - 86400000).toISOString()).order("erstellt_am", { ascending: true }).limit(EXPRESS_MAX + 5);
  const l = data ?? [];
  return { genutzt: l.length, max: EXPRESS_MAX, unbegrenzt: false, wieder: l.length >= EXPRESS_MAX ? new Date(new Date(l[l.length - EXPRESS_MAX].erstellt_am).getTime() + 86400000).toISOString() : null };
}
// 2.362.0 KC-CLUB-EXPRESS: ungelesene Express-Sendungen an mich (7 Tage), ohne „Nein“ und ohne laufendes „Später“ – für das Express-Fenster beim Start
// 2.389.0 KC-CLUB-TERMINANFRAGE-SICHTBAR (Fund Hansi „Klaus hat meine Terminanfrage nicht gesehen“): persönliche Terminanfragen an mich,
// auf die ich noch nicht geantwortet habe (offen, noch nicht vorbei, Frist nicht abgelaufen) – stehen dann groß unter „Heute wichtig“
async function offeneTerminanfragen(ich: Ich) {
  const { data: em } = await db.from("kc_club_terminanfrage_empfaenger").select("anfrage_id").eq("person_id", ich.person_id).is("antwort", null).is("vorschlag_beginn", null);
  if (!(em ?? []).length) return [];
  const { data: an } = await db.from("kc_club_terminanfragen").select("id,erstellt_von,anlass,beginn,frist,spiel_id").in("id", (em ?? []).map((x: any) => x.anfrage_id))
    .eq("status", "offen").is("spiel_id", null).gt("beginn", jetzt()).order("beginn").limit(5);
  const l = (an ?? []).filter((x: any) => !x.frist || x.frist > jetzt()); if (!l.length) return [];
  const leute = await personen(l.map((x: any) => x.erstellt_von));
  return l.map((x: any) => ({ id: x.id, von: vorname(leute.get(x.erstellt_von)) || "?", anlass: txt(x.anlass, 80), beginn: x.beginn }));
}
// 2.385.0 KC-CLUB-EXPRESS-ZUSTELLUNG (Wunsch Hansi „angekommen um x Uhr und gelesen um y Uhr“): je Empfänger festhalten, wann die
// Express-Sendung in seiner App ankam und wann er den Chat mit ihr geöffnet hat (nur das ERSTE Mal zählt). Neue Einträge melden dem
// Absender sofort ein Signal („chat“), damit seine Anzeige ohne Warten nachzieht. Fehler stören nie das Laden.
async function expressZustellung(ich: Ich, liste: { message_id: string; absender: string; thread_id: string }[], gelesen: boolean) {
  const l = liste.filter((x) => x.absender !== ich.person_id); if (!l.length) return;
  const t = jetzt(), ids = l.map((x) => x.message_id);
  const { data: neu } = await db.from("kc_club_express_zustellung").upsert(ids.map((message_id) => ({ message_id, person_id: ich.person_id, angekommen_am: t, ...(gelesen ? { gelesen_am: t } : {}) })),
    { onConflict: "message_id,person_id", ignoreDuplicates: true }).select("message_id");
  const { data: gel } = gelesen ? await db.from("kc_club_express_zustellung").update({ gelesen_am: t }).eq("person_id", ich.person_id).in("message_id", ids).is("gelesen_am", null).select("message_id") : { data: [] as any[] };
  const geaendert = new Set([...(neu ?? []), ...(gel ?? [])].map((x: any) => x.message_id));
  for (const x of l.filter((y) => geaendert.has(y.message_id)))
    await db.rpc("kc_club_rt_klingeln", { p_personen: [x.absender], p_art: "chat", p_thread: x.thread_id }).then(() => {}, () => {});
}
async function expressOffen(ich: Ich, zahlen: any[]): Promise<any[]> {
  const offen = zahlen.filter((z) => z.n > 0); if (!offen.length) return [];
  const { data: ex } = await db.from("kc_club_express").select("message_id,thread_id,absender,erstellt_am").in("thread_id", offen.map((z) => z.t.thread_id))
    .neq("absender", ich.person_id).gte("erstellt_am", new Date(Date.now() - 7 * 86400000).toISOString()).order("erstellt_am").limit(20);
  const exGelesenBis = new Map(offen.map((z) => [z.t.thread_id, z.t.last_read_at]));
  const ungelesen = (ex ?? []).filter((x: any) => !exGelesenBis.get(x.thread_id) || x.erstellt_am > exGelesenBis.get(x.thread_id));
  if (!ungelesen.length) return [];
  // 2.403.0 KC-CLUB-EXPRESS-ANKUNFT-ECHT (Fund Hansi: „angekommen“ bei jemandem, der nicht in der App war): das Laden allein zählt nicht mehr –
  // „angekommen“ meldet die App erst, wenn das Express-Fenster wirklich auf dem sichtbaren Bildschirm steht (express_angezeigt),
  // sowie beim Antworten im Fenster und beim Öffnen des Chats.
  const { data: ant } = await db.from("kc_club_express_antwort").select("message_id,antwort,spaeter_bis").eq("person_id", ich.person_id).in("message_id", ungelesen.map((x: any) => x.message_id));
  const am = new Map((ant ?? []).map((a: any) => [a.message_id, a]));
  const zeigen = ungelesen.filter((x: any) => { const a: any = am.get(x.message_id); return !a || (a.antwort === "spaeter" && (!a.spaeter_bis || a.spaeter_bis <= jetzt())); });
  if (!zeigen.length) return [];
  const [vonL, { data: th }, { data: gr }] = await Promise.all([personen(zeigen.map((x: any) => x.absender)),
    db.from("kc_communication_threads").select("id,subject").in("id", zeigen.map((x: any) => x.thread_id)),
    db.from("kc_club_gruppen").select("thread_id,name,symbol").in("thread_id", zeigen.map((x: any) => x.thread_id))]);
  return zeigen.map((x: any) => { const g: any = (gr ?? []).find((y: any) => y.thread_id === x.thread_id), t: any = (th ?? []).find((y: any) => y.id === x.thread_id);
    return { id: x.message_id, thread: x.thread_id, von: vonL.get(x.absender)?.display_name || "?", zeit: x.erstellt_am, chat: g ? `${g.symbol} ${g.name}` : t?.subject || "" }; });
}
const GEPLANT_WDH = ["einmal", "taeglich", "werktags", "woechentlich", "monatlich"], GEPLANT_MAX = 25, GEPLANT_TAGE = 31;
const GEPLANT_FELDER = "id,thread_id,text,wichtig,wege,senden_um,erste_um,wiederholung,anzahl,letzter_fehler,erstellt_am,geaendert_am,vorab"; // 2.549.0: + angelegt/geändert für die ⏰-Infos · 2.551.0: + vorab
function geplantNaechstes(ersteUm: string, regel: string, nach: Date): string | null {
  if (regel === "einmal") return null;
  return wiederholungen(ersteUm, regel, new Date(nach.getTime() + 1000), new Date(nach.getTime() + 400 * 86400000), null, [], 1)[0] ?? null;
}
const geplantAus = (g: any) => ({ id: g.id, text: g.text, um: g.senden_um, wiederholung: g.wiederholung, wichtig: !!g.wichtig, anzahl: g.anzahl || 0, fehler: g.letzter_fehler || null,
  wege: Array.isArray(g.wege) ? g.wege : [], angelegt: g.erstellt_am || null, geaendert: g.geaendert_am || null, vorab: !!g.vorab }); // 2.549.0 KC-CLUB-GEPLANT-WECKER · 2.551.0 KC-CLUB-GEPLANT-VORAB
async function geplantMeine(ich: Ich, threadId: string) {
  const { data } = await db.from("kc_club_geplant").select(GEPLANT_FELDER).eq("person_id", ich.person_id).eq("thread_id", threadId).eq("status", "offen").order("senden_um").limit(GEPLANT_MAX);
  return (data ?? []).map(geplantAus);
}
// 2.551.0 KC-CLUB-GEPLANT-VORAB (Wunsch Hansi „früher abrufen erlauben – Empfänger informieren, sonst zur geplanten Zeit senden“):
// Empfänger sehen nur, DASS eine Nachricht von X für eine Zeit bereitliegt – nie den Text, bevor sie sie abrufen.
async function geplantVorabFuerMich(ich: Ich, threadId: string) {
  const { data } = await db.from("kc_club_geplant").select("id,person_id,senden_um").eq("thread_id", threadId).eq("status", "offen").eq("vorab", true)
    .eq("wiederholung", "einmal").neq("person_id", ich.person_id).order("senden_um").limit(GEPLANT_MAX);
  if (!data?.length) return [];
  const leute = await personen(data.map((x: any) => x.person_id));
  return data.map((x: any) => ({ id: x.id, von: vorname(leute.get(x.person_id)) || "?", um: x.senden_um }));
}
async function geplantVorabMelden(ich: Ich, g: { id: string; thread_id: string; senden_um: string }) {
  const { data: tn } = await db.from("kc_communication_thread_participants").select("person_id").eq("thread_id", g.thread_id);
  const an = (tn ?? []).map((x: any) => x.person_id).filter((x: string) => x !== ich.person_id);
  if (!an.length) return;
  const wann = `${fTag.format(new Date(g.senden_um))}, ${fZeit.format(new Date(g.senden_um))} Uhr`;
  await sendenGewaehlt("club_nachricht", an, ["push"], { titel: `⏰ Nachricht von ${ich.vorname} wartet`, kurz: `${ich.vorname} hat dir eine Nachricht für ${wann} geplant – du darfst sie schon jetzt abrufen`,
    betreff: "Köcheclub Werne – zeitgesteuerte Nachricht", text: `${ich.name} hat dir eine zeitgesteuerte Nachricht für ${wann} geplant. Du darfst sie schon vorher in der Club-App abrufen – sonst kommt sie zur geplanten Zeit.`,
    url: `${APP_URL}#nachricht=${g.thread_id}` }, `club-geplant-vorab:${g.id}`).catch(() => null);
}
// 2.520.0 KC-COMM-WARTEN (Wunsch Hansi „mehr als 5 Mails → Zeitverzögerung, damit web.de nicht zumacht“): Mails über der web.de-Grenze
// (5/Min., 40/Std.) bekommen im Communicator einen Warteplatz (status „queued“ + scheduled_for). Der Minuten-Zeitplan ruft diese Aktion auch,
// wenn nur wartende Mails fällig sind; dann arbeitet der Communicator sie ab (nach 15 Min. Wartezeit übernimmt dort gleich Brevo).
async function mailWarteschlange() {
  const { count } = await db.from("kc_communication_requests").select("id", { count: "exact", head: true }).eq("status", "queued").not("scheduled_for", "is", null).lte("scheduled_for", jetzt());
  if (!count) return { faellig: 0 };
  const r = await fetch(`${SUPA}/functions/v1/kc-communication-router`, { signal: AbortSignal.timeout(28000), method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${SERVICE}`, apikey: SERVICE }, body: JSON.stringify({ action: "warteschlange" }) });
  return await r.json().catch(() => ({ status: r.status }));
}
async function geplantSenden(g: any, ich: Ich) {
  const r = await aktionAusfuehren("nachricht_senden", { id: g.thread_id, text: g.text, wege: Array.isArray(g.wege) ? g.wege : ["push"], ...(g.wichtig ? { wichtig: true } : {}) },
    ich, new Request(APP_URL, { method: "POST" }), Date.now(), 0);
  if (!r.ok) { const j: any = await r.json().catch(() => ({})); throw new Fehler(txt(j?.error, 200) || `Nicht gesendet (${r.status}).`, r.status); }
}
async function geplantIch(personId: string): Promise<Ich | null> {
  const [{ data: pe }, { data: ro }] = await Promise.all([
    db.from("kc_core_people").select("person_id,display_name,given_name,preferred_name,active").eq("person_id", personId).maybeSingle(),
    db.from("kc_club_rollen").select("*").eq("person_id", personId).maybeSingle(),
  ]);
  return pe?.active ? ichAus(pe, ro ?? null) : null;
}
async function geplantFaelligLauf() {
  const z = { gesendet: 0, fehler: 0 };
  const { data: faellig } = await db.from("kc_club_geplant").select(GEPLANT_FELDER + ",person_id,status").eq("status", "offen").lte("senden_um", jetzt()).order("senden_um").limit(20);
  for (const g of faellig ?? []) {
    // erst „belegen“ (nächste Zeit bzw. fertig), dann senden – zwei Läufe gleichzeitig senden so nie doppelt
    const naechstes = geplantNaechstes(g.erste_um, g.wiederholung, new Date());
    const { data: belegt } = await db.from("kc_club_geplant").update(naechstes ? { senden_um: naechstes, geaendert_am: jetzt() } : { status: "fertig", geaendert_am: jetzt() })
      .eq("id", g.id).eq("status", "offen").eq("senden_um", g.senden_um).select("id");
    if (!belegt?.length) continue;
    try {
      const ich = await geplantIch(g.person_id);
      if (!ich) throw new Fehler("Absender ist nicht mehr aktiv.");
      if (!ich.admin && await sperreFuer(ich.person_id)) throw new Fehler("Absender ist im Moment gesperrt – nicht gesendet."); // KC-CLUB-RC-PRUEFUNG (20.10.2026): Sperre gilt auch für geplante Nachrichten
      await geplantSenden(g, ich);
      await db.from("kc_club_geplant").update({ anzahl: (g.anzahl || 0) + 1, letzter_fehler: null, gesendet_am: jetzt() }).eq("id", g.id);
      z.gesendet++;
    } catch (e) {
      const grund = txt((e as any)?.message || e, 200) || "Fehler";
      // einmalige Nachricht: als Fehler stehen lassen (der Absender sieht es im Chat und kann neu planen); Wiederholung läuft weiter
      await db.from("kc_club_geplant").update({ letzter_fehler: grund, ...(naechstes ? {} : { status: "fehler" }) }).eq("id", g.id);
      await protokoll(g.person_id, "geplant_fehler", { id: g.id, grund });
      z.fehler++;
    }
  }
  return z;
}

// KC-CLUB-PRIVATTERMIN (1.0.0): persönliche Einträge – immer nur die eigenen (person_id = ich)
async function privatListe(ich: Ich, von: string, bis?: string) {
  const felder = "id,titel,beginn,ende,ganztaegig,ort,notiz,erinnerung_min,wiederholung,wiederholung_bis,ausnahmen,startseite";
  const bisD = bis ? new Date(bis) : new Date(Date.now() + 500 * 86400000);
  let q = db.from("kc_club_privattermine").select(felder).eq("person_id", ich.person_id).eq("wiederholung", "keine").gte("beginn", von).order("beginn").limit(300);
  if (bis) q = q.lte("beginn", bis);
  const [{ data: einzel }, { data: reihen }] = await Promise.all([q,
    db.from("kc_club_privattermine").select(felder).eq("person_id", ich.person_id).neq("wiederholung", "keine").lte("beginn", bisD.toISOString())
      .or(`wiederholung_bis.is.null,wiederholung_bis.gte.${von.slice(0, 10)}`).limit(200)]);
  const out: any[] = [...(einzel ?? [])];
  // KC-CLUB-WIEDERHOLUNG (1.1.0): Reihen im Zeitraum ausrechnen; id bleibt die der Reihe, serienBeginn für „Ändern“
  for (const r of reihen ?? []) {
    const dauer = r.ende ? new Date(r.ende).getTime() - new Date(r.beginn).getTime() : 0;
    for (const b of wiederholungen(r.beginn, r.wiederholung, new Date(von), bisD, r.wiederholung_bis, r.ausnahmen || [], 400))
      out.push({ ...r, beginn: b, ende: r.ende ? new Date(new Date(b).getTime() + dauer).toISOString() : null, serienBeginn: r.beginn, serienEnde: r.ende });
  }
  return out.sort((a, b) => String(a.beginn).localeCompare(String(b.beginn))).slice(0, 600);
}

