        if (error || !neu) throw new Fehler("Die Änderung konnte nicht gespeichert werden.", 503);
        await db.from("kc_dp_stempel").update({ storniert_am: jetzt(), storniert_von: ich.person_id }).eq("id", alt.id).is("storniert_am", null);
