  const zug = (zug0 ?? []).filter((z: any) => !gesperrt.has(z.person_id));
  const mitglieder: Record<string, unknown> = {}, dbz = { netz: 0, puffer: 0, vorrat: 0 };
  let vorrat: unknown[] | null = null;
