    if (th[0] || th[1]) { const ts = await holen("kc_communication_threads", "id", (q) => q.or(`created_at.gt.${seit},updated_at.gt.${seit}`)); if (!passt(th, ts.length)) return voll("nicht_gefunden"); ts.forEach((t: any) => threads.add(t.id)); }
